/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170315-3","meetingId":"h29-c-budget","date":"2017年3月15日","dateIso":"2017-03-15","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を164件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２９年度品川区一般会計予算","agenda":"平成２９年度品川区一般会計予算","exchanges":[{"speaker":"松澤委員","kind":"質問・要望","question":"しかし、この６年間、一度も放射性物質が検出されていないとの報告を受けておりますが、これで間違いないのか確認したいと思います。今回、平成２９年度予算では、昨年の２５０万８,０００円から１２１万２,０００円と半減しておりますけれども、この内容についてお知らせいただきたいと思います。","respondent":"有馬学務課長","answer":"その結果、平成２９年度につきましては、全校年１回としておりましたストロンチウムの実施方法を見直して、これは３カ年で全校検査をするというような回数の見直しを行ったものです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"松澤委員","kind":"質問・要望","question":"さらに平成２６年度からは、１校当たり年間２回のこれまでの検査に加え、ストロンチウム検査を年間１回追加していますと書いてあります。セシウム・ヨウ素の検査については各学校、年２回実施しているということですけれども、そちらには手を加えないで、なぜストロンチウムの見直しをし、これによって費用が半減するのか、説明していただきたいと思います。","respondent":"有馬学務課長","answer":"何点かお尋ねいただきました。ストロンチウムの実施方法をなぜ見直したのかですけれども、委員ご指摘のとおり、ストロンチウムは水溶性のある放射性物質ということで、汚染水問題が出たときに始めたということで、平成２６年度から始めております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"今、伺いましたけれども、ということは、３年に１回にしましたということは、このまま３年間、結果的に続けてみる、続けるということなのでしょうか。その点をお聞きしたいと思います。","respondent":"有馬学務課長","answer":"今後、また汚染水の状況が変わったりしましたら、そのときは適切に判断してまいりたいと思います。現段階では、先ほど申し上げましたとおり、３年間に１度というような考えで実施したいと思ってはおりますが確定したものではございません。","voiceIndex":8,"id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"費用もかなり高額だということで、やはりこれは３年間に縛られることなく、どこかで見直されていくべきではないかと、これはお願いしておきたいと思います。次に、セシウム・ヨウ素について伺いたいと思います。検査費用が安価とはいえ、役割は終わったのではないのでしょうか。原発いじめをなくすためにも、しっかりと調査すべきではないかと思っていますけれども、ご見解をお伺いいたします。","respondent":"有馬学務課長","answer":"当然、ヨウ素・セシウムにつきましても検討を行いました。２３区の状況も見まして、今のところ、まだ半数以上の区で実施しているという状況もございまして、これについてはしばらく継続していこうという考えです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"今、出荷制限の現状について、様々な食材の中でも出荷制限があるというお話も聞いています。現状と、市場の食材の安全性はどのようになっているのかお聞きしたいと思います。","respondent":"有馬学務課長","answer":"基本的には、関東甲信越でもそういうことで出荷制限にかかっているものもあります。ただし、それはあくまでも出荷制限がかかっておりますので、市場に流通しているものは基本的には安全だとは認識しております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"松澤委員","kind":"質問・要望","question":"子どもたちの食の安全を守るということは当たり前のことなのです。食の安全を守るために実施してきた。その検査が、今回、一定の見直しをしたということは評価するのですけれど、やはり、検査をすれば安心だからということだけで、風評被害が広がる、そしていじめが広がるという現状の中では、しっかりと精査していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"つる委員","kind":"提案","question":"そこでなのですが、今現在、学校のトイレの洋式化を、品川区も一生懸命、推進していっていただいて、公明党からもそれを提案しているので、ぜひハード整備というところで促進していただきたいのですが、その上で、学校で大便をしない小学生が３割いるという調査を、この間、私も拝見しまして、その理由として、自分たちの家庭にある洋式便器とは違う和式があるから。","respondent":"村尾教育総合支援センター長","answer":"大便所のほうに入って、それに対して、いじめを受けた、または冷やかしを受けたというような報告については、いじめ調査、また、いじめアンケート等を含めて学校からこちらに上がってまいりますが、そういう件については。","voiceIndex":16,"id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"多分、おそらく、トイレで限られたエリア、そして個室というさらに限られたエリアという中で、お友達同士の感覚、様々な評価の仕方というか見方はあると思うのですが、私も実体験としてあるわけですから、また、そういう調査や、全国的に見ると、そういうところがあるというところでは、私は、冒頭申し上げたとおり、便育の取り組みが非常に大事ではないかと考えています。その絵が和式のトイレなのだと。","respondent":"村尾教育総合支援センター長","answer":"便育という言い方は、特に学校教育の中ではそんなに使ってはいないのですが、ただ実際に、小学校に入ったときに、新１年生にはガイダンスとして、トイレの使い方等をまずしっかり子どもたちに伝えます。","voiceIndex":18,"id":"exchange-008"},{"speaker":"つる委員","kind":"提案","question":"便器の色というのは、基本、白かと思うのですが、何で白かというのは、便の色を確認しやすくするために白になっているとも言われておりまして、また、便が便器について、なかなか流しても取れないという場合というのは、油分を多くとり過ぎている。機会を通じて様々提案してまいりたいと思います。笑いは庶民の知恵。なので、過去にも提案させていただきましたが、その後の検討状況を教えてください。","respondent":"村尾教育総合支援センター長","answer":"特に、ユーモアのセンスというのは、大変重要だったり、また授業のスパイスになることもありますので、またこれについては引き続き様々な形で、外部人材の活用であったり、また市民科のある１つの人間関係形成みたいなところで紹介できるのではないかと考えているところです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"改めてですけれど、表現能力・コミュニケーション能力を、確かな言葉の使い手としてということで、品川区でも教師の方にお伝えしているということも伺っておりますので、児童・生徒においてもお笑いの授業、また教員にとっても研修の中で、取り組んでいただけることを検討いただきたいと思います。なので、返却ボックスが、そういう大型図書でもちゃんと返せるような改善というのは対応できますでしょうか。","respondent":"木村品川図書館長","answer":"引き続きお知らせなどご案内を丁寧に進めてまいりたいと考えています。","voiceIndex":22,"id":"exchange-010"},{"speaker":"つる委員","kind":"提案","question":"これも以前、提案というか質問させていただきましたが、児童センターでの読み聞かせなどを行っているお母さんたち、そのサポート等も含めて、図書館での取り次ぎサービスの提案をさせていただきましたが、その後の検討状況を教えてください。","respondent":"木村品川図書館長","answer":"そういうものと何か連携して、ボランティアの方に重いものを持って運ばせないような形がうまくとれるかどうか、引き続き研究してまいりたいと考えています。","voiceIndex":24,"id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"次に脊柱側わん検診ですが、これについては、まず現在、今年度からということで、実施状況について教えてください。","respondent":"有馬学務課長","answer":"脊柱側わん症の、いわゆるモアレ検査というものを今年度から行いました。対象は５年生・７年生ということで、成長が著しい時期のお子さんということで設定して行いました。受診率はほぼ１００％に近いという形になってあります。","voiceIndex":26,"id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"治療が必要な生徒がいたのかどうかなど、傾向性の部分も教えてください。","respondent":"有馬学務課長","answer":"中学生のほうは１,５５４人のうち２６人ということで、１.６７％が２次検診です。その結果、最終的に要治療となりましたのが、小学生で８名、０.３５％と中学生で２０名、１.２８％の合計２８名で０.７３％となっています。","voiceIndex":28,"id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"モアレ検査を提案させていただいて導入していただいたわけでありますけれども、結果として脊柱側わん症は、その後の生活に大きな支障のない形につなげていただくことが大事かと思いますので、女子生徒、児童・生徒等に対する様々な配慮も、当然、今年度から始めていただいて、現在もやっていただいていると思うのですが、そうしたことにもしっかりと配慮していただきながらお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"３６７ページ、いじめ防止対策費にかかわって、ＬＧＢＴなど、子どもたちのセクシュアルマイノリティーの悩みについて伺いたいと思います。性的マイノリティーの子どもたちのいじめ被害について、なぜ多い傾向があるのか、教育委員会の見解を伺います。性の多様性について子どもたちが小・中学校で学ぶ機会は、どのような場があるのか、現状を伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"そういうときに、どうしても若干、排他的な言動をしてしまう。それは決して悪気があるわけではなく、間違えた言動ではあるのですが、そういうところも含めて、子どもたちに対しては、正しい認識・知識を持たせていかなければいけないかと考えているところです。","voiceIndex":32,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"私にとっては、もう３０年も前のことですけれどもＬＧＢＴなど性の多様性について、当時は授業で異性愛を前提とし、体と心の性は一致していることが前提の授業だったのが、当時の学習指導要領を伺いたいと思います。そして、現在はどうなのか。現在は授業では取り扱っていないということですけれども、今後も含めて授業の中でどのように取り扱っていくのか、お考えも伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"１点目ですけれども、ＬＧＢＴというような、概念というのですか、認識が起きたのは、まさにそんなに昔ではなくて、本当にごく最近の考え方だと捉えております。","voiceIndex":34,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"トランスジェンダーは３００人に１人、およそ中学校に１人と、とても身近な存在です。とても、性の多様性についてしっかりと学ぶ機会をつくっていくことが大事だと思いますけれども、まずは学校の図書室について、この委員会でも２校に図書の配置がされたとご説明がありましたが、その学校はどこかということと、私は全ての小・中学校で図書の配置と啓発ポスターの掲示を求めますけれども、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"教材の作成等につきましても同様に、東京都の動き、また国の動きを含めまして、ＬＧＢＴにつきましては当然、教育の大きな１つの課題だと受けとめておりますので、そういうところで連携しながら進めていければと考えています。","voiceIndex":36,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"国や都との連携とともに、品川区でも独自に進めていただきたいと私は思います。２０１３年のホワイトリボンキャンペーンの調査では、子ども時代に何らかの形でいじめや暴力の経験があったと答えたのが７割とあります。伺いますけれども、体が男性で心が女性のトランスジェンダーの場合、学校でなぜこのような傾向があるのか、教育委員会の見解を伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"ほぼ品川区の教員がＬＧＢＴについては十分理解して、もしそういう子どもがいた場合、きちんとした個別対応ができるような体制、また管理職を中心としたサポート体制も組めるような体制を今とっておりますので、今後とも、いじめ。","voiceIndex":38,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"恋愛対象は必ず異性に向く。」ということへの誤解が、子どもをはじめ、社会全体に存在しているからではないでしょうか。いじめ克服へ、多様な性を学ぶ教材の作成や授業の実施について、まずは教育委員会でもチームを作って、抜本的に体制を強めていくことが必要だと思いますけれども、チームを作ることはいかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"当然、本区では、市民科という教科の中で人格形成をしており、今、市民科の中で、相手を認めることの大切さなどの単元を通して、いわゆる多様性については教えてきておりますので、今後、これについては、国の動き、また学習指導要領が今度、新しいものが出ますので。","voiceIndex":40,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"例えばトランスジェンダーの子どもの場合は、制服をどうするのか、修学旅行のお風呂をどうするのか、こういった悩みは深刻です。それだけに、性の多様性について正しく学ぶ授業について、学習指導要領の改訂はもちろん、品川区小中一貫教育要領にまずはしっかりと位置づけることが必要だと思いますけれども、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"その後に、子どもたちに対してどのような形で正しい認識を教えていくか、また対応について考えていくかにつきましては、繰り返しになりますが、今後、市民科の中でどのような扱いをしていくかについて検討したいと考えております。","voiceIndex":42,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"冒頭に、テレビの番組についてもお話がありましたけれども、子どもたちは学校で教わらなくてもテレビなどを通じて、日々間違った理解を与える情報にさらされております。こうした情報に、子どもたちは、笑っていい、またふざけ合っていいといった誤解も与えておりますので、この問題は私は緊急性があると思いますので、ぜひ積極的に、教材や授業で取り上げていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-021"},{"speaker":"木村委員","kind":"意見","question":"３６７ページのいじめ防止対策費、３６９ページの、まちの人々に学ぶ授業経費、３７５ページの８３運動経費からです。最初に３６７ページのいじめ防止対策費ですけれども、品川区いじめ防止対策推進条例の一番上にあります、「いじめは重大な人権侵害であり、決して許されません。現在のいじめと、理事者の皆さんの頃のいじめの違いというものは、どのように変わってきたと思いますか、お聞かせください。","respondent":"村尾教育総合支援センター長","answer":"いじめに関する認識の変化というようなご質問だと思います。現在もそうですし、以前からも、やはりいじめの原因として多いのは、悪口、それから嫌がらせ等が、やはりずっと子どもたちの中のいじめとして、代表的なものとして挙げられております。","voiceIndex":46,"id":"exchange-022"},{"speaker":"木村委員","kind":"質問","question":"今現在、インターネットというのがありますけれども、我々のころには、このインターネットというのはありませんでしたから、陰湿ないじめというものはあまりありませんでしたけれども、いじめ防止には、早期発見、早期解決、地域社会が一丸となってとありますけれども、現在のいじめにおける、今現在、品川区の事例というのでしょうか、そして、どのようにそれを解決できたのか、ご紹介ください。","respondent":"村尾教育総合支援センター長","answer":"取り組みにつきましては、各学校、そして学校支援チームのＨＥＡＲＴＳが学校のほうに伺ったりしながら、それぞれ個別に子どもたちの話を聞き、また内容を確認し、その後、解決するまで、また継続観察をするなど、今、きめ細やかな対応しています。","voiceIndex":48,"id":"exchange-023"},{"speaker":"木村委員","kind":"質問","question":"私たちのころには、先生は、怖い先生というものが必ず１人や２人はいましたし、毅然とした対応だった記憶があります。学校での教師は父親であり母親であるべきですし、生徒たちの前では毅然とした態度で振る舞ってほしいと思っています。家庭での教育あり、また学校での教育というものがあって、人に優しくできるのではないかと考えますけれども、どのように考えているでしょうか、お聞かせください。","respondent":"村尾教育総合支援センター長","answer":"一方、先生方は、子どもたちとの信頼関係を築くことも優先的に考えておりまして、何か心配なこと、それから悩みがありましたら、とにかく相談できるような関係性をしっかりつくるような体制ということで、毅然とした態度でいじめ防止をしながら。","voiceIndex":50,"id":"exchange-024"},{"speaker":"木村委員","kind":"質問・要望","question":"頑張っていただきたいと思います。次に３６９ページの上から９行目、まちの人々に学ぶ授業経費からですけれども、１つのことに精通した方々の経験談は何物にもかえられないし、学問では得られない貴重な時間も共有できるすばらしい体験ですけれども、このことに対して行政としてはどのように思いますか、お聞かせください。","respondent":"熊谷指導課長","answer":"家庭や地域の方々とともに子どもたちを一緒に育てていくという、まさにそういった視点に立った、まちの人々に学ぶ授業ですけれども、やはり私ども教員だけでは深めることができない学習活動というのが多々あります。","voiceIndex":52,"id":"exchange-025"},{"speaker":"木村委員","kind":"意見","question":"次に３７１ページ、ワンミニッツエクササイズからですけれども、子どもの体力・運動能力は、昭和６０年ごろから現在まで低下傾向が続いておりますけれども、体力調査における東京都の中学校の結果は全国的にも低位置にあり、品川区の小学生は向上しているものの、中学生では、その平均をほぼ全ての種目で下回っているという現状だそうです。","respondent":"村尾教育総合支援センター長","answer":"現在の成果というようなご質問ですが、実際、今年度はモデル校実施になりますけれども、毎日運動した子どもというのが、平成２７年度が２５％に対して、本年度は４０％ということで、やはり運動習慣が拡大しているかと考えているところです。","voiceIndex":54,"id":"exchange-026"},{"speaker":"木村委員","kind":"意見","question":"３７５ページの下から７行目、８３運動なのですけれども、これは子どもたちの登下校の時間帯において、地域の住民や保護者が、散歩や買い物の中で無理なくこなせる防犯活動とありますけれども、その中で、子どもたちが下校時間に、散歩や買い物をするわけですけれども、無理なく活動するとありますけれども、地域の住民は午後３時から、そして朝の８時ごろ散歩とありますけれども。","respondent":"品川庶務課長","answer":"８３運動のほうですが、教育委員会としましても、毎年、予算化しておりまして、啓発グッズ等をつくる費用で支援をしております。","voiceIndex":56,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"私からは、３８５ページ、学校運営費の校具費について、３９３ページ、学校改築推進経費、また時間があれば３７５ページ、文化財保護事業における指定文化財についてお伺いいたします。通常の校具、黒板等の備品があると思うのですけれども、通常、備品を入れかえるときの交換・更新作業はどのようにやっていますでしょうか。きちんと品質の保持などは、配慮しているのでしょうか。そこをお伺いいたします。","respondent":"有馬学務課長","answer":"校具に関するお尋ねですけれども、一般的に机や椅子、黒板というような、今お尋ねのものにつきましては、取りかえるに当たりましては、まず学校のほうに、老朽度といいますか、取りかえの希望調査をまず行います。","voiceIndex":59,"id":"exchange-028"},{"speaker":"筒井委員","kind":"提案","question":"実際どういうことが行われているかといいますと、まず黒板工事では、工法によるコストダウンが行われております。仕様変更の提案があった場合は、複数の専門業者、第三者の目からアドバイスを受けた上で決定すべきです。品川区としても、今述べたような問題解決のための提案の内容を、契約条項に入れる、入札条件に入れるべきだと考えますけれども、区のお考えはいかがでしょうか、お知らせください。","respondent":"篠田学校計画担当課長","answer":"こちらのほう、例えば今お話がございましたような、素材ですとか厚みですとか仕上げですとか、かなり細かいところまでを設計に落とし込みまして、それを工事業者が施工図に落とし込んで、実際に工事を実施していく。","voiceIndex":61,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"特に黒板などというものは、おそらく学校にいるとき一番長く見るもの、接するものですから、これは当初指定した要求仕様を最後まで守っていたという厳しいチェックを、区としてもぜひとも行っていただきたいと考えております。最初に指定した要求書を安易にひっくり返さないよう、厳しいチェックの目を向けていただきたいのですけれども、品川区のお考えとしてはいかがでしょうか。","respondent":"小林施設整備課長","answer":"そちらのほうでまず現場の管理をして、あと施設整備課の職員も含めて最終的な完了検査というのをやっております。","voiceIndex":63,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"ＶＥ仕様、同等品という変更をした仕様というのは、実際、設計事務所まで行っていない、報告が届いていない可能性もありますので、ぜひともメーカーなどの専門業者のチェックの目を入れていただきたいと考えております。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-031"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"私からは、３６３ページ、教職員福利厚生費の中の教職員健康管理費、３７１ページ、区内開催・応援３競技体験教室、３７５ページ、ＰＴＡ活動支援のことを質問させていただきたいと思います。初めに、教職員健康管理費についてお伺いしたいと思います。事務事業評価の中では、教職員の健康診断は法律で受診義務が定められているということです。よろしくお願いします。","respondent":"品川庶務課長","answer":"教職員の健康管理ですが、定期健康診断につきましては、平成２６年、平成２７年と、両方とも受診率１００％となっています。それから本年度、平成２８年についても、ほぼ１００％に近くなっておりますので、月末までには１００％にいくと考えています。","voiceIndex":67,"id":"exchange-032"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１００％ということで了解いたしました。これは私の知っている例なのですけれども、数年前、１０年ぐらい前になると思うのですけれども、先生が朝、出勤している途中に駅まで到着して、その後改札から出られない、学校に入っていけない先生が過去にいらっしゃいました。心のケアについてお知らせいただきたいと思います。よろしくお願いします。","respondent":"品川庶務課長","answer":"職員のメンタルヘルスの件ですが、平成２４年度から品川区独自でストレスチェックを行っております。","voiceIndex":69,"id":"exchange-033"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで、新卒の先生だけではないですけれども、特に新卒の先生はそういった心のストレスがあると思うのですけれども、そういった新卒の先生に対しても、取り組みは、その学校に所属している学校長や副校長などが、ベテランの先生も含めて対応されてから、そういった診療をされるという認識でよろしいのでしょうか。よろしくお願いします。","respondent":"品川庶務課長","answer":"ストレスの原因が上司などという場合については、やはり学校長、副校長を通じてというわけにもいきませんので、そういった、ケース・バイ・ケースによって、上司である学校長、副校長を通したり。","voiceIndex":71,"id":"exchange-034"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３７１ページ、区内開催・応援３競技体験教室のことをお伺いさせてもらいます。そういった障害者スポーツへの理解を深めるということで、区内３競技を区内全校で、ホッケー、ビーチバレー、ブラインドサッカーの体験教室をやると思うのですけれども、それぞれ３競技ありますので、そういった振り分けは今後、検討している段階だと思いますが、今現在の状況をお知らせいただきたいと思います。","respondent":"熊谷指導課長","answer":"平成２８年度はブラインドサッカーが１６校、そしてホッケーは５校で実施しております。平成２９年度からは、毎年、各校１種目ずつローテーションで実施いたしまして、平成３１年度までに全ての学校で３競技の体験教室を行っていく予定です。","voiceIndex":73,"id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"平成３１年度までに全校で３競技含めてやるということで、障害者スポーツというこだわりではなくても、スポーツの理解を深めるということでも、ぜひ子どもたちにも指導をよろしくお願いしたいと思います。続きまして、３７５ページ、ＰＴＡ活動支援について、関連した話をさせていただきたいと思います。けれども、その辺のところの認識を教えていただければと考えています。","respondent":"熊谷指導課長","answer":"マラソン大会等に教員が土日に出ることですけれども、それにつきましては勤務として振り替えることができますので、子どもたちの応援をたくさんしてもらって、そして教員の力にもそれが返ってくると思いますので、ぜひ参加させていきたいと考えています。","voiceIndex":75,"id":"exchange-036"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ、各小学校の校長を含めて、啓発というか、ぜひ参加というか、応援に来ていただきたいと考えています。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"放射性物質検査について伺います。そして、予算の減額については先ほど伺いました。その確認です。３年に１回の根拠が、在学中に１回当たる率でいいだろうという答弁でしたが、もう少しここを詳しく教えてください。そして、あとストロンチウムの検査で、汚染水の状況を見てということも伺いました。その検査の回数が、もとに戻ることなどはないのかということも、重ねてお伺いいたします。","respondent":"有馬学務課長","answer":"これについては、平成２９年度も平成２８年度と同様に行っていく予定です。それから、ストロンチウム検査を３年で１巡にしたということの理由ですけれども、これについては様々私どもも検討いたしました。","voiceIndex":79,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"ストロンチウム検査の仕組みなのですけれど、同じ給食食材を使っている学校ごとにストロンチウム検査が行われるといったことだったら、保護者からも不安の声や不公平感の声というのは上がらないとは思うのです。不公平感が生まれないような仕組みができているのかということが聞きたかったので、そこを伺いたいと思います。","respondent":"有馬学務課長","answer":"そういう意味だと、今までどおり、年１回、各学校でやっていたという意味では公平だったですけれども、これまで３年間やってまいりました。そこで一度も検査が出ていない。それから、汚染水問題で始めたストロンチウムについて、海産物についての出荷停止の割合が減ってきた。","voiceIndex":81,"id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"時間の関係で先にいきます。３月１１日のＮＨＫでも、福島県に対する風評被害を払拭するために、福島県の海で魚をとり、計測し、数値を公表している方が紹介されていました。生活者ネットワークでは、２０１６年に福島県へ視察に行き、農業の生産者の方の声も聞きました。そこでもやはり、消費者の立場でも、検査して、その計測結果を見て判断することは大切だと私たちは伺いました。見解を伺います。","respondent":"有馬学務課長","answer":"出荷停止の状況については、これは厚生労働省のホームページにも出ていますけれども、毎年やはり件数的には、基準値を超える出荷物というのが減ってきているという状況が１つあります。","voiceIndex":83,"id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"基準値についてのお話がありました。次の質問へ移ります。２０１６年度予算特別委員会でＬＧＢＴ対応の質問を幾つかしたときには、それぞれ前向きなご答弁だったと理解しております。その中で、教育総合支援センター長は、「ＬＧＢＴの子どもたちへきめ細やかな対応をするには、何よりもまずは教員への研修が第一」と答弁されていますが、現時点で教職員への研修はどの程度進んでいるのか伺います。","respondent":"村尾教育総合支援センター長","answer":"１点目につきましては、人権・同和教育研修会ということで、各学校から１名参加し、そこで資料等に基づく研修、また同様に、そういう資料に基づきまして養護教諭の研修、そして区で行っている、巡回相談員を対象とした連絡会での研修、また特別支援教育コーディネーター。","voiceIndex":85,"id":"exchange-041"},{"speaker":"田中委員","kind":"質問","question":"ＬＧＢＴに特化した教員向けの研修だったのでしょうか。もう一回、教えていただけますか。","respondent":"村尾教育総合支援センター長","answer":"ＬＧＢＴということで、性的マイノリティーに関する人権を含めての研修です。","voiceIndex":87,"id":"exchange-042"},{"speaker":"田中委員","kind":"質問","question":"２０１６年度予算特別委員会のときに、ＬＧＢＴの子どもへの対応を伺ったところ、ＬＧＢＴの子どもたちへの対応は、東京都、教育委員会の動向を見て、区も同調し、進めていくということを伺いました。都からそれにかかわる児童・生徒への支援という部分で通知が来ております。具体的に挙げていただいた細かな個別の配慮はどの程度達成されているのでしょうか、伺います。","respondent":"村尾教育総合支援センター長","answer":"今のご質問ですけれども、教職員の研修を含め、環境整備ということで、各学校、対象の児童・生徒がおりましたら、それぞれ各学校においてサポートチームをつくり、また環境整備、また保護者への対応、そして相談体制の充実ということで、それにつきましては各学校。","voiceIndex":89,"id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"今回の予算委員会の補正の中でも、学校のトイレ改修の話題がたくさん出ました。ＬＧＢＴの子どもへのトイレの配慮というのがとても重要だと思います。改修の設計の中にそのような視点は当然入れていただいていると思いますが、区としての見解があればお知らせください。相談機能づくりは本当に必要です。現在の相談機能の配置状況と、子どもたちへのメッセージはどのように発信されているのか伺います。","respondent":"品川庶務課長、村尾教育総合支援センター長","answer":"トイレの件ですが、改築する学校については、必ず、だれでもトイレというものを設置しておりますので、そういうもので対応しているという状況です。そういう子どもたちに対しても偏見や差別をなくす等、市民科の中でも、授業でまさに取り組んでいるところですので、子どもたちに個別対応、また受容的な対応ということで、一人一人、十分にきめ細やかなものができるよう配慮しています。","voiceIndex":91,"id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"自分が否定されていない、存在してもいいというメッセージを当事者の子どもたちに伝えることは、子どもの不登校、自殺、いじめ回避にもつながります。学校いじめ防止基本方針について伺います。いじめ防止対策推進法が制定され、その中で、各学校は、学校いじめ防止基本方針を策定することが求められました。現在、法律に基づいて、学校の基本方針策定状況はどの程度、進んでいるのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"各学校におけるいじめ防止基本方針の状況というようなご質問です。これは、いじめ防止対策推進法に規定された１３条で、学校において、いじめ防止基本方針を定めることとなっておりますので、当然、全ての学校が現在、この防止基本方針を持っているところです。","voiceIndex":94,"id":"exchange-045"},{"speaker":"田中委員","kind":"質問・要望","question":"つまり、先にできた法にあるとおりに、学校いじめ防止基本方針を各学校が作成したら、今度は品川区教育委員会から、後からできた品川区いじめ防止対策推進基本方針の趣旨を踏まえた学校いじめ防止基本方針をつくるように言ってきたからではないかと思うのですけれど、どうしてこのような２度手間になるような事態になったのか、教育委員会の品川区いじめ防止対策推進基本方針ができるまで。","respondent":"村尾教育総合支援センター長","answer":"その中に、様々、いじめ根絶協議会だったり、また区で行っている様々な取り組みを、この条例に盛り込みましたので、それを踏まえて各学校が、児童・生徒、保護者、そして地域の皆様に、学校のいじめ防止の基本的な考え方をお約束するという趣旨で。","voiceIndex":96,"id":"exchange-046"},{"speaker":"田中委員","kind":"質問","question":"各学校の学校いじめ防止基本方針を拝見させていただきました。そうしたら、本当に各学校によって特色が出ている方針と、あと、ちょっと学校の名前を変えただけの基本方針であったりというのもありました。これだと、何か品川区の定めた基本方針に沿わなければいけないというふうに、何となく思ってしまうのですけれど、そのところはいかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"現在、各学校がつくっております基本方針については、まさに国のものをベースにつくっておりますので、どうしても、やはり基本的なベースは似ているかと考えています。","voiceIndex":98,"id":"exchange-047"},{"speaker":"田中委員","kind":"質問","question":"学校の先生方はとても忙しいと認識しています。学校に余計な負荷をかけるべきではないという立場と各学校の特色も踏まえて作成されたほうがいいのではないかという意味で質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問・要望","question":"「プラン２１」の品川教育検討なのですけれども、先日の一般質問でもやりましたが、ＡＩ時代における教育についてということで、この前の日曜日に新聞社主催の「ＡＩ時代に求められる教育とは」というフォーラムに参加してまいりました。一部、京陽小学校で行われていたプログラミング教育について、このフォーラムでも実は紹介されたのですけれども、それについて教えてください。","respondent":"熊谷指導課長","answer":"未知の状況にも対応できる、そういった力、思考力・判断力・表現力を活かした、そういった能力が必要であると考えております。","voiceIndex":102,"id":"exchange-049"},{"speaker":"あくつ委員","kind":"意見","question":"これからすごい時代に突入するというご認識を教育委員会がお持ちで、どういう未知の状況に対応する能力を養っていくのか、ということでありました。すみません。京陽小学校について、ご答弁がまだでしたね。","respondent":"村尾教育総合支援センター長","answer":"本区においては、プログラミング教育におきましては、委員のご指摘のとおり、京陽小学校で３年間の研究を進めてまいりました。","voiceIndex":104,"id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問","question":"ＳＴＥＭ教育とＳＴＥＡＭ教育はオバマ大統領がかなりアメリカで進めたようですけれども、これは見たら、先ほどの京陽小学校で進めたＣＡＮＶＡＳというＮＰＯ法人、ここも日本中でこのＳＴＥＭ教育を、今、広げつつあると、こんな表記もあったのですけれども、今回の京陽小学校の取り組みは、このＳＴＥＭ教育の一環として見ていいのかどうか、お伺いします。","respondent":"村尾教育総合支援センター長","answer":"これは委員ご提案のＳＴＥＭ教育という、１つの大きな、総合的な理科系の教育の考え方ではありますけれども、プログラミング教育については大きくつながるものではありますし、次期学習指導要領においても、算数、理科、また総合的学習。","voiceIndex":106,"id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今、小学生や中学生、子どもたちに求められていく力というのは、これからわからないものに対して、そのフォーラムなどに来ている人は、自分の子どもの教育に対してみんな興味を持っていますから、ではどういう職がいいのですかという質問をみんな投げかけるのですけれども、そんなことはわかりませんと。そのためにどういう力を養成していくのか、改めて伺いたいと思います。","respondent":"熊谷指導課長","answer":"そういった将来設計能力も必要ですし、また生きていくためには、その基本となる学力、体力、そして心です。知・徳・体をしっかり持った上で、品川区の生き抜く力を育てていきたいと考えています。その上で、品川教育検討委員会を進めてまいりたいと考えています。","voiceIndex":108,"id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３７３ページの人権教育というところで伺います。人権教育の調査研究受託は毎年ついている同和教育の委託だと思うのですけれども、品川区において、障害者や、先ほどご答弁にもありましたけれど、多様性に関する理解力、差別解消といったものを学ぶ時間というのはどこにあるのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"もう一つの大きな取り組みとしては、副籍制度というものがございまして、特別支援学校の子どもたちと、在籍というか、その学区に住んでいる子どもたちとの交流ということで、子どもたちが、様々な形で。","voiceIndex":110,"id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それで、その関係で伺いたいのですが、品川区の保育の人口が平成５０年まで増えるという見込みでお話がありましたけれども、勘違いしてはならないのは、これは若年層の人口の増加であって、全体の流れではないということです。それで、ＮＨＫに、この根拠は何なのですかと私も問い合わせをしましたら、２０１３年の東京都の調査ということだったので、それを調べましたら、確かにそのとおりになっていました。","respondent":"柏原企画調整課長","answer":"それで、品川区の人口推計で言いますと、平成３９年がピークということで、そこから緩やかに減るという状況で推計を出しています。","voiceIndex":112,"id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問・要望","question":"平成３２年ですから、平成３９年から減り始めると。確認させていただきたいのは、保育のニーズに応えることです。ただし一方で、これも長期計画の範囲内ですから、平成３９年まで、予想を超えて若年人口が増えていくとしている。この犯人は、意思疎通が困難な人が誰なのかをわざわざ職員に確認してから、１９人の知的障害者の方を選択して殺害した。この点について教育委員会にお聞きしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"そういうものをしっかりやりながら、子どもたちに、正しい認識だけではなく、豊かな人間性や社会性というものをしっかりと身につけていこうと考えております。","voiceIndex":114,"id":"exchange-055"},{"speaker":"横山委員","kind":"質問","question":"私からは、３７１ページ、品川英語力向上推進プラン、オリンピック・パラリンピック教育推進事業、３６７ページ、いじめ防止対策費についてお伺いいたします。１点目は、いじめ防止対策費についてお伺いいたします。ＨＥＡＲＴＳのカウンセラーは、ＬＩＮＥやＳＮＳ等のネットリテラシーをどのぐらいお持ちでいらっしゃる方々なのでしょうか。東京都教育委員会の３月９日のプレスリリースにて、「考えよう！","respondent":"村尾教育総合支援センター長","answer":"２点目です。都でプレスリリースしたアプリの部分ですけれども、まだこちらのほうに具体的な資料やパンフレットは届いてはいないのですが、都のほうから出されたものにつきましては、３つのアプリケーションを３月に公開予定と聞いております。","voiceIndex":119,"id":"exchange-056"},{"speaker":"横山委員","kind":"質問・要望","question":"今の小学生、中学生なのですけれども、電話での相談よりも、実際に使っているＬＩＮＥでのトラブルに関しては、例えばスクリーンショットなどをとって、それをそのまま相談に使用する、または、メールなど、そういう入り口のほうが、相談のしやすさですとか情報の共有のしやすさということもあるとお聞きしておりますので、都のアプリが開発されるということで、そういったものも活用したり。","respondent":"村尾教育総合支援センター長","answer":"その専門の機関と、教育委員会としても連携を図りながら、様々な課題に対して、やはり専門的な知識がどうしても必要になりますので、相談体制をしっかりと置きながら、子どもたちのトラブル解消に向けて取り組んでいこうと考えています。","voiceIndex":121,"id":"exchange-057"},{"speaker":"横山委員","kind":"質問","question":"児童相談所移管推進に関連して、一時保護児の学校の扱いと、学校と一時保護所の連携についても、現状どうなっているのか教えてください。この点でも、都ではなく区が推進していくというところ、効果が出てくるところではないかと私は考えているのですけれども、学校の扱いと学校との連携について、区だからこそできる部分が大いにあり、可能性を感じておりますが、区のお考えをお聞かせください。","respondent":"村尾教育総合支援センター長","answer":"現在、そのような状況で学校と取り組みを進めているところです。","voiceIndex":123,"id":"exchange-058"},{"speaker":"横山委員","kind":"質問・要望","question":"要望で終わらせていただきます。２点目は、品川英語力推進プラン、オリンピック・パラリンピック教育推進事業の国際理解についてお伺いいたします。学習指導要領の改訂に当たり、品川区の英語教育、国際理解教育、どのように対応する予定でしょうか。現在の品川区独自の小学校英語教育のカリキュラム作成に、青山学院大学、アレン玉井教授が携わっておりますが、どのような経緯で導入されたのでしょうか。","respondent":"熊谷指導課長","answer":"平成３０年度には、５・６年生には７０時間ということで、全校実施を行っていく予定です。","voiceIndex":127,"id":"exchange-059"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ、品川区の今まで進めてきた英語教育に加えて、今回の改訂を含めまして進めていただければと思います。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３７５ページの教科書採択事務、３６３ページの職員給与費、教員の多忙化に関して質問をします。教科書採択事務なのですが、道徳の教科書採択が始まると聞いています。今後のスケジュールを教えていただきたいのが１点です。品川区は市民科という教科がありますけれども、文部科学省の道徳の教科化と市民科との整合性をどう考えているのか、お伺いいたします。","respondent":"村尾教育総合支援センター長","answer":"１点目の教科書採択のスケジュールです。来年度、道徳の教科所の採択に当たりましては、まず５月ごろに、教科用図書調査検討委員会という、これまでの教科書採択と同じような仕組みで、まず組織を立ち上げます。","voiceIndex":131,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"道徳の教科化について、ちょっと根本的な問題をお伺いしたいと思います。１つは、この国定教科書化のことについてです。２点目は、評価をどうしていくのかというところです。品川区は、市民科の教科書を使っているわけですけれども、この国定教科書化と、あともう一つ、内心の自由に踏み込んだ評価を教員がしていかなければならないという、このことに対して、区教育委員会の所見をお伺いしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"１点目、道徳の教科化という部分で、道徳教育の今回の目標の部分につきましては、子どもたちが自己の生き方を考え、主体的な判断のもとで行動し、そして自立した人間として他者とより良く生きるという、道徳性の育成というものを目指しているものですので。","voiceIndex":133,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問","question":"私は、今の安倍内閣の教育再生以来の動きからすると、やはり今までとは違って、新しい教育指導要領もできますので、内容的に変化していく、この危惧を持っているのですけれども、今までと変わらない状況の中で道徳をやっていけるのか、もう一度お伺いいたします。","respondent":"村尾教育総合支援センター長","answer":"繰り返しになりますけれども、市民科の中でも、これまでも道徳教育というのは十分、指導の中に入ってきておりますので、新しく道徳が教科になったとしても、これまでどおり品川区の市民科として、子どもたちの人間育成については進めていければと考えていますし、当然。","voiceIndex":135,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これから教科書の採択が、スケジュールも示されましたけれども、選定に当たって、ぜひ環境を整えていただきますように、この点は要望しておきますので、よろしくお願いいたします。続いて教員の多忙化のところなのですが、教職員が子どもたちにしっかりと向き合ってほしい、多忙化を何とか急いで解消していただきたいと思って質問します。多忙化の現状と課題をどのように認識されているのか、改めて伺います。","respondent":"熊谷指導課長","answer":"既にご答弁申し上げましたとおり、私が年間３回、校長とヒアリングを行って、その中で各学校の状況について、そして勤務実態について確認しています。","voiceIndex":137,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問・要望","question":"現状のところがちょっと一般論かと思って伺ったのですけれども、具体的につかんでいらっしゃるのでしょうか。平日は８時１５分から１６時４５分です。どのように時間を把握しているのか。そして月何時間になるのか。私は、過労死ラインを超えていないのか、とても心配しています。数字で教えていただきたいと思います。","respondent":"熊谷指導課長","answer":"実際には、土日の勤務状況の把握ということがございましたけれども、土日につきましても打刻はできますので、打刻ができないという状況はございません。","voiceIndex":139,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は現場の方から聞いております。学校の休日の日には打刻ができません。この実態、そういった中で打刻ができないと数字に残らないのです。それを、一体どこでどうやってつかんでいるのか、ぜひここを教えていただきたい。私は、教育長も課長も、現場の教職員の方々にも、一人一人が心身ともに元気でお仕事をしていただきたい。ぜひ、実態をどれだけつかんでいるのか、もう一回お伺いします。","respondent":"熊谷指導課長","answer":"先ほどご質問がございましたけれども、打刻ができないということにつきましては、土曜授業ですとか行事のときにできます。ですので、これにつきましては、勤務になっているときには打刻ができる状況にあります。","voiceIndex":141,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"意見","question":"土曜授業や行事のときではないのです。学校が休んでいるときにも仕事をしなくてはいけない。そして、そこで仕事をしているにもかかわらず、本人が記録をとらない限り、その人の仕事状況がわからないのです。こんな状況ではとてもいかないと思いますので、ぜひつかんでください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":143,"id":"exchange-067"},{"speaker":"松永委員","kind":"質問","question":"私からは、３６３ページの災害対策教職員待機寮管理費、３６５ページの生徒指導対策費の巡回相談員、そして３６７ページの、いじめ防止対策費について伺いたいと思います。この災害対策教職員につきまして、地震や災害、水害など、いつどこで起きるかわからない災害に対してどのようなシステムで行動されることになっているのでしょうか、伺います。","respondent":"熊谷指導課長","answer":"３回、防災訓練への参加が義務づけられているところですけれども、それをまた実際に、児童・生徒の防災訓練等、それから避難訓練等にも活用することで、教職員として子どもへの安全教育にそれを活用しています。","voiceIndex":145,"id":"exchange-068"},{"speaker":"松永委員","kind":"質問","question":"年３回ということなのですけれども、昨年、震度７クラスの地震が発生したことを想定して、１２月５日に防災訓練が行われました。浜川小学校でも行われたのですけれども、そのときに、児童の引き取り訓練や、スタンドパイプを使った放水訓練等が行われました。そのときに、教職員の方々はどのような形で防災訓練に参加されていたのか、そのことについて伺いたいと思います。","respondent":"熊谷指導課長","answer":"今のご質問ですけれども、直接、待機寮に入居している職員がそれに参加して、どのような動きをしたのかということはつかんでおりません。","voiceIndex":147,"id":"exchange-069"},{"speaker":"松永委員","kind":"質問・要望","question":"平成２９年度予算には、寮が２寮となっておりますけれども、現在何世帯住んでいて、災害対策の教職員が何人住んでいるのか、伺いたいと思います。","respondent":"熊谷指導課長","answer":"現在の入居者なのですけれども、まず、ゆたか寮ですけれども、ゆたか寮につきましては全部で１５世帯入居しています。人数としましては１５名入居しています。それから伊藤寮ですけれども、伊藤寮につきましては８世帯入居、そして入居者は８名となっています。","voiceIndex":149,"id":"exchange-070"},{"speaker":"松永委員","kind":"質問","question":"世帯数と人数が同じのため、もしかしたら、これは独身の方なのかというふうな感じには読み取れるのですけれども、その辺について改めて伺いたいと思います。災害ということで、消防署や、今日は消防団長がいらっしゃいますけれども、消防団、そして警察との連携について、どのような連携がとられているのか、また災害対策の教職員の男性と女性の割合がわかりましたら教えてください。","respondent":"熊谷指導課長","answer":"それから消防署、そして警察、消防団等との連携ですけれども、こちらにつきましては、入居者本人が所属する学校で防災訓練に参加するケースも多々ありますので、そういった中で、地域の警察、消防、消防団とのつながりの構築がなされていると聞いております。","voiceIndex":151,"id":"exchange-071"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ連携をとっていただいて、いつ起こるかわからない地震ですから、力を入れていただきたいと思います。次に、３６５ページの生徒指導対策費の巡回相談員１０名、３,０８９万５,０００円について伺いたいと思います。そこで、人数について伺います。本区では、昨年も同様、１０人となっておりますが、２３区内で比べまして１０名が妥当なのかどうか伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"学校の規模も違いますので、一概に多いか少ないかというのはあるのですけれども、現在、１０名で、各小・中、それから義務教育学校を巡回しながら対応はできていると考えているところです。","voiceIndex":153,"id":"exchange-072"},{"speaker":"松永委員","kind":"質問・要望","question":"平成２８年度予算特別委員会の中で、たしか私は、いじめ等根絶普及啓発事業の中で啓発バッジについて質問させていただいたのですけれども、今回の予算特別委員会で、先ほどちょっと説明があったのですけれども、条例改正のため普及啓発費が減ということで、これは普及啓発バッジ、またはポスター等というのはなくなってしまったのか、それについて少し伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"週に１回、それぞれ巡回相談員、そしてＨＥＡＲＴＳのチーフ会議も行いながら、特に重点的に行っていかなければいけない支援はどこだ、どういう形でやっているかということについても、お互いに協力しながら進めていく、そのような関係です。","voiceIndex":155,"id":"exchange-073"},{"speaker":"松永委員","kind":"質問","question":"いじめについてですけれども、最近、インターネットやＩＣＴ化が進んでいる中で、以前、目安箱というのを質問させていただいたのですが、目安箱の内容というか、実績、必要性があるのかどうかというのも改めて伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"ただ、その中でも、本当に切羽詰まったところで子どもが投書するということもありますので、昨年度同様、目安箱に投書されましたらセンターのほうに連絡が一報が来て、そして学校に行き当該の児童・生徒と話をしたりするような取り組みは、現在も進めているところです。","voiceIndex":157,"id":"exchange-074"},{"speaker":"松永委員","kind":"質問・要望","question":"最後に、３８０ページの学校管理費について伺います。そこで、教育委員会として、なぜ差がついているのかについて、どのように考えているのか伺います。あわせて将来性ですけれども、品川区では今現在、保育園をどんどん増やしていると思いますけれども、そうした中で、今後、保育園を卒業される方が小学校に上がった場合の、受け入れ体制について伺いたいと思います。","respondent":"有馬学務課長","answer":"今後は、各学校がそれぞれ良い教育に裏づけられた内容を進めていくことが大事だと考えています。就学人口につきましては、人口推計を毎年行っているところです。","voiceIndex":159,"id":"exchange-075"},{"speaker":"鈴木（博）委員","kind":"意見","question":"本日は、３６７ページのいじめ等防止プログラム経費に関連して自殺予防教育について、それと３８９ページの給食運営費に関連して、ノロウイルスによる集団食中毒、３９１ページの保健運営費に関連して、性教育、インフルエンザ罹患の中学生の転落事故についてお尋ねいたします。性感染症と性教育についてお尋ねします。","respondent":"村尾教育総合支援センター長","answer":"性感染への問題意識のご質問ですが、ＡＩＤＳおよび性感染症の部分につきましては、現在、増加傾向、また低年齢化ということがうたわれておりますので、これについては教育委員会として高い問題意識を持っております。","voiceIndex":162,"id":"exchange-076"},{"speaker":"鈴木（博）委員","kind":"質問","question":"現在の品川区の小学校・中学校・義務教育学校におきまして、性教育の実施状況、年間の授業数、授業の内容、それと性感染症の流行という状況のもとで、学校現場で、例えば校外の医療関係者による性教育の授業などは考えられていたり、現在行われているのでしょうか、ご説明をお願いします。","respondent":"村尾教育総合支援センター長","answer":"現在の、区内学校における性教育の状況ですが、実際には、４年生の保健体育でありますけれども「育ちゆく体と私」というところの２時間授業を含めまして、６年生での「病気の予防」のＡＩＤＳ、７年生におきましては、「性とどう向き合うか」ということで、性意識の変化。","voiceIndex":164,"id":"exchange-077"},{"speaker":"鈴木（博）委員","kind":"質問","question":"平成２０年１月１７日の中教審答申では、以下のような、健やかな体を育む教育の在り方に関する専門部会の見解を踏まえて、告示、公示されました。それで、この見解というのは、以下述べます。それで、性感染症が猛威を振るっている現状で、この答申は極めて妥当な見解だと思われますが、この見解に対する教育委員会のお立場も踏まえて、性感染症、性教育について、最後にまとめのご説明をお願いします。","respondent":"村尾教育総合支援センター長","answer":"国も様々な形で性感染につきましては予防対策を進めていると、こちらも認識しております。","voiceIndex":166,"id":"exchange-078"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２月に、ノロウイルスに汚染された刻みノリを食べた、立川市・小平市小学校の生徒・教職員１,０００人以上が、ノロウイルス胃腸炎を発病する大規模な食中毒が発生しました。今回の事例を踏まえて品川区ではどのような対応がなされているのでしょうか。ノロウイルス感染症を含む感染性胃腸炎に対する学校現場の今現在の対応についてもご説明をお願いいたします。","respondent":"有馬学務課長","answer":"過日、立川市で発生した集団食中毒に対する区の対応ですけれども、２月２１日の段階で、私どものほうから衛生管理の徹底に努めるようにという通知をまず出しています。その後、２月２７日に東京都から、夜間でしたけれども、刻みノリを使うなというような指示が来ました。","voiceIndex":168,"id":"exchange-079"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ノロウイルスの感染症を診断する方法としては、クイックナビ－ノロ２という、ふん便から調べる迅速診断の検査があるのですが、これは臨床の場では信頼性が低くてあまり評価されておりません。３歳未満、それから６５歳以上の高齢者しか保険適用にならないので、検査をした場合、実費になります。特に感染性胃腸炎の臨床検査については、現場ではどのように指導されているのでしょうか。","respondent":"有馬学務課長","answer":"日常的な予防対策としては、当然のことのように、トイレを使った後あるいは食事を作る前といったところは、きちんと手洗いをするようにと、従来からの指導に努めているです。","voiceIndex":170,"id":"exchange-080"},{"speaker":"鈴木（博）委員","kind":"質問","question":"非常に現場が冷静に対応されているということで安心しました。次にいきます。マスコミ報道に関連しまして、２月１４日、区内中学生が自宅マンションから転落死したという報道がありました。亡くなられた中学生、残されたご遺族の方に深い哀悼の意を表します。今回の事例の大まかな経過についてご説明をお願いします。","respondent":"村尾教育総合支援センター長","answer":"現在、子どもからの相談はありませんし、保護者からの問い合わせも特になく、学校も終業式を含めて予定どおり進んでいるという状況です。","voiceIndex":172,"id":"exchange-081"},{"speaker":"鈴木（博）委員","kind":"質問","question":"リレンザを服用したというような表現のニュースが多かったのですが、抗ウイルス剤については何か学校現場や教育委員会のほうで対応などはされたのでしょうか。","respondent":"有馬学務課長","answer":"２日間は特にそういう行動が多く見られるので、なるべく１人にさせないような配慮が必要だと言われているということ。それから、今言ったようなことを、ちゃんと学校内でも情報を共有してくださいというようなことを、校長会で伝えたです。","voiceIndex":174,"id":"exchange-082"},{"speaker":"西本委員","kind":"意見","question":"３６７ページの、いじめ防止の点で、福島県のほうから避難されている方がいらっしゃると思います。区内の小・中学校、高校、大学、どこまで把握できるかわかりませんけれども、原発に関するいじめがあるのか、ないのか、そういう調査をしたのかどうかお尋ねします。","respondent":"村尾教育総合支援センター長","answer":"すぐに、区内の同様の子どもたちの通っている学校にも連絡し、十分確認をとっていただいたところ、基本的にはそのような申し出もなく、学校のほうでも、それについては今後、十分気をつけていくようにということでお答えをいただいています。","voiceIndex":178,"id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"これは風評被害の影響だと強く思っておりますけれども、今回、この検査に対する方法を変えていただいたということなのですが、私は、もう６年過ぎている中で、それから現状の線量等の検査結果を踏まえますと、税金を使ってこれの検査をするという意味があるのかどうかということを非常に疑問に思っております。それについてのお考えをいただきたいと思います。","respondent":"有馬学務課長","answer":"あくまでも食の安全の確保ということです。それで、その立場において、やはり出荷停止の状況がまだあるということも一方で事実ですので、一気に廃止というのは、まだもう少し様子を見たいということで、今回はこういうご提案をさせていただいたところです。","voiceIndex":180,"id":"exchange-084"},{"speaker":"西本委員","kind":"質問","question":"出荷停止ということは、まず国としてきっちりとチェックしているということだと思うのです。それで、品川区の給食では、保育園・幼稚園もそうですけれども、チェックされているものを使っているのですよね。そこでチェックしていないものを使っているのですか。","respondent":"有馬学務課長","answer":"ただ、一方で、福島県に限らず、関東甲信越で、例えばキノコ類などで、まだそういうものが出ているということもありますので、安全を確保するために、一歩踏み込んでという形にはなりますけれども、それで実施してきたということです。","voiceIndex":182,"id":"exchange-085"},{"speaker":"西本委員","kind":"質問・要望","question":"福島産のものについては、逆に言うと、本当にこれはしっかりとやっているのです。ただ、では他の食材に対して疑いをどこまでかければいいのですかということになる。しかも、家庭における食材についてはどこまで皆さん注意されて買っているのでしょうか。ちゃんと食材の放射性物質のチェックをして、そういうものですよとラベルか何かあって、それだけしか使わないとか、そこまで注意しているのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"その辺を含めまして、各学校においてもその辺を十分に注視しながら、子どもたちへの対応を、今、進めているところです。","voiceIndex":184,"id":"exchange-086"},{"speaker":"西本委員","kind":"意見","question":"無気力でというのが多くなってきているのです。家族関係ということもあると、やはり、なかなか学校でそれを見るというのは難しいのかと思いますが、横のつながり等で対策チームを組むとか、様々なサポートをする体制などは研究されているのか、実際やられているのか、お知らせください。","respondent":"村尾教育総合支援センター長","answer":"ただ、それ以外にも、様々な、やはり子どもたちの抱えている問題というのは、一つ、二つではなく大変複合的なものと、こちらは捉えております。現在、対応といたしましては……。","voiceIndex":186,"id":"exchange-087"},{"speaker":"塚本委員","kind":"質問","question":"それから３９１ページ、学校保健費では、歯科矯正、かみ合わせの矯正について、それから時間があれば３８１ページの学校ＩＣＴ活用経費をお伺いしたいと思います。そういった中で、不登校というのが、今、非常に多くなってきていると感じています。そういったときに、保護者、生徒、そして学校という３者の中で、現状としてどういった対応をしていくような体制になっているのか、まずお伺いします。","respondent":"村尾教育総合支援センター長","answer":"年間、本年度は２回ではありますけれども、夕方６時から地域センターを借りて、不登校の保護者の方に来ていただいて、様々なディスカッションをするような会も、今後もう少し広げていかなければいけない、また保護者の支援が子どもの学校復帰にはとても重要かと考えていますので。","voiceIndex":189,"id":"exchange-088"},{"speaker":"塚本委員","kind":"質問・要望","question":"別室になった場合に、基本的には自習という形で、学校で不登校になりつつある生徒が過ごすというような状況になっていると思いますけれども、この自習という形が主流になっているのだとすれば、そういったことは良いことなのか、どうなのか、考え方としてどう思っていらっしゃるかお伺いしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"それ以外にも、やはり保健室もなかなか様々な子どもたちが出入りしますので、そういうときは、学校によっては図書室であったり、また特別教室を使って、子どもをそこで、様々な形で対応できるようにしているというのが一般的だと考えております。","voiceIndex":191,"id":"exchange-089"},{"speaker":"塚本委員","kind":"質問・要望","question":"では次に、学校保健費の歯科かみ合わせなのですけれども、平成２４年の我が会派の一般質問でこの問題を取り上げまして、そのときの答弁としては、まずは国の保険適用の動向を注視したいというご答弁でありました。それから今日に至るまで年数がたちましたけれども、やはり保護者からの、かみ合わせの状況で大変に心配だというようなことは、常々ご要望、お話があるところです。","respondent":"有馬学務課長","answer":"保険適用の関係につきましては、今のところ、まだ保険適用にはなっていないです。それで、申しわけございません。歯科の部分だけの統計は、今資料を持ち合わせてございません。","voiceIndex":193,"id":"exchange-090"},{"speaker":"塚本委員","kind":"質問・要望","question":"今持っていないというのは、どこかにあるのかもしれませんけれども、ぜひ、こういったところもしっかり把握していただいて、このご相談は大変多いので、現状をしっかり、適宜、適切な対応ができるように今後とも対応していただきたいと思いますので、よろしくお願いいたします。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-091"},{"speaker":"沢田委員","kind":"意見","question":"教育実習についてなのですけれども、教育実習の受け入れというのは、年間大体どれぐらい、最近されているのか、またどういった基準で品川区の学校に教育実習の学生が来ているのか、またそれからどのような先生方が教育実習の担当をされているのか、お聞かせください。","respondent":"熊谷指導課長","answer":"実習の受け入れですけれども、平成２８年度、品川区では、幼稚園２９名、小学校５１名、中学校２６名、受け入れてあります。","voiceIndex":197,"id":"exchange-092"},{"speaker":"沢田委員","kind":"意見","question":"先ほど、教育実習を受け入れる指針や、受け入れるときの体制は、校長先生が担当の教諭を決めるなどということでしたけれども、そういう方針的なものがしっかりあるのか、受け入れる先生たちの意識、学校の意識というのはどういう形で、新人の教育実習で学んでいる学生を受け入れるという意識で取り組まれているのか、その辺のお考えをお聞かせください。","respondent":"熊谷指導課長","answer":"特に、学生みずからが本当に教員に合っているのか、その適性を見分けるのも、この教育実習の場であると思っていますので、教育免許状の取得だけの理由で教育実習に来ている方も残念ながら中にはいるのですけれども、そういったことも踏まえながら。","voiceIndex":199,"id":"exchange-093"},{"speaker":"沢田委員","kind":"質問・要望","question":"まさに当然、そういう夢を持った子どもたち、免許を取るために来ている方もいるかもしれないけれど、そういった方たちをしっかり、品川区としても新たな教員として育てていっていただきたいと思います。どういった方が代替で来ているのか、どういった方を採用しているのか、教えてください。","respondent":"熊谷指導課長","answer":"人数ということなのですけれども、平成２９年１月１日現在で、小学校では育休代替教員が５３人、それから産休代替が７人、中学校では育休代替が３人、産休代替が１人、そして義務教育学校では育休代替が９人、産休代替が０人ということで、現在。","voiceIndex":201,"id":"exchange-094"},{"speaker":"沢田委員","kind":"意見","question":"結構な人数だと思うのです。そういった先生が産休や育休などで休んだときに、代替の教員について一定の基準を持って選んで採用しているとはいっても、その後、１年以上はいることもあるということだと思うのです。その質というのはやはり重要だと思うのですけれども、これはどういった研修体制を整えられていて、また代替で来るとすぐに授業をやると思うのです。","respondent":"熊谷指導課長","answer":"基本的には、校長、副校長を中心にサポート体制をしっかりとって、実際には子どもたちへの授業力向上に向けて支援しています。","voiceIndex":203,"id":"exchange-095"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういったサポートをしっかりやっていっていただきたいと思いますし、やはり学校、品川区で授業を受けるということで、代替の職員になったときに、代替の方というのは、やはり一時、教員を抜けられていたりされていて、来られる方だと思うのです。","respondent":"熊谷指導課長","answer":"今、委員からご指摘がありましたように、経験年数等によりましてもサポート体制はまた変わってくる部分もありますけれども、比較的、品川区の場合は、継続して行ってらっしゃる先生をお願いしているケースが多うあります。","voiceIndex":205,"id":"exchange-096"},{"speaker":"南委員","kind":"質問","question":"３８８ページの学校給食費について伺います。世界最悪レベルの東京電力福島第一原発事故、発生して６年たちました。そういう状況です。これを、税金を使うなどとんでもないという質疑が今までありましたけれども、それこそとんでもないことであり、子どもたちの命と安全を守る上での自治体の役割として、これはしっかり検査するべきだと考えていますけれども、その点について伺います。","respondent":"有馬学務課長","answer":"あわせて、それらの動向を見ながら、あるいは出荷停止の状況等、様々見ながら考えていきたいと思ってあります。","voiceIndex":208,"id":"exchange-097"},{"speaker":"南委員","kind":"質問・要望","question":"動向ということもありましたけれども、私は、ぜひ子どもたちの命の安全を守る上で、品川区の自治体としての立場をしっかり守って、必要な検査はきちんと続けていただきたいと改めて要望したいと思います。この給食費補助を導入した理由というのはどういうことなのでしょうか。","respondent":"有馬学務課長","answer":"給食費補助のうちの多子家庭給食費補助についてのお問い合わせだと思います。これにつきましては、事業を開始したのは昭和５５年となります。","voiceIndex":210,"id":"exchange-098"},{"speaker":"南委員","kind":"質問","question":"昭和５５年という、大分、何年も前なわけです。今、実際、子どもたちが学校で食している給食費は、私費負担になっておりますけれども、これは月額にするとどのぐらいの負担になっているのか。１・２年生、３・４年生、それぞれ区分けしているグループで月額を教えてください。","respondent":"有馬学務課長","answer":"給食につきましては、単価はそれぞれ、低学年が２４０円、中学年が２６０円、高学年が２８０円、中学生は一律３２０円となっております。これの食数、月分という形になります。","voiceIndex":212,"id":"exchange-099"},{"speaker":"南委員","kind":"質問・要望","question":"それで、私は勝手に２０日として計算してみたら、４,８００円から６,４００円ぐらいの金額であります。家計消費は実質、１５カ月連続で対前年比マイナスとなっている。したがって、これを実現できるようにしていただきたいと考えていますけれども、保護者の負担、この社会経済状況の中で、収入が下がっているということについての現状認識をどういうふうに考えているか、まずそこを伺いたいと思います。","respondent":"有馬学務課長","answer":"今の給食費ですけれども、金額が１桁違うのではないかと思います。今、平均すると、大体２万人、生徒がいらっしゃると思います。それで、月額５,０００円ですので、年に直すと６万円程度になりますので、これを単純にすると１２億円という計算になります。","voiceIndex":214,"id":"exchange-100"},{"speaker":"南委員","kind":"質問・要望","question":"数字の違いは訂正したいと思います。しかし、１２億円にしても、やはり十分可能だし、大事なことは、本当にこの不況の中で、やはり経済的な負担なく健康を保っていける学校給食法の目的に沿う学校給食を、その負担を軽減するという立場に立っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":216,"id":"exchange-101"},{"speaker":"渡部委員","kind":"質問","question":"２点お伺いしたいと思います。３６３ページは事務局費の中で学事制度検討経費です。３６７ページは校外授業費のところで伺ってまいりますので、よろしくお願いいたします。それと、１つ私ども、ずっと、兄弟枠というのですか、優先をお願いしていた経緯もあります。逆に申しますと、いわゆるその２校以外は、この辺が全部吸い上げられているのか、その辺の状況をお知らせください。","respondent":"有馬学務課長","answer":"これは、昨年は８名でしたので２名改善されました。兄弟枠につきましては、小学校で３名が入れませんでした。これは昨年１０名でしたので、これも多少は改善されているという状況です。","voiceIndex":218,"id":"exchange-102"},{"speaker":"渡部委員","kind":"質問","question":"状況はわかりました。校外授業費は、実は林間学校、修学旅行、移動教室など、ちょっと勉強していまして、林間学校が５年生です。これはわかります。修学旅行の９年生もわかるのですけれど、移動教室の６年生と７年生というのは、そもそもの位置づけというのですか、移動教室ですから、教室が移動するわけなのですけれども、もともとどういう質のものなのかというところを教えてください。お願いします。","respondent":"有馬学務課長","answer":"移動教室、６年生と７年生で実施していますけれども、これにつきましては、通常の授業とは別に、委員も言われたように、教室を移してということになりますけれども、自然に親しみ、また歴史的文化遺産等の学習を経験させるということと、それから集団生活をそこで行って。","voiceIndex":220,"id":"exchange-103"},{"speaker":"渡部委員","kind":"確認","question":"どういうことが言いたいかと申しますと、例えば５年生ぐらいから、みんなで６年生になったときにどこに行こう、どこに行くためにはどういう勉強を重ねて、それの確認がしたいからどこへ行こうというような活動ができないかと思います。そうしますと、そこへ行くと、ただ単に行って、山に登って景色を見て写真を撮って帰ってくるのではなくて、自分たちが様々勉強したところの確認をしてくるのです。","respondent":"有馬学務課長","answer":"宿を借りるときにはアルコールの自動販売機は全部禁止するですとか、細かいルールもありますので、なかなかちょっと難しいかと思ってあります。","voiceIndex":222,"id":"exchange-104"},{"speaker":"渡部委員","kind":"質問","question":"費用的なところですとか、様々な問題点が多いのはもう承知しております。どういうふうにやったら何か可能なのかなどと少し考えながら、またいつか質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-105"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からは、教育指導費、３６４ページにかかわって、特別支援教育費ですとか、あるいは先ほどから話が出ていますＬＧＢＴについて、そしてまた３８１ページにありますタブレット端末等の導入などについて伺いたいと思います。指導課長に以前、ダイアログ・イン・ザ・ダークの話をご紹介させていただいたことがあるのですけれども、その後、ご体験していただいたかどうかということをお伺いしたいと思います。","respondent":"熊谷指導課長、村尾教育総合支援センター長、有馬学務課長","answer":"ダイアログ・イン・ザ・ダークにつきましては、委員からご説明いただきまして、私、個人として非常に興味深く思ったところです。保護者との相談窓口であったり、またスクールカウンセラー、また巡回相談等を含めまして、できる限りということで。特別支援教育のほうにつきましては、２人に１台程度の配置ということになっておりますけれども、マイスクール八潮については配置はしておりません。","voiceIndex":226,"id":"exchange-106"},{"speaker":"あべ委員","kind":"質問・要望","question":"ダイアログに関しては、ぜひ、ご関心があれば行ってきていただきたいと思います。非常にいいプログラムだと思います。そういったものも活用して、例えば学年を超えて学習に遅れがある子ども、あるいは学校種を超えて遅れがある子どもなどに対しては、こうしたソフトなども使いながら学習をフォローしていくということもできるのではないかと思いますが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"こちらの画期的なところは、家のパソコンでも、自分の番号を入れることによって継続して学習ができるというところであり、今、モデル的に進めていまして、全学年対応で１年生から９年生までの内容が入っておりますので、その辺も今後、様々な形で拡大できればと考えています。","voiceIndex":230,"id":"exchange-107"},{"speaker":"あべ委員","kind":"質問・要望","question":"区議会で私が質問する機会も、これが私にとっては最後になるかもしれません。議会の場で教育論を語るということは、私は極力これまで避けてきたのですけれども、この機会に、これからの品川区の教育について私の考えを少しお伝えし、また教育委員会のお考えも伺いたいと思います。子どもは柔軟ですから、大人が課題とその解き方を与えれば、目先の成績を伸ばすことは難しくはないかもしれません。","respondent":"中島教育長","answer":"特に、これまで子どもたちの発想ですとか、それからモチベーションですとか、そういったものを大切にすることで子どもたちの存在感をしっかりと自分が認識していける、そのような流れのもとに市民科もつくられてまいりました。","voiceIndex":232,"id":"exchange-108"},{"speaker":"こんの委員","kind":"確認","question":"直前でも渡部委員から兄弟枠のお話が出ておりましたけれども、まずは、改めてですけれども、確認したいのですが、学校選択を希望した場合、受け入れの優先順位として兄弟枠が設けられましたけれども、設けた背景と経緯、また反対にブロック外での兄弟の受け入れは設けられていない状況ですけれども、そもそもこの兄弟の受け入れについて、入学年齢の児童を持つご家庭、それからお子さん。","respondent":"有馬学務課長","answer":"その中でブロック内の希望の方をまず入れるということで、なおかつ、空きがあれば、ブロック外の兄弟でも受け入れるというようなことになってあります。それから、これまでもブロック外で、指定校変更によって希望があったかですけれども、毎年数件は発生しております。","voiceIndex":236,"id":"exchange-109"},{"speaker":"こんの委員","kind":"意見","question":"ご説明どおりだと思います。私が課題というか１つの問題として思っているのが、ブロック外の兄弟の受け入れの考え方であります。これは１つの事例を申し上げたいのですけれども、２人のお子さんを持つご家庭の事例であります。このことについては区としてはどのように捉え、今後どのように、こうしたことの対策としてお考えになっていることがあるのであれば、お聞かせ願いたいと思います。","respondent":"有馬学務課長","answer":"例えば今回の例はたまたま引っ越したということですけれども、区の全体のルールを見たときに、とりあえず、何とか上の子を入れておけば、兄弟枠で、どこに行っても下の子は絶対そこに入れるというふうになると。","voiceIndex":238,"id":"exchange-110"},{"speaker":"こんの委員","kind":"質問・要望","question":"課長が今おっしゃったような事例も確かにあるかと思います。中には、先ほどおっしゃったような事例もなくはないが、やはり兄弟一緒に学校に通う。そういった意味では、ご事情をよくよく聞いてご判断していただく仕組みなども、今後考えていただければと思いますが、もう一言ご答弁をお願いできますでしょうか。","respondent":"有馬学務課長","answer":"はもう条件次第で、原則論だけ言ってしまえば、上の子も学区の学校に行けば、それぞれ学区で通えるということにはなりますので、そういうことで様々な条件がありますけれども、その中でご家庭も判断されることだと思いますし、我々も１つのそういった兄弟枠についての課題だとは。","voiceIndex":240,"id":"exchange-111"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ、課題と受けとめていただいて、今後、兄弟の受け入れについてご検討いただきたいと思います。要望で終わります。次に移ります。そういったところに行かれない状況の方も、卒業後、進路というのが非常に心配であるのですが、進学ができない状況になって、そのまま卒業されている方というのは、どういう手だてを、またどういうサポートを、現状、品川区としてされているのか教えていただきたいと思います。","respondent":"村尾教育総合支援センター長","answer":"まさに、マイスクール八潮も五反田についても、進学というのを１つの目標として子どもたちは頑張っておりますので、それについては、また来年も引き続き、きちんとした進路指導、また、もし委員のおっしゃるとおり進学先が見つからない場合については、当然、引き続き。","voiceIndex":242,"id":"exchange-112"},{"speaker":"こんの委員","kind":"質問","question":"それで、先ほど進路指導については、在籍校が中心で進路指導をされる。私のイメージとしては、マイスクールに通っていらっしゃる子どもの状況というのは、やはりマイスクールの先生がよくよくご存じなので、連携をとっているといっても、担任の先生よりも状況がわかっていて、より細かく情報提供ができるのはマイスクールの先生のほうかとイメージしているのですが、その辺はどうなのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"それに当たって、マイスクール八潮の指導員も、それぞれ学校に行って情報を持ってきたり、また直接、子どもが受けようという学校に行って情報をとってくるなどということで、当然ながら連携を図りながらということはありますけれども。","voiceIndex":244,"id":"exchange-113"},{"speaker":"こんの委員","kind":"質問・要望","question":"私が少し問題として思ったのが、情報提供のあり方というところがどうなっているのかというところでしたが、確かに学校に来る情報のほうが多いですから、そこから合ったものを情報提供しながら進路を選んでいく。そのサポートをされているということで、状況は良くわかりましたので、引き続き、今回の結果と同じような、毎年、進学が進むように、これからも頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":246,"id":"exchange-114"},{"speaker":"渡辺委員","kind":"質問","question":"３７１ページ、オリンピック・パラリンピック教育推進事業、それから、つる委員が触れておりました、外部人材の活用といいますか、いじめ撲滅もひっくるめての話を、続いて伺えればと思います。というのは、もう、１つ例をとれば、アニメです。そんな思いがあったので、この辺のご見解を伺いたいと思います。そして、４つのアクションがその後、続いて、今後やりたい抱負というのですか、目的がある。","respondent":"村尾教育総合支援センター長、熊谷指導課長","answer":"様々な形で、教職員だけではなく、教員以外の専門スタッフ、また地域の方々の力をかりて、本当にその地域の特色ある教育活動を進めたり、また本区全体としての教育の質を高めるということで、今後とも様々な形での外部人材の活用。そういう中で、直接、苦労して努力して、そしてオリンピアン、パラリンピアンになった方々の話を聞く機会を、今年度は、オリンピアンが１７校、そしてパラリンピアンが９校で実施したところです。","voiceIndex":249,"id":"exchange-115"},{"speaker":"渡辺委員","kind":"質問","question":"そういう教育、国際感覚のところで、平成２６年の海外留学についての内閣府の調査では、我が国が平成１６年に８万３,０００人いました。やはり、ここはオリンピック・パラリンピックを契機に、国際感覚を養うという意味では大きなチャンスだと思っているのですが、これはまず、様々なキーワードはある中で、国際感覚を養うという点で、もう一言、こういう課題に対してどう取り組むのか教えてください。","respondent":"熊谷指導課長","answer":"障害者スポーツの啓発ですが、ブラインドサッカー等につきましても、ボールボーイのボランティア等を荏原第六中学校の子どもたちが実施するなど、とにかく、まずは障害者理解を深め、そして実際、体験するなどして、今後も引き続き障害者理解教育は進めていきたいと考えています。","voiceIndex":252,"id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"学校選択制なので、３６３ページの就学事務費か、先ほどのプラン２１推進事業なのでしょうか。それから、学習指導要領の改訂についてという３点をお尋ねします。幼小連携が大変効果的に行われていて、運動会への参加、あるいは相互の交流などが、進められていると伺っています。区民の方が、担任がかわってしまったのだというお話をしていたことをお聞きしたところなので、お尋ねします。","respondent":"有馬学務課長、村尾教育総合支援センター長、熊谷指導課長","answer":"ただ、実際問題は、学校選択が終わった後の指定校変更の中で、幼稚園へ行ったときに、小学校と連携していたというような希望で指定校変更を希望される方が。私からは、特別支援教室におけるご質問にお答えいたします。過去形ということなのですけれども、実際に会話で、文脈の中で過去形を使うということもストーリーテリングで実施していきますので。","voiceIndex":255,"id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"あわせてご見解を伺います。その点において大きな課題があるのではないかと思っています。そうすると、かわった、普通教室の担任となった先生には、兼務発令ということで、拠点校と設置校の両方の兼務をしているという発令がされているのかということを確認し、そして特別支援教室の継続した指導についてのお考えを伺います。うまく融合する中で、新しい教育要領を制定していっていただきたいと思います。","respondent":"有馬学務課長、村尾教育総合支援センター長","answer":"例えば保育園でも、スクールステイというようなことで、保育園も連携しているようなところもあります。そうしますと、大分、対象も広がってしまったりしますので、これは慎重な検討が必要だと考えております。継続性につきましては、やはり今まで指導していた、または様々な形で信頼関係を結んでいたということについては、当然、学校のほうでも十分配慮しながら、その子どもたちが不利益をこうむらないように、また各学校。","voiceIndex":259,"id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、これがこの先、今度、中学校に広がっていきますし、あと来年度の体制も、そういった成果が出ているので、志望する保護者の方や児童が増えて、特別支援教室の希望者が増えているとお聞きしています。ですから、その成果をぜひ来年度に活かしていっていただきたいと思います。先ほどの、教員がかわってしまった話ですけれども、児童の保護者の方への十分な説明も、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":262,"id":"exchange-119"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３６３ページの学事制度検討経費に関連して、学校選択制について伺います。現在行われております学事制度審議会の検討項目に学校選択制を入れた区の問題意識を伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"品川区の教育改革の一環といたしまして、学校がとるべき姿という形で、これまで続けてきたものですけれども、今年度から品川区教育ルネサンスという形で新たな展開を進めている中で、今後どういった形で品川区の学事制度はあるべきかという観点から。","voiceIndex":264,"id":"exchange-120"},{"speaker":"のだて委員","kind":"質問","question":"なぜ入れたかをお聞きしたので、区の問題意識をお答えいただければと思います。","respondent":"篠田学校計画担当課長","answer":"学校選択制につきましては、これまで長年にわたり続けてまいりましたけれども、例えば就学人口の変化等によりまして、必ずしも学校選択がこれまでのようにできるような状況が、なかなかできないというようなこともありますし、また１つの制度ですので。","voiceIndex":266,"id":"exchange-121"},{"speaker":"のだて委員","kind":"質問","question":"人口の変化や、選択できない状況、永久に続かないというお話もありましたけれども、まだこの選択制については、学事制度審議会の議題にはなっていませんけれども、自由発言のときなど、この間の審議会では、学校選択制についてどういう指摘があったのか伺います。","respondent":"篠田学校計画担当課長","answer":"一方で、学校選択というのが、多数の保護者の方から、あるいは児童・生徒ご本人からも高く評価されているということで、学校選択制自体に関しては賛否様々なご意見をいただいているところです。","voiceIndex":268,"id":"exchange-122"},{"speaker":"のだて委員","kind":"質問","question":"様々な意見があるということで、議事録要旨にも、学校選択の結果、別々の３つの小学校に通っているような現状もあり、町会側がどこの学校とかかわればよいか迷っているという意見も出ています。選択制によって、地域とのつながりが弱まっているのではないかと思いますが、いかがでしょうか。","respondent":"篠田学校計画担当課長","answer":"ただ、一方では、地域との結びつけ方、学校との結びつきといった観点で考えますと、今年度から品川コミュニティ・スクールという形で立ち上げましたけれども、必ずしも。","voiceIndex":270,"id":"exchange-123"},{"speaker":"のだて委員","kind":"質問","question":"コミュニティ・スクールもやっていきながら、住んでいるところだけが地域ではないというご答弁でしたけれども、やはり住んでいる地域との関係が、顔も見えて、よくわかるのではないかと思うのですけれども、導入から、もうすぐ２０年になろうとしている中で、こういった、学校選択制によって地域とのつながりが弱まるという声が根強く上げられているのはなぜだと考えているのか伺います。","respondent":"篠田学校計画担当課長","answer":"確かにご意見として、地域との結びつきが弱まっているというご意見をおっしゃる方もいらっしゃいますけれども、例えば、今、実際に学校に通われている方の７５％は学区域のお子さんでいらっしゃいます。","voiceIndex":272,"id":"exchange-124"},{"speaker":"のだて委員","kind":"質問","question":"なぜ弱まっているという声が上がっていると考えているか、なぜなのかということをお聞きしたので伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"それは、それぞれ地域ごとに、必ずしも全ての地域で全てのお子さんが地元の学校に行かれているとは限りませんし、比較的多くのお子さんが別の学校に行かれているといった地域もあると思いますので、それぞれの地域特性によるものと考えております。","voiceIndex":274,"id":"exchange-125"},{"speaker":"のだて委員","kind":"質問","question":"それぞれの地域特性ということでしたけれども、やはり地域とのつながりが弱まっている一因に、選択制というのもあると思います。地域の方に話を聞くと、近所の子がどこの学校に通っているかもわからないと。選択制で地域のつながりが分断されているという声も寄せられます。学校選択が地域のつながりを弱める一因だと考えているのか、伺います。","respondent":"篠田学校計画担当課長","answer":"学校選択制が、地域との結びつきの弱い原因ではないかというお話ですけれども、制度実施による１つの結果ですので、全てを否定することは難しいかとは思いますけれども、ただ、先ほど申し上げたとおり。","voiceIndex":276,"id":"exchange-126"},{"speaker":"のだて委員","kind":"質問","question":"様々な理由があるということでしたけれども、私が聞いたのは、学校選択がその一因でもあるかということをお聞きしたので、伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"ただいまご答弁申し上げたとおり、様々な要因の中で、要因であることは否定はできないけれどもという形を申し上げたので。ただ、それだけではないと考えているところです。","voiceIndex":278,"id":"exchange-127"},{"speaker":"のだて委員","kind":"質問","question":"一因であるということでしたけれども、元教員の方からもお話を伺いました。学校選択制の導入の前までは、地域の学校を保護者や教員とともに良くしていこうと力を合わせていましたが、学校選択で、どの学校にするのか選ぶ心理から、学校の内側からでなく、外側からの視点が強くなってしまったのではないでしょうか。教育委員会の見解を伺います。","respondent":"篠田学校計画担当課長","answer":"特に、それまでは学校というのが非常に閉鎖的な空間であるということで、地域との結びつきが弱いといった中で、学校がどう変わっていくかといったために導入された制度であると認識しております。","voiceIndex":280,"id":"exchange-128"},{"speaker":"のだて委員","kind":"質問","question":"親の心理が変わってしまったのではないかということをお聞きしたので、その見解を伺いたいと思います。","respondent":"有馬学務課長","answer":"またその地域で行われている活動にも参加しているというようなこともありますので、それなりにきちんと活動はされている状況は、かいま見られるのではないかと考えております。","voiceIndex":282,"id":"exchange-129"},{"speaker":"のだて委員","kind":"質問","question":"様々かかわっていらっしゃるということです。杉並区では、学校関係者からも、廃止の声が３８.１％、見直しが３４.４％ということでアンケート結果が出ておりまして、既に廃止しました。品川区でも、実際に先ほどもありましたけれども、選択しても希望どおり入学できない子が、小学校で１１０名、中学校で６名いるわけですから、見直す必要があるのではないでしょうか、伺います。","respondent":"有馬学務課長","answer":"特に中学校については、６００名を超える中での６名が入れなかったということですので、ただそれをもってして、全て選択制がだめだとは、まずならないのではないかと考えております。","voiceIndex":284,"id":"exchange-130"},{"speaker":"のだて委員","kind":"質問","question":"今のご答弁は、おそらく、希望された中でも少ない数だというお話だと思うのですけれども、少ないからいいのかということがあると思うのです。やはり、公教育、義務教育ですから、悩んで選択しても入れないと。保護者の方も、選択するのに、アンケートでも責任を感じているという回答があります。せっかく選んでも入れない。この状況をどう考えているのか、伺いたいと思います。","respondent":"有馬学務課長","answer":"それに対して、今は教育委員会としてはできる限りのことでニーズに応えている。１００％ではないかもしれないですけれども、できる限り応えているというのが今の現状です。","voiceIndex":286,"id":"exchange-131"},{"speaker":"のだて委員","kind":"質問","question":"選択制によって、学校の人数の格差も生まれてしまっています。１,０００人いる学校から１学級しかない学校など様々あって、そういったところで、義務教育のところで競争が生まれてしまっています。こういった学校の競争を行っていく中で、特色を出すのに力を入れ過ぎて子どもと向き合えなくなってしまっている可能性はないのでしょうか、伺います。","respondent":"有馬学務課長","answer":"基本的に、競争によってとは考えてございません。大規模だとか小規模だとかというのは、もともとの学区の人口が違うということもあります。","voiceIndex":288,"id":"exchange-132"},{"speaker":"のだて委員","kind":"質問・要望","question":"学校選択制によって、様々地域の繋がりなどの問題が発生してきております。ぜひ廃止も含めて見直しをしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":290,"id":"exchange-133"},{"speaker":"伊藤委員","kind":"質問","question":"それからＩＣＴ化です。これは、品川女子学院にお伺いした際、生徒が皆さん、これを活用していらっしゃって、ＵＳＢメモリをＩＣＴ機器に差して、例えば、多分、生徒が作成したパワーポイントを使ってプレゼン等をしていく。それで、これからの品川区のＩＣＴ化の方向について、こういうことを例にして具体的な展開をしていくべきと考えますが、いかがでしょうかという質問です。","respondent":"熊谷指導課長","answer":"そうした事例につきましても今後、発表して、様々な学校でその取り組みを活かしていけるよう努力していきたいと思います。","voiceIndex":292,"id":"exchange-134"},{"speaker":"伊藤委員","kind":"意見","question":"それで、次のステップとして私たちが思っているのは、これは品川区の全児童・生徒を対象としたＩＣＴ機器の貸与と、それから、それを活用して、今おっしゃったような授業を立体的に展開していく。それから、もちろんウイルス対策等を十分しながらですけれども、自分でつくった様々なデータを、学校で、皆さんの前でプレゼンしていく。お願いいたします。","respondent":"有馬学務課長","answer":"今後のＩＣＴ化の方向性ですけれども、今、小規模校の支援ということで、推進校１０校、小学校８校、中学校２校につきましては、１人１台のタブレットを配備しています。このタブレットにつきまして、今後の計画というものは、今、具体的な資料を持ち合わせておりません。","voiceIndex":294,"id":"exchange-135"},{"speaker":"伊藤委員","kind":"意見","question":"それは方向性としては間違っていないとは思うのですけれど、グローバル人材の育成やら、それから未来に向けた子どもたちを育てていくというすばらしいことを、教育委員会としては掲げていらっしゃるわけです。すると、ＩＣＴというのは、必ずと言っていいほど通過していく世界であるわけです。それが次のステップだと思うのだけれども、もう一言、答弁をお願いいたします。","respondent":"有馬学務課長","answer":"今言ったように、まずはパソコン教室のタブレット化です。それから、もう一つは、全教室に対するプロジェクター等の整備も同時に行いますので、そういったことを踏まえて、また検討していきたいとは思ってあります。","voiceIndex":296,"id":"exchange-136"},{"speaker":"伊藤委員","kind":"意見","question":"ぜひ十分な検討をお願いしておきます。子どもが使えなかった。逆の現象ですよね。だから、その方がおっしゃるには、グローバル人材の育成をうたうならば、学校で洋式トイレを進めることはもちろんいいのだけれども、だけど教育現場の中で、例えば世界文化の多様性に応じた教育の展開をすべきではないかという意見があったので、そのことについて品川区の見解をお願いいたします。","respondent":"品川庶務課長","answer":"ただ、状況によって、和式は基本的には残していくというスタンスはとっていくつもりです。学校では、１年生のときに生活科の中で、トイレのことを勉強するということがあります。そこで、１年生も和式トイレの使い方などを勉強するというような教育体制を図っております。","voiceIndex":298,"id":"exchange-137"},{"speaker":"伊藤委員","kind":"質問","question":"ある方がＬＧＢＴを説明するときに、異性愛のみを推進する異常な現実という表現をされたことがあったのです。だから、そういう教育の現場では、１つの方向性のみ推し進めていくのではなくて、多様性の部分を十分把握しながら子どもたちに教育をしていく必要があると思うのですが、いかがでしょうかという質問なのです。ご答弁をお願いいたします。","respondent":"村尾教育総合支援センター長","answer":"ＬＧＢＴに関するというか、性的マイノリティーに関する子どもたちの教育につきましては、まさにおっしゃるとおり、子どもたちに対して、やはり多面的・多角的な見方というものについても、当然教えていくべきものだと考えておりますし。","voiceIndex":300,"id":"exchange-138"},{"speaker":"伊藤委員","kind":"意見","question":"だから、今おっしゃったように、総合的な観点から、個々の事例を研究・調査していって、教育現場では展開していかないと、例えば個人の尊重もそうだし、それから世界に向かって目を向けていかなければいけないし、もちろん人権を守らなければいけないという、非常に難しい方程式を解いているような教育なのかもしれないけれども、でも、それを具体的に展開していかないことには、こういう。","respondent":"村尾教育総合支援センター長","answer":"１年生から９年生という義務教育の中で、発達段階もありますけれども、やはりそれぞれの発達段階に応じて、様々な事実を、きちんと社会の中での現実を見せ、それに対して子どもたちの意見をまとめながら教育は進めていく。","voiceIndex":302,"id":"exchange-139"},{"speaker":"若林委員","kind":"質問・要望","question":"３７３ページの特別支援教育費と、３６４ページの教育指導費、これはがん教育について伺いたいと思います。委託ということについてもご説明いただきたいと思います。もっと指導したいとか、また子どものほうから言うと、もっと指導を受けたいという声があったのかどうかとか、トータル的に適切な回数など、一人一人のニーズに沿った取り組みの考え方についても教えていただきたいと思います。","respondent":"村尾教育総合支援センター長","answer":"時間、曜日は決まっておりまして、１から２時間程度ということで、子どもたちがもっとやりたいという声があるのかということについては、当然、子どもたちは様々個別対応が受けられますので、そういう希望はあるかもしれませんが、やはり時間割りの中で組んでおきますので。","voiceIndex":305,"id":"exchange-140"},{"speaker":"若林委員","kind":"質問・要望","question":"知能発達検査のほうは、確かにそういう課題があるということを、以前、施設に行ったときも伺っておりまして、これでまた、効果と実績に効果的な特別支援が行われるということで、１点、何年生を対象にされているのか、これまでは２年生と聞いていた覚えがあるのですが、この辺をちょっと教えていただきたいと思います。時間が切れてしまうので続けます。","respondent":"村尾教育総合支援センター長","answer":"Ｗｉｓｃ検査につきましては、１年生から６年生、どの学年でも対応できると考えています。実際には２年生以上ということで子どもたちの検査をしているのが現実です。２点目です。","voiceIndex":307,"id":"exchange-141"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は、３６９ページ、体験学習になるのかもしれません。その中で、体験という部分をどこまでやるのか。それから、あと、この前伺ったら、美理容の学校も定数割ればかりだと。今後どうなっていくのだろうと。それで、では木育というのはあまり学校で聞かないと思っていたのだけれども、こういう木育という捉え方はどうお考えかというのをまずお聞きします。","respondent":"村尾教育総合支援センター長","answer":"委員のご提案されている体験活動、体験教育という部分については、今後、次期学習指導要領の中に、教育内容の７つの改善の一つとして、４つ目に体験活動の重視ということで、生命の有限性や自然の大切さ、他者との協働などということで。","voiceIndex":310,"id":"exchange-142"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そのときの話で、１つ目は、木材と触れ合える環境をつくっていくべきだろうと。これは、公的な部分も木造を増やしていこうという考えがあったけれども、２つ目は、実際に手にとって体験をしようと。それで、今おっしゃったように、３つ目は、何か作っていこう。これはお願いで、要望だけでやめます。１つは親育です。だから、そこら辺の点を公の部分としてどうお考えなのかというのを教えていただきたい。","respondent":"熊谷指導課長","answer":"私立の幼稚園との違いというところなのですけれども、実は本区におきましては、私立幼稚園の教員も、それから保育士も一緒に学ぶための研修会も実施しているところです。そうした中で、ともに品川区の子どもたちを育てる教育を行っているところです。","voiceIndex":312,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"私は、教育費全般で、学習指導に絞ってお聞きしたいと思います。現在、全国各地の自治体で、貧困家庭の子ども向けの学習支援事業の立ち上げが相次いでいます。小学５年生の２０.５％、中学２年生の２１.６％が生活困難層だった。子どもの学習指導をしている教育委員会は、このことについてどのようにお考えでしょうか。","respondent":"熊谷指導課長","answer":"本区におきましては、コミュニティ・スクール実施に伴い、地域未来塾を起こしておりまして、放課後の学習支援、そして長期休業中の学習支援ということで、寄り添った指導を行っているところです。","voiceIndex":315,"id":"exchange-144"},{"speaker":"須貝委員","kind":"意見","question":"私は、責任があるのではないかと。だって、本来は、教育、子どもの学習指導は、教育委員会、学校でやらなければいけない。でも、こういうふうに全国の福祉行政がどんどん手を挙げて、うちもやります、支援します。そうですよね。例えば、この子たちが、授業の３分の２しか受けられない、半分しか受けられないのだったらわかります。それについて、責任というか、そういうものをお感じになりませんか。","respondent":"熊谷指導課長","answer":"もちろん責任は感じております。ちなみになのですけれども、委員がよくご指摘される秋田県や福井県、学力が非常に高い県ですけれども、ここでポイントなのですけれども、ここはなぜ高いかというと、地域ぐるみで、保護者も地域も一緒に取り組んでいる。","voiceIndex":317,"id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、何が原因なのですか。プロの先生ではもう力量的に難しいのですか。できないのでしょうか。では学校というのは何のためにあるのですか。そういうことを考えると、やはり私は様々なところを見てきても、何か品川区は教育を一生懸命やっているのはいいのですが、やはりきちんとした成果というのを出さないと、教育の現場としても私はおかしいのではないかと思うのですが、いかがですか。","respondent":"熊谷指導課長","answer":"体育が得意な子もいますし、例えば、国語は得意だけれども数学は苦手というような、私のような場合もあるかと思います。ですので、そういった苦手分野を克服するための支援を、学校でもそうですが、放課後の学習でも行っていくことが重要だと考えております。","voiceIndex":319,"id":"exchange-146"},{"speaker":"須貝委員","kind":"質問・要望","question":"子どもたちが成長して、将来の姿を、若い教育委員会の方、事務局の方もそうだと思うのですが、やはり今、様々な自分の希望する夢、それから会社、そういうものを求めていくには、ある程度、学力がないと、やはり難しいではないですか。最低限の力はつけてほしい。ですから助かっている子もたくさんいます。それは設備費が学校改築ですごいですから。そういう状態になってほしいのですが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"ＡＩ先生、教材と私は申し上げましたけれども、やはり生身の人間、生身の教員の良さというのは何だろうといったときに、子どもたちの顔を見て、今日は元気がない、間違っているのでがっかりしている、親御さんと何かあったか、子ども同士でけんかしたか、様々な機会を通じて。","voiceIndex":321,"id":"exchange-147"},{"speaker":"須貝委員","kind":"意見","question":"私は、今の教育現場は忙し過ぎると思う。先ほどから話を聞いても、学習指導をはじめ、生活指導、進路指導、保護者対応、それから様々な研修があります。教員の負担は絶対、どう考えても重過ぎます。私立ではこんなことは、ほとんどない。だから、教員の負担を減らすとか、学習塾に行かなくても品川区の教育で、学校で、きちんと学べるような、私はそういう学校を、教育現場をつくってほしいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":323,"id":"exchange-148"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、３６５ページの学校ＩＣＴ化推進経費について、３８１ページの学校ＩＣＴ活用経費について、それと、ページがないのですが、教育スタイルについてと主権者教育について、時間があれば図書館経費についてお伺いいたします。それと、アクティブラーニングについて区のご見解をお知らせください。この点について、今後の品川区の教育委員会の考えをお知らせください。よろしくお願いします。","respondent":"熊谷指導課長、有馬学務課長、村尾教育総合支援センター長","answer":"指導課、教育総合支援センター、それから学校管理職がモデルとして実施することによりまして。予算でいきますと、来年度は８校分、新たに校内無線ＬＡＮを設置する予定でございまして、校内ＬＡＮにかかる費用につきましては。アクティブラーニングにつきましては、世界規模の調査によって、日本の子どもたちが、愕然とするほど、なかなか授業参加が弱いというか。そういった中で、対極にあるものを使ってという交流が行われているところです。","voiceIndex":325,"id":"exchange-149"},{"speaker":"石田（し）委員","kind":"質問","question":"月、何回会議があるかだけ教えていただければと思います。","respondent":"熊谷指導課長","answer":"会議ですけれども、大体、週に１回は、職員会議、もしくは研修会、研究会というのがありますので、大体、月にしますと多くて５回ぐらい、４、５回だです。","voiceIndex":331,"id":"exchange-150"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"このデータを活用することによって、先生がどういったことをＩＣＴを使ってやっているのかとか、生徒がどういうことに興味を持ってやっているのかということで、次の授業などにも非常に活かすことができるデータでありますので、これはぜひこういったデータをしっかりと蓄積して活用していただきたいと思うのですが、ご見解をお知らせください。","respondent":"有馬学務課長","answer":"最初の１点目のフューチャークラスルームの件ですけれども、実は教育委員会といたしましても、平成２５年に一度、そういうものがあるということで、導入を検討するまでには至りませんでしたけれど、こういうものがあるのだということで認識したものです。","voiceIndex":333,"id":"exchange-151"},{"speaker":"石田（し）委員","kind":"意見","question":"時間があるので１点だけ、図書館経費ですが、品川区の図書館における、電子書籍の導入の取り組みについて、現状と今後のお考えをお知らせください。","respondent":"木村品川図書館長","answer":"普及でありますとか、それから規格の統一感でありますとか、そういうところを見ながらというところで、まだ具体的に、いつからちょっと試しでやってみようとか入れてみようとか、そういうところまではまだ至っておりませんが、引き続き研究してまいりたいと思ったところです。","voiceIndex":335,"id":"exchange-152"},{"speaker":"石田（し）委員","kind":"意見","question":"この予算の中でも、例えば大井町のサービスコーナーのときに図書の貸し出し等も出てきますけれど、そういったことも、電子書籍があればなくなっていくのかと思いますので、ぜひ研究から検討の段階に入っていただければと思いますので、引き続きよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":337,"id":"exchange-153"},{"speaker":"安藤委員","kind":"質問","question":"図書館経費、学力定着度調査について伺います。３７７ページには、大崎駅西口図書施設開設等経費、芳水小学校内図書施設設計費が計上されていますが現在の大崎図書館の機能、果たしている役割の代替にはほど遠く、これをもって大崎図書館移転を進めるというのは反対です。移転理由を変えるとは一体どういうことなのでしょうか。これでは住民をだましたのではないでしょうか、伺いたいと思います。","respondent":"木村品川図書館長","answer":"これは以前も答弁でご説明させていただきましたが、品川産業支援交流施設（ＳＨＩＰ）の開設に伴いまして、実際に大崎図書館の今まで２階にございましたビジネス支援機能が移転することに伴いまして、大崎図書館自体の再活用を検討するというような段階におりました。","voiceIndex":339,"id":"exchange-154"},{"speaker":"安藤委員","kind":"質問","question":"地元の方々は、大崎図書館を移転するという区の方針を聞いて、反対の請願を出したわけです。実際にビジネスコーナーは２階に残っているからです。区立図書館の広報紙にも、大崎図書館の紹介として、「２階にはビジネスコーナーが設けられており」とあります。それがあって、批判が強くなって、その都度、理由を後から考えているから、こうなるのではないのでしょうか。","respondent":"木村品川図書館長","answer":"理由をその都度変えているというようなご認識ということではありますけれども、繰り返しになりますが、私どもとしては、説明をそのような意味で、受け取られたというところではあるかもしれませんが、してきたつもりはございません。","voiceIndex":341,"id":"exchange-155"},{"speaker":"安藤委員","kind":"質問・要望","question":"ただでさえ充実が求められている図書館サービスの充実を求め、次の質問に移りたいと思います。次に、３６９ページ、学力定着度調査経費について伺います。本人、あるいは担任や学校への、そして学校ホームページなどの掲載はどうなっているのか、それぞれ伺いたいと思います。最後に、東京都の学力テストおよび全国学力テストとの違いはあるのか、ないのかも伺います。","respondent":"熊谷指導課長","answer":"実施する学年と教科ですけれども、まず２・３年生につきましては、国語と算数と、そして児童のアンケート、そして４年生から６年生は、国語、算数、社会、理科、そして児童アンケート、７年生から９年生は、国語、数学、社会、理科、英語、そしてアンケートとなっております。","voiceIndex":343,"id":"exchange-156"},{"speaker":"安藤委員","kind":"質問","question":"子どもたちに渡るというところですが、それがどのような結果になるのか、子どもたち同士で、おまえ、どうなのだということで競争が激化しないか、危惧するところです。そこで考えなくてはいけないところは、ここで定着を図るとされている学力とは何かということだと思います。区の考えを伺いますが、学力テストではかれる学力とは何なのか、子どもの何がはかれると考えているのか伺いたいと思います。","respondent":"熊谷指導課長","answer":"それで、子どもたちが一体どこでつまずいているのか、どうしたら学力を定着させられるのか、そういったものを経年で見ていくことで改善につなげていく。そして、教員にとっても指導力の改善ということにつなげていけると考えております。","voiceIndex":345,"id":"exchange-157"},{"speaker":"安藤委員","kind":"質問","question":"私が心配するのは、毎年のようにテストが行われ、これでは２年生から毎年テストです。５年生からは、７年生以外は毎年、年に２回、テストが行われることになります。さらに、学級やグループで話し合う活動を授業などで行いましたかという設問に対しては、小学校が品川区３５.１％、全国４７.８％と低い。そうした心配について、区はどのように考えるでしょうか。","respondent":"熊谷指導課長","answer":"だからこそ、これから、こうした子どもへのアンケート等も含めて、授業の改善について、また区としても学校と一緒に考えていきたいと考えております。","voiceIndex":347,"id":"exchange-158"},{"speaker":"安藤委員","kind":"質問・要望","question":"紹介しましたように、こうしたテスト競争を激化させることで、テストの点数を獲得するためにどうするかということが中心の学校になっていき、そして子どもたちが追い詰められる。そして、豊かな学びを奪われる可能性があります。学力テストの拡大は中止を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":349,"id":"exchange-159"},{"speaker":"たけうち委員","kind":"質問・要望","question":"３６７ページの、いじめ防止対策費、３７５ページの文化財保護事業、３８７ページの就学援助費でお伺いします。親としては、先ほどもあったとおり、ネットいじめが４件、報告があったなどとありましたけれども、なるべくなら持たせたくないと思う中で、多分、多くの中学生は持っていると思うのですけれど、持たせる理由はなぜなのかというところ、どのようにつかんでいるかを教えてください。","respondent":"村尾教育総合支援センター長、品川庶務課長、有馬学務課長","answer":"このような取り組みは進めているところです。文化財の件ですが、これは広報のほうで、しながわ百景アプリ、ＡＲ技術を活用した記念撮影スポットというものをアプリでやっていく予定でおります。中学１年生だったら中学１年生のときでないとならないというものでしたけれども、国は最近、これをいわゆる前倒し。","voiceIndex":351,"id":"exchange-160"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そうしましたら、義家文部科学副大臣は、大変重要な指摘なので速やかに行いたいと決意をしていると、このような答弁があったということなので、おそらく全国としては、子どもの貧困とか、様々な動きの中で、そういう動きを今、模索しているのではないかと思いますので、品川区としては直接そのスキームではないと思いますけれども、そうした動きを見きわめて。","respondent":"濱田生活安全担当課長、有馬学務課長","answer":"夜が遅くて心配だという声に対しましては、中学生になった初年度に、防犯ブザーを配布しております。こういったことで対応しております。直接的に、区の場合は、要保護世帯への補助については、生活保護の部分で入学の支度金ということで、すでに前倒しが実際にはされているですけれども、それ以外の部分の準要保護の部分について。","voiceIndex":355,"id":"exchange-161"},{"speaker":"鈴木（真）委員","kind":"確認","question":"先日、ちょっと資料をいただいたのですけれど、今の学校、小学校・中学校・義務教育学校の建築年次を確認させていただいたところ、一番古いのが昭和３３年の鮫浜小学校ということで、今、改築の計画が出ています。あわせて、一番古い所で、全体がこの年代ではないということもお聞きしているのですけれど、これからの改築計画についてどのように考えていくのか、その点を教えてください。","respondent":"熊谷指導課長、篠田学校計画担当課長","answer":"学校支援地域本部事業経費の内訳ですけれども、学校地域コーディネーター経費が２,２５１万９,８７２円となっております。それから、地域未来塾講師謝礼ということで８２８万８,０００円です。そういったものの対応ですとか、あるいは個別の学校で何か支援が必要だといったようなことを教育委員会が判断すれば、そういった、１つの手段としての学校の改築といったようなことも要因として挙げられるかと思います。","voiceIndex":359,"id":"exchange-162"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それで、前に質問に入れさせてもらったことがあると思うのですが、新しくコーディネーターになる方は、すごくこれから責任感を持ってやっていこうということでお話を伺っています。１億３,４００万円です。これは、何で学校改築で出てきて、補助金として出てこないのかどうかという点が１点です。それから、この１億３,４００万円というのは、自費なのか、国から出てくるのか、その辺を教えてください。","respondent":"熊谷指導課長、篠田学校計画担当課長","answer":"実際に新しくなるコーディネーター等に対する支援ですけれども、年間を通しまして４回、研修、そしてコーディネーター同士の情報交換、また私ども事務局との連絡調整会議等を設けて支援をしています。財源の関係ですけれども、埋蔵文化財等の対応につきましては、いわゆる出るか出ないかわからない段階での試掘に関しては、国の補助あるいは都の補助というものの対象になるのですけれども、出ることが確定してしまいますと。","voiceIndex":362,"id":"exchange-163"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"どういうものが出てくるか、その辺はわからないのですけれど、工事が順調に進むようにお願いしたいと思います。それと同時に、これから、今、品川教育ルネサンス、コミュニティ・スクールと、さきほどお話も出ていましたけれど、この学習指導要領と教育ルネサンスをどのように結びつけて、区の教育を展開させていくのか、そこら辺の点についてお答えをお願いしたいと思います。","respondent":"中島教育長","answer":"義務教育学校による複線化の中で審議会を設置して、これからも教育のあり方を検討していくことも踏まえて、より良い品川区のあしたの教育をつくってまいりたいと考えます。","voiceIndex":365,"id":"exchange-164"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1066#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":132171,"voices":367}},{"id":"h29-20170317-7","meetingId":"h29-cm03","date":"2017年3月17日","dateIso":"2017-03-17","committee":"厚生委員会","time":"午後 ２時００分～午後 ３時３２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３６号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第３６号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"横山委員","kind":"確認","question":"１点だけ確認したいことがあるのでお願いします。ジェネリック医薬品の利用促進等への働きかけを、今後は２３区と都と一緒になって行っていくというお話いただきました。品川区も既に取り組みされているかと思うのですけれども、その辺について確認をお願いします。","respondent":"高森国保医療年金課長","answer":"この間、データヘルス計画ということで、平成２７年度に計画を策定させていただいて平成２８年度から進めているのですけれども、このデータヘルスの推進会議の中で、薬剤師会の方もお声をかけ呼ばせていただきまして、そういう中で。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからこの資料なのですけれども、国保運営協議会に出された資料と随分違う資料になっているというのはなぜなのでしょうか。今までは国保運営協議会の資料に条例のところがどう変わるかというのをつけた資料を委員会の資料として示していただいていたと思うのですけれども、なぜ国保運営協議会に出された資料からかなりのページを減らした資料になったのかをお聞かせください。","respondent":"高森国保医療年金課長","answer":"この間、確かに委員おっしゃったように、国保運営協議会の資料というのは、今日お出しした厚生委員会資料よりもかなり大きいものですけれども、必要な部分を抽出いたしまして、今回委員会資料として提示しています。それ以上の意味はございません。","voiceIndex":9,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"説明そのものも、もっとわかるようにしてほしいというのが、今回の国保運営協議会でも意見として出されたのです。それが１点です。というのも、ここで比較をすると、例えば賦課総額とかというのはどこかに出ているでしょうか。それから国保の加入者、加入世帯がどれぐらいいて、それが経年的にどういうふうに変化しているのかとかという、そういう推移はどこかに書かれているでしょうか。","respondent":"高森国保医療年金課長","answer":"そしてこの賦課割合、所得割率については、各区独自という形になっていますので、ここでは１.３９という所得割率になっているところです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは、きちんと国保運営協議会に出された資料というのは、ぜひとも委員会の中に今までどおりに出していただきたいと思いますし、それと同時にこういう説明をするときに、制度の仕組みがわかるような形で説明してほしいというのが毎回国保運営協議会で出されていると思うのですけれども、そういう形で厚生委員会の中でも説明も制度そのものも理解できるような形での説明を、ぜひしていただきたいと思います。","respondent":"高森国保医療年金課長","answer":"資料につきましては、来年度について、国保運営協議会の資料も変更するような動きもありますので、もう一度検討して、なるべく同じ形のものを出すように進めていきたいと考えております。","voiceIndex":15,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"基礎控除額プラス２６５,０００円のところが、基礎控除額プラス２７万円ということで、控除される額が５,０００円上がって、対象を拡大するということになるのかと思うのですけれども、２割軽減のところが４８万円のところが４９万円ということで、１万円ということで、これは、なぜ５,０００円、１万円という額が拡大がされたのかということと、それから、それによって対象者が増えるのか。","respondent":"高森国保医療年金課長","answer":"被保険者数ですが、全体の話で、２３区の話でよろしいですか。","voiceIndex":17,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"９８件、８６件というのは、今まで対象でなかった方が新たに対象になる世帯数ということで考えてよろしいでしょうか。","respondent":"高森国保医療年金課長","answer":"世帯数で、平成２８年度の実績が５割軽減ですと、５,１０３件だったのですけれども、これが５,２０１件、２割軽減４,６５７件が４,７４３件となります。ただ、この数字はあくまでも推定ですので、その旨ご理解いただければと思います。","voiceIndex":21,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうした場合に、１３億５,０００万円が１人当たりにしたらどれぐらいの値上げになるのかということを伺ったときには、１万５千幾らというふうなことで答えていただきました。本当であれば、平成２９年度、平成３０年度で３３％を全額保険料で賄う仕組みにするという予定ですよね。予定だと思うのですけれども、その３３％というと、１７％と１６％みたいな感じに二等分するとそうなるではないですか。","respondent":"高森国保医療年金課長","answer":"それと、この高額療養費賦課総額算入の経緯については、申し上げておきますけれども、平成１２年に都区制度改革のときに、高額療養費を含めて算入した保険料水準が低く抑えられる状況ではない限り、容易ではないというふうな認識で、算入を見送ってきたという状況です。","voiceIndex":23,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところもあって、今回平成２９年、平成３０年で入れると言っていたものが予定どおり入れられないというふうな状況になったのではないかなと思うのです。その中で区長会も全国市長会も知事会もそういうところが全部求めていて、せめて協会けんぽ並みに国保の負担割合を持っていってほしいというようなことを出していますね。その辺のところはどう考えられているのでしょうか。","respondent":"高森国保医療年金課長","answer":"私どものほうも保険料引き下げできれば、それに越した事はないわけで、毎年のように引き上げをお願いするのも大変苦しいところでありますけれども、しかしながら医療費総額が本当に伸びているというのも事実でございまして、その負担も少しでも行いながら。","voiceIndex":25,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"所得に占める保険料の割合というのは、国保が９.９％で、協会けんぽが７.６％なのです。そこで、やはり新たに投入された３億７,０００万円は、みんなで保険料引き下げに使いましょうと言えば、そのように誰もが認める構造的な問題の解決の一助になるわけですから、ぜひそうすべきなのになぜそうしないのか。それは矛盾じゃないのかと思うのですけれどもいかがでしょうか。","respondent":"高森国保医療年金課長","answer":"ただ、この一般会計から、実は法定外繰入金ということで、国保会計にお金を動かしているわけで、全然使っていないわけではなく、もう既に保険料を値下げするために利用していたお金に入れているということですから、お金には色がないので。","voiceIndex":27,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"７,７５１円というのは、本当にぎりぎりでもう本当に払えないぎりぎりで生活できないと言っているところにさらに値上げがどんどん続くというそういうことですから、これだったらいつまでたっても矛盾は拡大するばかりで解決どころか、暮らしも破綻、制度も破綻というふうなことになっていくのではないかと思うのですけれども、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"確か、平成２５年度に高額療養費等を算入するという決定をして、そのスタートのときの平成２６年から４年間ということで、確かそのときの総額というのが、算入総額１人当たり９千幾らと言われていて、毎年２,５００円ぐらいの算入と言われていたのですが。","voiceIndex":29,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私自身で計算したらそういう感じになるのです。逆に増やしていただきたいということで、要望をします。もう一つ、改めて伺いたいのが、今回の予算の中にこの値上げ分というのは、今、予算委員会が開かれていますけれども、予算書の中に出されているものは、この値上げ分が、投入された予算というふうなことで考えていいのか。基本的なことなのですけれども、そこのところ確認をさせてください。","respondent":"高森国保医療年金課長","answer":"国保制度の予算につきましては、毎年当初予算を議決いただきまして、３月に最終的に補正を行っている状況でございまして、今回は国からの法令の改正等により、こういう特別に委員会を設けするような形で、遅れてきましたので、保険料の関係でいけば。","voiceIndex":31,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうしますと、今回これで条例で決められて、この保険料と決まりましたら、それはいつどのように反映されるということなのですか。","respondent":"高森国保医療年金課長","answer":"さまざまな形で支出として、どんどん出ていくように国保はなっていまして、国保の会計のご説明しますと、療養給付費だとかさまざまな被保険者の方が利用された保険、いわゆる保険費用を東京都の国保連合会というところを通してお金を出していくわけですけれども。","voiceIndex":33,"id":"exchange-012"},{"speaker":"松永委員","kind":"質問","question":"新しいお薬はこれですよ。もう１点が１２ページなのですけれども、これも先ほども鈴木ひろ子委員からもありましたが、毎年値上がりされて、私的には、個人的にはしようがないというのはあるのですけれども、総額医療水準が上がったということと、１人当たりの医療費が上がった、増加したという要因がある中で、これはおよそ大体どこまで上がるのかというのは計算されているのでしょうか。","respondent":"高森国保医療年金課長","answer":"実際出ているお金、保険者として出ていくお金というのはそういう形になりますので、かなり制度自体が、国民皆保険ということでさまざまな高額な医療が今、保険の中に含まれてきてありますので、その辺のところは、国が整理をしたり何かして、何らかの形で対応していけば。","voiceIndex":37,"id":"exchange-013"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"幾つかわからない点お伺いします。１０ページのところで、2)の賦課割合は５８：４２とするということですが、基本的なことで申しわけないのですが、１２ページの資料を見ますと賦課割合が６１：３９になっているのですが、なぜここでずれてしまうのかなというのが、素朴な疑問として、まず１点目です。なぜ政令は、このような動きになっているのか、その理由についてお伺いしたいのが２点目です。","respondent":"高森国保医療年金課長","answer":"こちらは２３区では、５８：４２ということで、所得割が５８で、均等割が４２ということなのですけれども、こちらの１ページめくって１２ページ目、品川区の国保の保険料率は、確かに６１：３９となっていますが、これは所得の多い方が多かったりしますと、所得割の率が上がって。","voiceIndex":40,"id":"exchange-014"},{"speaker":"安藤副委員長","kind":"質問","question":"先ほどから紹介もありますこの２０１４年７月の全国知事会の提言がありまして、これに基づいて保険者支援金というのが国から出るようになったと認識をしているのですが、その提言では「被保険者が保険料負担に耐えられる限度を超え、国保運営が破綻するおそれがある」と述べておりますし、「皆保険制度の最後の支え手である国保を持続可能な制度とするには。","respondent":"高森国保医療年金課長","answer":"１,７００億円のうち、３億７,０００万ほどが、品川区のほうに公費として入ってきたということで、これは何回も申し上げていますけれども、保険者の財政支援ということで、保険者が、法定外繰入金が大きくなりすぎて、耐えられなくなるということから、当時平成２６年。","voiceIndex":42,"id":"exchange-015"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"それは保険者のことを言っているわけではないですよね。中心は、保険料を納める被保険者のことを言っているわけで、そうした趣旨に照らせば、やっぱり私はしっかりとそのために来たお金であるならば、保険料を下げるために使わないとこの提言の趣旨には合わないのではないですかという意味でお伺いしたので、もう一度お伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-016"},{"speaker":"安藤副委員長","kind":"質問","question":"保険者が大変な自治体もある、財政を圧迫していると言いますけれども、品川区は、私は、これまでもやれてきたし、現在でも財政が破綻直面というわけでもないわけではないですか。品川区で財政的に一般財源からの投入で具体的に危機だという状況があるのかどうか、そこら辺はどうなのでしょうか。私はしっかりと保険料を下げるためにこのお金は充てるべきだと思いますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これは保険料の問題、それから財政の問題ということで、全て国保の条例にかかわってくることなので、そういう意味で、この委員会における質疑というのは、委員が自由に発言をし、質問もできるという場ですから、そういう形で抑えるというやり方はちょっと。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"去年の平成２８年の１２月２６日に、区長会で、国保について、先ほども課長からありました特別区の緊急要望が出されています。そこで「子育て世帯の経済的負担の軽減のために」というのが3)に書かれているのですけれども、「これは国の責任において、区市町村の補助制度に対する財政措置を講じること」ということなのですけれども、これは具体的にどういうことかということを教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-019"},{"speaker":"渡部委員長","kind":"質問","question":"答弁の前に鈴木ひろ子委員からのご発言に対しまして、委員長として自由な意見をとめているつもりはございません。同じ会派から同じことの繰り返しになっているのがまず１点です。それから、２点目に区の一般財源の投入の話ですけれども、区の財政全般を語れる理事者の方がいませんので、それに対して答弁いただけないと判断して進めておりますので、ご了承ください。答弁お願いします。","respondent":"高森国保医療年金課長","answer":"これは、直接国保のほうには関係がないという言い方をしてはあれですけれども、子育て支援の関係の課で、区の独自の軽減をしているところに対して、いわゆる国の方針とはずれているという形で、それが先ほどお話があったペナルティで。","voiceIndex":55,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、そこのところのペナルティで出されているのが、品川区ではどの程度なのかということについて、先ほどお聞きしましたのでご答弁お願いいたします。","respondent":"高森国保医療年金課長","answer":"申し訳ございません。私のほうでは、今その資料を持ちあわせてございません。","voiceIndex":57,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかりました。さらに、ぜひ求めていただきたいのと、特に子育て世代のところは、均等割とか何かまるまる、赤ちゃんでも同じ均等割がかかってきてしまうというところでは、子育て世代にとっては、特に国保が大変だという。","respondent":"高森国保医療年金課長","answer":"２３区だけでそういう形のことを、仮に合意形成が図られて実現したとしても、またこれは法に抵触するということで、さまざまな形での指導が入ると認識していますので、現状ではそれについてはできないです。","voiceIndex":59,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点で言えば、子育て世代、子どもにも均等割が同じ額だけかかってしまうというところの負担の重さというのは、実感されているのではないかなと思うのですけれども、そういう点ではそういう子どもに対する均等割の減額ですとか、多子世帯の減免というのは、ぜひともそういう制度を要望として上げていただきたいなと思うのですが、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"先ほど、特別区長会で出ているということで、やはり子育て世代の負担軽減ということが、厚生労働省のほうに出ていますので、こういうことは必要に応じて、また進めていきたいと考えています。","voiceIndex":61,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、もう一つお聞きいたします。東京都からの収納率向上にかかわる取組み別成績交付算定表に基づく平成２７年度の報奨金というか、そこの金額なのですけれども、確認させていただきたいのが、現年度収納率、現年度分の収納率の伸び率、滞納繰越分の収納率、滞納繰越分収納の伸び率です。","respondent":"高森国保医療年金課長","answer":"そのとおりです。","voiceIndex":63,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そうですね。現年分の収納率伸び率というのは、２.１７％ということでいいのでしょうか。多分平成２６年が８７.１９％で、平成２７年が８９.３６％ということで、その点を確認だけさせていだきたい。それから滞納繰越分の収納率というのが、５０.９０％で滞納繰越分の収納率伸び率が、平成２６年が４０.３２％なので、１０.５８％ということでいいのか、そのことの確認だけさせてください。","respondent":"高森国保医療年金課長","answer":"そのとおりです。","voiceIndex":65,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうしますと、私は東京都のほうから計算式をいただいたのですけれども、現年度分の収納率が８９.３６％で、東京都から入るお金は４,５００万円。それから伸び率で、２.１７％で５,０００万円。差し押さえ件数で３,０００万円ということになると、１億６,５００万円が取組み別成績交付算定表からもとめられる交付額になるのではないかなと思うのですけれどもいかがでしょうか。","respondent":"高森国保医療年金課長","answer":"それと、差し押さえ割合に対する交付というのが３００万円ありますから、平成２８年度の交付見込み額につきまして１億６,８００万円です。","voiceIndex":67,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"わかりました。この額が幾らなのかということで、本会議の質問でもしたのですけれども、そのときにはこういう金額ではなかったので、改めて１億６,８００万円ということで確認をさせていただいていいでしょうかということで、確認です、お願いします。","respondent":"高森国保医療年金課長","answer":"本会議の質問のときには確定通知が来ておりませんでしたので、お知らせすることはできなかったという状況です。現在は確定通知が来てあります。","voiceIndex":69,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"理由ですけれども、今年値上げの額が近年にない大幅な値上げで、もともと毎年値上げされて、もう限界に来ているということが、３首長会の中でも確認されているにもかかわらず、さらに大幅な値上げになったということ。そんな中で滞納がどんどん広がっており、その滞納者には厳しい取り立てを行うことで、その報奨金が昨年より２倍に膨れ上がる１億６,８００万円ということが、改めて明らかになりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3472#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":26556,"voices":82}},{"id":"h29-20170322-3","meetingId":"h29-c-budget","date":"2017年3月22日","dateIso":"2017-03-22","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を122件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"このように、超過勤務や休日出勤をやむを得ず行っている現状、部署によって年間残業時間が８００時間、１,０００時間を超える職員の方もいらっしゃる事実、また多忙やストレスが理由で病気休暇・休職となる方もいると伺っています。ここで伺います。区職員で年間残業時間が８００時間、１,０００時間を超えている方は、それぞれどれぐらい、何人ぐらいいらっしゃるでしょうか。お願いします。","respondent":"田村総務部長","answer":"傾向ですが、款別でもお答えしたように、職場としては、保育・子ども育成関連で待機児対応等の関連、あるいは防災関連で東日本大震災以降の各種対応と、高齢者の地域支援で施設開設等あったこと、あるいは選挙管理委員会は急な都知事選等の対応があったということで。","voiceIndex":2,"id":"exchange-001"},{"speaker":"渡部委員","kind":"確認","question":"状況を確認させていただいて、きっと、８００時間、１,０００時間のほかにもそれに近い方々もいらっしゃると思うのですけれど、幾つか考えなど、この先述べします。ここ５年間のこれらの推移をお示しいただくとともに、低下に至った背景と要因がありましたら教えてください。真に必要とはどういうものなのか、判断基準をお示しください。そして、実際に人員配置をしてきた事例等があれば教えてください。","respondent":"田村総務部長","answer":"その間も、工夫としては、学校警備の委託あるいは住民情報のオンライン化、戸籍事務の電算化等を実施してきて、工夫した上で人件費率を下げてきたです。ここ数年でも、図書館業務の委託、指定管理者の導入等、今後もこのような努力を続けてまいりたいと考えております。","voiceIndex":4,"id":"exchange-002"},{"speaker":"渡部委員","kind":"質問","question":"さまざまなお話を伺えています。具体的なところでは、夜間町会長会議や火曜延長開庁時などで出勤時間の調節などは可能なのではないでしょうか。このような取組みをされているのか、またあわせてお考えをお聞かせください。","respondent":"田村総務部長","answer":"それと、夜間窓口や、あるいは特に地域センター等、勤務時間については現在のところ超勤対応ということでやっておりますが、定期的にも曜日を決めて残るということだと、翌日は例えば午後から出勤ということも、弾力的に考え得るご提案だと思いますので。","voiceIndex":6,"id":"exchange-003","title":"町会・自治会支援"},{"speaker":"渡部委員","kind":"意見","question":"よろしくお願いします。安倍総理の強い指導力のもとで改革が進められようとしており、区も今後、さらなる改善を行っていただくことになると思います。区職員の皆様が、仕事にやりがいと生きがいを感じて幸福感をお持ちいただかなければ、区民を幸せにすることはできません。最後に、本区におけるこれからの働き方改革に取り組まれる区のご決意をお聞かせください。","respondent":"田村総務部長","answer":"やはり、区というのも大きな１つの組織ですので、それを構成しているのは人、職員です。ですから、職員自体が、やる気なり、仕事に対する生きがいを感じないと、やはり区民サービスにも反映できないだろうと考えております。","voiceIndex":8,"id":"exchange-004"},{"speaker":"渡部委員","kind":"質問","question":"引き続きよろしくお願いいたします。次に、子育て支援について伺います。平成２２年より継続して、区は新規保育園の開設など対応してまいりましたが、平成２９年度当初においても待機児童が生じています。ここで質問いたします。平成２２年度から本年度までの、幼齢人口の推移、待機児童数の推移、待機児童解消に向けた施設建設などの区の取組み、予算の変遷をお知らせください。","respondent":"齋藤子ども未来部長","answer":"予算規模ですが、平成２２年度から、７３億円、８７億円、９６億円、９３億円、１０３億円、１３４億円、１５５億円、来年度予算は２０７億円を予定しております。","voiceIndex":10,"id":"exchange-005"},{"speaker":"渡部委員","kind":"質問・要望","question":"予算を今、伺いました。平成２６年、平成２７年、平成２８年と、平成２２年から比べても相当数、上がってきていて、これだけやっていても、まだまだ待機児童数に追いつかないということで、幾つか質問します。改めて、現状において計画のある平成２９年度の予定がわかっていれば教えてください。年度途中においてもさらなる充実の可能性があるのかどうか教えてください。","respondent":"齋藤子ども未来部長","answer":"平成２９年度の開設予定ですが、４月開設が、認可保育園が１０園ございまして、８１５人、定員拡大があります。認証保育所が２園で７０人、４月当初が８８５人になります。","voiceIndex":12,"id":"exchange-006"},{"speaker":"渡部委員","kind":"質問・要望","question":"さらなる待機児童解消に向けて、さまざまな手法を用いて取り組んでいただくよう、要望します。子どもの幸せ、生き抜く力の醸成、親育ちの支援等について伺っていきますが、児童相談所の都からの移管について、今後、実現に向けて、職員派遣を含め、準備が進められていることと承知しています。これにつきましては、さまざまな場面で会派からも要望しています。お願いします。","respondent":"齋藤子ども未来部長","answer":"その二、三区が各区にフィードバックをしてほしいという提案がございました。あり方検討委員会の筋論から言うと、なかなか承服しがたい提案ではございましたが、一歩でも進めたいということで、品川区をはじめ２２区はこれに応じたところです。","voiceIndex":14,"id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"続きまして、児童センター等について伺いますが、品川区の児童センターは、０歳から１８歳までの間、地域の子育てや活動を支えていただいています。最近の保護者の方に伺いますと、数多くのプログラムが用意された児童センターで、同じ悩みを持った仲間や同世代の仲間と知り合えて、子育てをされていると聞きました。子どもたちに幼少期、どのように接していらっしゃるのでしょうか。","respondent":"齋藤子ども未来部長","answer":"イクメンという言葉が時代に出る前、平成２０年当時から、品川区は乳幼児家庭の孤立を防止したり、親の育児不安を払拭したり、特に男親の育児への参加を促すという点で、親育ちワークショップ、赤ちゃんとのふれあい事業、父親の子育て参加促進事業。","voiceIndex":16,"id":"exchange-008"},{"speaker":"渡部委員","kind":"質問・要望","question":"２５館ある児童センターが、さらに地域の子育て拠点となるよう、お願いを込めて要望し、次の質問に入らせていただきます。１つエピソードを紹介します。結果が出ている品川区の教育について伺います。品川区の子どもたちが着実に自主性や自発性をつけていることは、今の話からも見てとれますが、最終的に社会に出てから苦労しない人となるには、より実践的な教育が必要なのではないでしょうか。","respondent":"本城教育次長","answer":"今後といたしましては、さらに文字通りの「主体的・対話的で深い学び」を充実・実現できるように、９年間の一貫した教育の強みを活かしまして、授業のあり方の研究・工夫を深め、広げていきたいと考えているところです。","voiceIndex":18,"id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"これから小中一貫の質問を続けしますが、次に学習指導要領について伺います。国では１０年ごとに改訂がなされます。次は平成３０年から先行実施、各自治体の教科書採択等に合わせて、小学校では平成３２年度から本格実施となります。さきの平成２０年時においては、国の教育が区に追いついたと言われておりました。今回の改訂のポイントをお示しいただくとともに、区の今後の改訂について伺います。","respondent":"本城教育次長","answer":"策定の組織といたしましては、今年度も立ち上げております品川教育検討委員会において検討し、各教科につきましては、その検討をもとに教科等の検討部会を設置いたしまして検討し、平成２９年度中の要領の策定を目指しています。","voiceIndex":20,"id":"exchange-010"},{"speaker":"渡部委員","kind":"質問・要望","question":"先ほどアクティブ・ラーニングの考え方も伺いました。次に、義務教育学校で行っている夏の勉強合宿について伺います。昨年も、これに参加した子どもたちから、勉強の仕方がわかったという声があることをお伝えし、さらなる開催を求めました。改めて伺います。やはり、今後、他の中学校においても勉強合宿を進めるべきと考えますが、いかがでしょうか、伺います。","respondent":"本城教育次長","answer":"勉強合宿についてですが、現在は義務教育学校６校についてのみ行っておりますが、今後といたしましては、義務教育学校以外の他の中学校の実施についても、より支援していきたいと考えているところです。","voiceIndex":22,"id":"exchange-011"},{"speaker":"渡部委員","kind":"確認","question":"これにつきましては、さまざまな、教員の負担の件ですとか学校の規模等の影響があると思いますが、今のお話を伺いますと、これからしっかりと進めていただけると確認させていただきました。コーディネーターの方々は、学校内の校務遂行に加えて、校外、いわゆる地域での校務も多くあると認識いたしますが、非常勤として、これらの時間等の取扱いはどのようになっているのでしょうか、現況をお聞かせください。","respondent":"本城教育次長","answer":"その中でのコーディネーターの勤務ということで、現在のところは、月８回・１日６時間、あるいは月１２日・１日４時間のような形を基本としていますが、今、３年間の計画配置を考えている中で、全校配置をしていく過程で、場合によってはコーディネーターがより働きやすいような。","voiceIndex":24,"id":"exchange-012"},{"speaker":"渡部委員","kind":"質問・要望","question":"問題点と課題もこれから多々出てくることと思いますので、ぜひ現場で活躍されている方々からさまざまなお話を伺って、最終的に品川区のスクールコーディネーターの方々が仕事をしやすい環境整備に努めていただきたいと思います。さらなる品川区の教育の発展と小中一貫教育の充実を、これからもますます求めてまいりますが、最後に教育委員会としての意気込みをお聞かせください。","respondent":"中島教育長","answer":"それもあわせて進めてまいりたいと考えます。今年度刊行いたしました「品川の教育」という冊子をめくりますと、これまで品川区立の学校は、地域の熱い思いと支援にいっぱい支えられて今があると考えることができます。","voiceIndex":26,"id":"exchange-013"},{"speaker":"渡部委員","kind":"質問","question":"これからもよろしくお願いいたします。続きまして、高齢者福祉について伺っていきます。区においても高齢者比率は上がり続けています。ここで、誰でもなり得る認知症への取組みについて伺います。厚生委員会にて報告を受けましたが、改めて、この品川くるみぷらんの内容と目的・意義についてお話しいただきまして、ガイドの配布について対象と時期をお聞かせください。","respondent":"榎本福祉部長","answer":"配布の対象と時期ですけれども、まず、４月１０日には、区ホームページへ掲載する予定です。４月中には、在宅介護支援センター、それから病院、診療所などの医療機関関係の機関に配布いたします。その後、６月には、６５歳以上の方のいる全世帯に配布する予定です。","voiceIndex":28,"id":"exchange-014"},{"speaker":"渡部委員","kind":"質問・要望","question":"６５歳以上の方々には全戸配布することは伺いました。全戸配布が無理にしても、この理解というものを促すためにしっかりと取り組んでほしいと思うのですが、これをどのようになさっていただくのか、区民の方に知らせていただくのか、６５歳未満の方に知らせていただくのか、お答えをお願いいたします。","respondent":"榎本福祉部長","answer":"具体的には、ケーブルテレビの番組の「しながわほっとインフォメーション」で、６月には「品川くるみ認知症ガイド」についての放送を予定しております。そのほか、各種イベント等を活用して、若年層や地域の方々への周知を図っていきたいと考えております。","voiceIndex":30,"id":"exchange-015"},{"speaker":"渡部委員","kind":"確認","question":"高齢者クラブについて１点確認させてください。これらの活動に対してきめ細かい支援を行っていると思いますが、活動にあたっての保険はどのようになっていますでしょうか、教えてください。不慮の事故の際の手続等についてもお聞かせください。簡単にできるものなのか、煩雑なものなのか。例えば口頭で報告をいただいて、会員でない方や行政等が代理で手続可能なのかどうかもあわせてお聞かせください。","respondent":"榎本福祉部長","answer":"高齢者クラブの保険の関係ですけれども、今現在、高齢者クラブは１１４クラブありまして、活動にあたっての保険は、全国老人クラブ連合会が推奨しております会員向けの傷害保険、賠償責任保険等があります。","voiceIndex":32,"id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"確認させていただきました。ないのが一番なのですが、これからまた不慮の事故等があった際には、しっかりと手当てできるような仕組みが必要だと思いまして、確認をさせていただきました。次に町会支援について伺います。品川区町会および自治会の活動活性化の推進に関する条例が制定されて１年がたちました。加入促進に向けて、区として可能な限り支援を要望いたしますが、お考えをお聞かせください。","respondent":"堀越地域振興部長","answer":"品川区町会および自治会の活動活性化の推進に関する条例、制定後１年の町会・自治会の皆様からの反応についてですが、本条例施行によりまして、町会および自治会の位置づけが明確になったということでございまして、皆様からは。","voiceIndex":34,"id":"exchange-017"},{"speaker":"渡部委員","kind":"質問・要望","question":"町会の方々も非常に喜んでおります。地域連絡調整員のほうも機能しているとも伺っておりますので、引き続き支援をお願いいたします。さまざまな活動を行っている町会ですが、款別審査でも伺ってまいりましたが、町会活動における、ふれあい保険が新年度から変更になると聞きました。内容等もお聞きしましたが、改めてこの変更内容と、各町会へどのような周知が行われていくのか、お聞かせください。","respondent":"堀越地域振興部長","answer":"このような形で、活動のさらなる活性化、町会・自治会の担い手確保にもつなげていただければと考えています。それから、周知につきましては、町会長会議等で、地域センターを通じて積極的に周知を図ってまいりたいと考えているところです。","voiceIndex":36,"id":"exchange-018","title":"町会・自治会支援"},{"speaker":"渡部委員","kind":"質問・要望","question":"さらなる町会活動支援に努めていただきたいと思いますので、よろしくお願いいたします。最後に、大井町にある東芝病院について区の考え方をお聞きします。東芝病院は救急指定で３０８床ある総合病院であることは承知しています。区内に数少ない分娩可能病院でもあります。本題に入る前に幾つかお聞かせください。同等の施策を受けられる他医療機関はあるのでしょうか、お聞かせください。","respondent":"西田健康推進部長","answer":"平成２９年度は乳がん検診の受診枠を増やしていただく予定です。気管支ぜんそくなどの公害健康被害認定に関する医学的検査も、年間１００件以上、実施しており、昨年開始したばかりではありますが、産後ケア事業宿泊型も実施しております。","voiceIndex":38,"id":"exchange-019"},{"speaker":"渡部委員","kind":"質問・要望","question":"東芝本社の経営問題の一環で、東芝病院売却についてマスコミで報道がされ、この間、区議会でも、区や区民にとって存在意義が大きく、一連の報道に憂慮し、全会派統一見解として、本年の２月６日に大沢区議会議長名で東芝社長宛てに、東芝病院存続に関する要望書を提出いたしました。この先どのように状況把握していくのか。行われるのであれば、どのような支援策が考えられるのか、お答えください。","respondent":"西田健康推進部長","answer":"区としての支援策につきましては、状況に応じてさまざまなケースが考えられますので、現在お示しする状況にはないと認識しております。したがいまして、今後も東芝本社および病院に関する情報に関し、東芝病院関係者との連携を密にし、引き続き情報収集に努めてまいるつもりです。","voiceIndex":40,"id":"exchange-020"},{"speaker":"渡部委員","kind":"質問","question":"今もお話しいただきましたように、これは区民にとって大切な病院ですので、しっかり私ども議会としても注視してまいります。区としてもこの動向を注視されて、区と議会がしっかり連携してこの問題に当たっていきたいと考えておりますので、よろしくお願いいたします。以上で私の質問を終わります。引き続き、石田秀男委員より続けします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"渡部委員に引き続きまして、総括質疑をします。久しぶりの総括ですので、よろしくお願いいたします。シティプロモーションについて伺います。私はその瞬間、やったと考えています。区長の言うシビックプライドとは何か、まずお伺いしたいのと、シビックプライドを醸成するために、今回の予算の中で、ここには力を入れたというところを、まず初めにお聞きしたいと思います。","respondent":"濱野区長、中山企画部長","answer":"そのことがシティプロモーションを通してシビックプライドにつながっていくのだろうと考えています。予算については担当の部長よりお答えをします。あるいは動画の作成もやってまいりますけれども、こういう中で、区民の参加、力を得ながらやっていく。こういう方法の中でも、今のシビックプライドにつなげるプロモーション活動というものは可能と考えています。","voiceIndex":44,"id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"意見","question":"区長は大体そう答えると思っておりました。例えば、前より必ずこのまちをよいまちにする。そういう中で、情報を今度、区のほうで発信する側、デザインする側、それからプロモーションする側に工夫がすごく必要だと考えていますし自分たちのよりよい生活をするために力を発揮したいと思えるようなプロモーションがあってしかるべきだと考えていますので、その辺をどうお考えなのか。","respondent":"濱野区長","answer":"１つの例でありますけれども、上神明天祖神社でしろへびサミットという行事を展開いたしました。この行事を通して、白蛇の、おもしろさと言うと変ですけれども、こういうもののＰＲというものを全国に発信したと考えています。","voiceIndex":47,"id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問","question":"ですから、先ほど、しろへびサミットも１つです。宿場まつりも１つです。ではどうしたらいいのだ。だけれども、ではどうしようか。それには、そういうさまざまなタウンミーティングと、私は、区がやはりそこは仕掛けていくべきだろうと思っておりまして、こういうことの考え方、そっちへ移行していくということが、私は非常に大切だと思っておりまして、改めてそこの考え方を伺いたいと思います。","respondent":"濱野区長","answer":"そういったことで、品川区のまちのよさを感じている人が自分の自負心を持ってこのまちを伝道していくのだという、少し大げさですけれど、伝道者になるのだというような方々をサポートしていくということが、品川区の大きな仕事ではないかと思っておりまして。","voiceIndex":49,"id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは、ぜひやっていただきたい。それから、私もこの質問をするときに、せっかくシティプロモーション担当ができて一生懸命、頑張っていらっしゃるのだけれども、観光だ、何だというときに、どうも横串があまり感じられなかった。もう、シティプロモーション担当が全てわかっていて、こういうことはこうやって、全部、指示していくのだぐらいの行政の体制があってほしい。この考え方もお願いしたい。","respondent":"濱野区長","answer":"これからもさまざまに展開してまいりますので、ご理解をいただければありがたいと思います。","voiceIndex":51,"id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問","question":"次は、広町再開発と庁舎建替えについて伺いたいと思います。広町地区整備検討委託６,０００万円について計上されておりますけれども、６,０００万円の中身についてまずお伺いしたいのと、ＪＲ東日本は２０２０年以降のスケジュールをどのように考えているのか、改めて互いに検討する上でのスケジュール感を区はどういうふうに考えているのか。そういうこともあわせてお聞きしたいと思います。","respondent":"藤田都市環境部長","answer":"広町地区の再開発ですけれども、まず６,０００万円ですけれども、基本的にはＪＲと一緒に共同で検討する部分、それから区が単独で検討する部分の２つがございまして、この検討を両方進める経費として、６,０００万円を見込んでいるものです。","voiceIndex":53,"id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問","question":"今、平成３１年度までには都市計画決定をしていきたいということでありますけれども、大変心配しています。その辺のところだと、スケジュール感に対して、またはさまざまな権利関係の話、この辺が非常に苦労するのではないのかと考えていますが、改めてそこだけ、スケジュール感と決意というのか、その辺をもう一回お聞きしたいと思います。","respondent":"藤田都市環境部長","answer":"一方では、都市計画的な部分については区のほうが主導すべき部分だとも捉えておりますので、まちづくりマスタープランで目指すべき大井町の実現はもちろん、区とＪＲ、両者にとってよりよいまちづくりの計画になるよう、しっかりと進めてまいりたいと考えています。","voiceIndex":55,"id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひよろしくお願いします。そこで、その前に１つ、オリンピック時のＪＲの社宅跡地の暫定利用についてですけれども、ＪＲ東日本も独自に考えを持っているということもお聞きしますが、区も必ずそこには積極的にかかわっていって、今一緒にやっていこうということであれば、ともに情報を早目に出していただきたい。","respondent":"藤田都市環境部長","answer":"庁舎建替えについては、こういったまちづくりの大きな動きの中で、耐震化等の工事は行ってありますけれども、建物本体の耐用年数的なこともありますので、こういった部分についても、どういった形でやるのが最適なのか、こちらについてはしっかり検討していきたいと考えています。","voiceIndex":57,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"さっきの話に戻ってしまうけれど、中小企業センターは東急と下神明までのことも含むので、その辺をもう一度、答弁をいただきたいと思います。これはこれで必要だからいいのですが、今後の二重投資みたいな話。この辺は、もう平成３１年にある程度検討していくとすると、やはり二重投資をする必要はないと私は思っておりまして、その辺の考え方を伺いたい。","respondent":"藤田都市環境部長","answer":"現在、広町地区の検討の中でも、一定の検討が進んだ段階で、今後、高架下の活用も含めた東急との調整が必要であると考えています。下神明も駅そのものが東急の駅ですので、周辺のあり方については、東急も含めてさまざまな意見交換をすることが必要であると考えています。","voiceIndex":59,"id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうなったときに、中小企業センターも含めてということはぜひお考えいただきたいと思っていますので、それは再度、再開発の網のかけ方というのは区でもやれるわけですから、その辺のところの考えをお聞きしたいと思います。これは手を入れていくということでありますけれども、この辺の異なってくるところを、どうやってこれから整理していくというお考えなのかも、お聞きしたいと思います。","respondent":"藤田都市環境部長、本城教育次長、中山企画部長","answer":"下神明のあたりのまちづくりの進め方ですけれども、来年度予算、平成２９年度予算には。そのような、ある意味できめ細かなフォローの中で体育館を使っているのが、現状ではあるかと考えているところです。そういう中で、こういう減免についてもあわせて検討する必要があるかと考えています。","voiceIndex":61,"id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"体育館なのですけれども、本当に皆さん、大変な中、やっていらっしゃる。ナイター照明などは１時間３,５００円ぐらい払っている。それから、免除団体からお金が取れないというのは、別にキャンセル料をつくればいいだけで、その辺はぜひ考えていただきたい。そういう減免団体、特に免除団体のあり方も含めて、この中で私はやっていくべきだと考えていますが、その考えをお聞かせください。","respondent":"本城教育次長、中山企画部長","answer":"こちらにつきましては、１点、今、委員のご指摘がございましたように、ランニングコストの問題ということについては、どうしても体育館は広くて遮熱性が低く、熱効率が悪いということから、ランニングコストの問題が１つです。団体の利用の実態も踏まえながら、より多くの方が利用される施設という方向での料金もあわせて、それからモラルを低下させないあり方についても考えていきたいと考えております。","voiceIndex":65,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"よろしくお願いします。もう一つ聞きたいのでそれぐらいにしておきますが、中学生の部活動について聞きます。それから、現在の区における部活動の加入率、８割ぐらいだと考えていますけれども、それをお聞きしたいのと、あとは指導者がいなくて廃部になった部活動などもあるのか、改めてお聞きしたいと思います。","respondent":"本城教育次長","answer":"基本的な部活の加入率ですけれども、運動部と文化部、合わせて８９％の加入率に今なっているところであります。運動部が５９％、文化部は３０％の加入率です。","voiceIndex":68,"id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"提案","question":"最後の質問になると思いますが、コミュニティ・スクールも始まります。その中で部活の指導員の活用も、またさまざま今後、動いてくるのだと思いますが、部活が地域とともに活動していくということも、これからコミュニティ・スクール等で考える。その中で、やはりそこは教育委員会がさまざまな形で提案して、その決意を最後にお聞きして質問を終わりたいと思います。","respondent":"本城教育次長","answer":"そういった中で、その活用の仕方として、地域との交流の中で指導者を得ることができれば、学校の質の向上とあわせて、地域の連携というコミュニティ・スクールの推進に通じる意義も十分達成できると考えておりますので、そういう観点から推進していきたいと考えているところです。","voiceIndex":70,"id":"exchange-033"},{"speaker":"あくつ委員","kind":"提案","question":"これは、都議会公明党が昨年の議会質問で提案し、１２月には小池都知事に直接要望した政策が反映されたものです。これに先立つこと５年前の平成２４年、区内小学校の保護者の声から、区議会公明党は一般質問で学校トイレの洋式化を求め、以来、繰り返し議会質問で取り上げ、洋式化のさらなる推進を訴え続けてきました。質問の１点目については、学校トイレについて伺います。","respondent":"本城教育次長","answer":"トイレにつきましては、児童・生徒が明るく清潔で気持ちよく使える場として、学校生活での基本的な生活習慣を学ぶ大切な場所であると考えているところです。その上で、洋式の考え方ですが、現在、原則として洋式化を進めていく考え方ではあります。","voiceIndex":74,"id":"exchange-034"},{"speaker":"あくつ委員","kind":"提案","question":"文部科学省への回答のとおり、品川区は今後、学校トイレを９０％以上、洋式化していく方針であるということを確認しますが、お考えを伺います。５年前から、区議会公明党は、トイレ改築に際し、教育の一環として、子どもたちが便器や室内のカラーリング・デザインを話し合い、実際にこれを活用することを提案してまいりました。今後の改築の際にもさらに活用していただきたいと考えますが、いかがでしょうか。","respondent":"本城教育次長","answer":"このような取組みにより、子どもたちが非常に親しみを持ちながらトイレを使っているような効果が出ているです。今後もそのような取組みを継続していきたいと考えているところです。","voiceIndex":76,"id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問・要望","question":"続きまして、本年の２月２０日には濱野区長に対しまして、学校・公園等トイレの洋式化促進に関する申し出を行い、東京都の予算を積極的に活用するなど、区立学校や公衆・公園のトイレの洋式化を強く要望したところですので、早急な洋式化をお願いいたします。質問の２点目は、公衆トイレ・公園トイレについて伺います。整備される予定のおもてなしトイレの考え方と、今後の改築スケジュールを教えてください。","respondent":"本城教育次長、松代防災まちづくり部長","answer":"洋式化の比率についてですが、委員のお話の調査の中で、区といたしまして、おおむね洋便器を設置するということの中で、洋式化比率約９０％ということで、その中での回答ですので、そのように記載した形において、今後。平成２９年度より実施します、おもてなしトイレ事業につきましては、２０２０年東京オリンピック・パラリンピックが開催される平成３２年の夏頃までに、観光名所である旧東海道や大井町駅周辺などの主要ターミナル駅。","voiceIndex":78,"id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"学校トイレについては９０％以上、目標を達成していくというご答弁をいただきました。質問の３点目は、女性にとって使いやすいトイレについて伺います。衛生面について、品川区の清掃の頻度を教えてください。最後に、来年度、おもてなしトイレの設置にあたり、女性の目線での区内のトイレの使いやすさ・衛生面・安全面の工夫について、イメージアップが必要と考えますが、ご見解を伺います。","respondent":"松代防災まちづくり部長","answer":"警備状況ですが、緊急ボタンを押しますと赤色ランプが点灯し、警備会社に通報されまして駆けつける体制となっております。これまでに、いたずらや誤作動による対応がありましたが、トイレでの事件・事故は起こっておりません。最後に、イメージアップについてのご質問です。","voiceIndex":81,"id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"地域共生社会の構築について質問いたします。本年２月、国は新たな福祉の概念として、地域共生社会を打ち出しました。品川区の人口推計で、今後、人口のピークが訪れ、その後、減少が始まる時期は、いつごろと推測されているのか教えてください。その意味で、国の提唱する地域共生社会を今後構築していく必要性についてご所見を伺います。","respondent":"中山企画部長、榎本福祉部長","answer":"人口推計に関するご質問にお答えいたします。現在の人口推計は、平成２８年３月に策定した品川区人口ビジョンですけれども、平成３９年に総人口はピークを迎えると考えております。したがって、今後１０年間は人口増を見込んでおります。地域共生社会の必要性についてお答えします。委員がおっしゃったとおり、地域住民や地域の多様な主体が参画し、分野を超えてつながるという、地域共生社会の考え方は必要であると考えています。","voiceIndex":83,"id":"exchange-038"},{"speaker":"あくつ委員","kind":"確認","question":"質問の１点目は高齢者分野です。先ほども話がありましたが、支え愛・ほっとステーションについて伺います。今後、制度が持続・拡充していくためには、双方が我がこととして、今後来るべき地域共生社会の構築であるという意識改革の工夫が必要と考えますが、いかがでしょうか。いずれにせよ、コーディネーター機能を、人数も含め、大幅に強化する必要性があると考えますが、ご見解を伺います。","respondent":"榎本福祉部長","answer":"支援員の世代を次につなげていくことも課題であると認識しております。この地域支援員を増やすのはなかなか難しいところですけれども、ワークショップやフォーラムなどを通じて、理解と参加を促していきたいと考えています。","voiceIndex":86,"id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問・要望","question":"認知症カフェについて伺います。認知症カフェ２種類の違いと補助の内容について教えてください。そして、展開に地域格差があるならば、社会福祉法人や民生委員、区内で約１万２,０００人が受講した認知症サポーターなどを活用し、認知症の人がアクセスしやすいよう、できるだけ偏りのない認知症カフェの全区展開を働きかけていただきたいと思いますが、いかがでしょうか。","respondent":"榎本福祉部長","answer":"相談支援包括化推進員のことですけれども、これについては、国の制度を使うよりは、まだ今、都からの制度を使っているほうが有利ですので、そちらでいく予定です。","voiceIndex":88,"id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問の２点目は障害者分野です。（仮称）障害児者総合支援施設と、施設での同性・異性介護について、あわせて伺います。既に高齢者サービスである在宅支援センターの併設も決まっております。地域共生社会の先駆施設として、例えば同施設の開設後、法人の自主事業として、こども食堂や認知症カフェなどを実施するなど、地域貢献事業の展開を促していただきたいと思いますが、いかがでしょうか。","respondent":"榎本福祉部長","answer":"地域共生社会型の施設として、さまざまな福祉との連携が図れると考えております。それで、障害児者総合支援施設では、従来の児童学園の領域・機能の拡充と、今後の障害者の状況やニーズに対応した総合的・継続的な支援を行うことを、まず第一として考えたいと考えています。","voiceIndex":90,"id":"exchange-041"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう一つ、同性介護が原則ということでありますが、約束できないと言われれば、これは例えば自分の妻や母親、娘がそういうふうに言われたら、やはりこれは利用できません。ですから、そこのところを、無理だからという説明ではなくて、できるだけ対応していくというご答弁をいただきたいのですが、お願いいたします。","respondent":"榎本福祉部長","answer":"社会福祉法人における自主事業の関係につきましては、まずは本来の役割を第一義的に進めさせていただきまして、それが安定軌道に乗ったところで、さまざまな先駆的事業についても検討していきたいと考えています。","voiceIndex":92,"id":"exchange-042"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問の３点目は、子どもと生活困窮者の分野です。そこで、生活調査の結果と分析、今後の方針を議会にお示しいただきたいと思いますが、いかがでしょうか。本大綱をもとに、品川区で策定予定の（仮称）子ども・若者育成計画などに子どもの貧困対策を組み込むなど、子どもの未来を応援する姿勢を明確に品川区が示すことは、根拠も意義もあることと思いますが、ご見解を伺います。","respondent":"齋藤子ども未来部長","answer":"子ども・若者計画ですが、国の子ども・若者育成支援推進大綱の中でも、子どもの貧困問題への対応ということは、大切な基本的施策の一つと位置づけられておりますので、委員ご提案の趣旨を踏まえ、計画を策定してまいります。","voiceIndex":94,"id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問・要望","question":"真の人権意識とは、幼年期からの繰り返しの人権教育や、障害者と触れ合う経験・体験から醸成されるものと考えられ、品川区においても、さらなるインクルーシブ教育、人権教育の進化が求められると思いますが、教育委員会のお考えを伺います。障害者の理解、人権意識の醸成として、子どもたちにアール・ブリュット展の鑑賞機会の創出を求めますが、障害者部門、そして教育委員会、それぞれのご見解を伺います。","respondent":"本城教育次長、榎本福祉部長、中島教育長","answer":"来年度、観賞を予定している学校もあるところです。特に、子どもたちにはできる限り見てもらいたいので、教育委員会とも連携し、工夫を図っていきたいと考えております。こういう、人権の基本的な部分を子どもたちにしっかり理解させるとともに、それを取り巻く私ども大人が共通の認識を持って、人権意識を。","voiceIndex":96,"id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１０年ぶりに改訂される新学習指導要領でも、今回、心のバリアフリーというものが入っているですので、アール・ブリュットを観賞する際には、ぜひ作品の作成過程の映像なども見ていただきたいと思います。以上で私の総括質疑を終わります。ご清聴ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"品川区の人口動向や将来の人口推計を念頭に、区有施設について質問いたします。品川区では平成２４年に、品川区公共施設有効活用プランを策定しました。ここでは、区有施設全体の約６割が建築後３０年を経過して老朽化する中、区の財政負担増への懸念と将来の人口減少を見据えて、効果的・効率的な区有施設のあり方をまとめています。当活用プランによってどのような効果が得られたのかお聞かせください。","respondent":"中山企画部長","answer":"荏原第四中学校等の移転の後は、私立学校への賃貸等、財産としての活用も行う。こういった事例が、１つの成果の具体例としても挙げられるものと考えております。","voiceIndex":102,"id":"exchange-046"},{"speaker":"塚本委員","kind":"質問","question":"さて、品川区は昨年、新たな人口ビジョンを発表いたしました。この人口ビジョンは、品川区の人口の現状分析に基づいて、人口の将来展望と、目指すべき方向性を提示することを目的としています。そのためには、新たに生じる区民ニーズや縮小する区民ニーズなど変化を的確に捉えることが必要と考えますが、どのように区民ニーズを的確に捉えるのかを踏まえて、区の公共施設の管理・運営について見解を伺います。","respondent":"中山企画部長","answer":"人口増がまた延伸したということの影響ですけれども、端的に言えば行政需要の増大というものが、今後考えられるです。特に子育て関係、あるいは学校の規模等については、この人口動向を踏まえた対応をしていく必要がある施設と考えております。","voiceIndex":104,"id":"exchange-047"},{"speaker":"塚本委員","kind":"質問・要望","question":"今後、施設のあり方というか区民のニーズというものは大きく変化してくるのではないかという思いもありまして、このような質問をさせていただきました。ぜひ、今、モニタリング、また世論調査、さまざまな手法のご案内がありましたけれども、区民ニーズを的確に捉えた施設のあり方を確認していただきたいと思います。区民集会施設について伺います。","respondent":"中山企画部長","answer":"したがいまして、より利用者の実態を踏まえながら、１つの施設の有効な利用のあり方というのを考えていくということで、先ほど例を出しました、ゆうゆうプラザのような事例では、多世代の利用も図っていくということでありますので、あわせて。","voiceIndex":106,"id":"exchange-048"},{"speaker":"塚本委員","kind":"質問・要望","question":"我が会派では、ひとり暮らし高齢者、ひとり親家庭、低所得者など住宅困窮者に、空き家を活用した住宅政策を求めてきました。居住支援協議会については、連帯保証人や家主の貸し渋りなど具体的課題を支援すること、また、新たな住民を迎え入れることが地域コミュニティの活性化にもなるといった視点も加えて検討いただきたいと思いますが、区の見解をお聞かせください。","respondent":"藤田都市環境部長","answer":"区といたしましても、こうした状況を踏まえまして、既に実施しております高齢者向けの住宅あっ旋、転居時の一時経費の助成、保証会社の紹介、保証料の助成などに加えまして、都で開催しております居住支援協議会連絡会のほうで得た情報。","voiceIndex":108,"id":"exchange-049"},{"speaker":"塚本委員","kind":"質問・要望","question":"少子高齢化社会を迎え、区民生活の変化に即応して的確な政策決定が求められると思います。区民集会施設、住宅系施設のみならず、文化、スポーツ、産業、子育て支援、福祉保健、学校教育など、公共施設が区民の暮らしに最大限に寄与するものとなるよう望むものでありますけれども、区執行部、企画部門として、現状の認識と今後の展望についてお聞かせください。","respondent":"中山企画部長","answer":"こういう観点での区民のための施設の整備をより充実させていきたい、このような計画をしていきたいと考えております。","voiceIndex":110,"id":"exchange-050"},{"speaker":"塚本委員","kind":"質問","question":"ぜひよろしくお願いしたいと思います。次に、少子化対策についてお伺いいたします。品川区人口ビジョンで示された将来の人口推計から想定される少子高齢社会に対して、品川区として対応すべき課題について初めにお伺いするとともに、平成２７年の品川区の合計特殊出生率が１.２３となったことへの評価と、目標としている平成３１年１.４５人を達成するための現状分析ならびに必要な対策をお聞かせください。","respondent":"中山企画部長","answer":"したがいまして、いわゆる年少の人口と高齢者への対応というのは違いが生ずるのかということで、年少者に対する対応としては、この１０年間の増というものを、ある意味ではどう乗り切っていくか検討したときに。","voiceIndex":112,"id":"exchange-051"},{"speaker":"塚本委員","kind":"意見","question":"理想を申し上げれば、人口を維持するために必要とされている合計特殊出生率が２.０７人ですので、これを目標として間断なく少子化対策を進めるべきものと考えております。ただ、子育て支援の助成ということにつきまして、助成政策なのですが、ここには所得制限というものが一般にあります。あわせて、多子計算にかかわる年齢制限という考え方がある理由についてお聞かせください。","respondent":"齋藤子ども未来部長","answer":"来年度以降、予算の計上をさせていただいておりまして、区税非課税世帯では、第２子の保育料は無償とする予定でおります。幼稚園保育料につきましても、制度設計は同様です。","voiceIndex":114,"id":"exchange-052"},{"speaker":"塚本委員","kind":"質問・要望","question":"そこで、多子世帯の子育て負担解消の必要性についての区の考えをお聞かせいただきたいと思います。現在の多子世帯の子育て支援における多子計算の年齢制限を仮に１８歳までに引き上げたとした場合、区の財政負担がどの程度になるのかということを伺うとともに、年齢制限のさらなる引き上げというものを検討しているですが、求めたいと思います。区の見解をお伺いいたします。","respondent":"齋藤子ども未来部長","answer":"１つ目は受益者負担の考えでございまして、保育料で保育の経費を賄えているのは約２０％弱です。こういった受益者負担のことと国の方針、財源ということがありますので、国の動向を注視しながら、国の動向を踏まえて拡充を検討してまいります。","voiceIndex":116,"id":"exchange-053"},{"speaker":"塚本委員","kind":"質問","question":"この多子軽減に関するお声は結構、最近多く伺うところがありますので、今、ご検討いただくということでしたので、よろしくお願いしたいと思います。次に、待機児童対策について伺います。品川区は、公園など公有地を活用するなどして、来年度、過去最多の１,０４４人の定員拡大をするとしています。あわせて、今後の保育の量の見込みに対する確保策をどのように考えているのかもお聞かせください。","respondent":"齋藤子ども未来部長","answer":"当初の計画では、平成２９年度に認可保育園６園、５６６名定員拡大、平成３０年度に６名定員拡大、５５１人の拡大で、ほぼ８０人ぐらいの余裕が生まれる予定でございましたが、現在ではそれを上回る想定で子どもの数が増え、入園希望者が増えているところです。","voiceIndex":118,"id":"exchange-054"},{"speaker":"塚本委員","kind":"質問・要望","question":"品川区として、これら都の予算を積極的に活用していただくなどして、区がこれまで進めてきた総合的な待機児童対策に一層尽力するように求めたいと思います。こういった施設においてどうなのか、保育施設の種類などについて伺いたいと思います。さらに、平成３０年度４月入園に向けた保育定員の拡大について区の見解を伺います。","respondent":"齋藤子ども未来部長","answer":"現場を回ったり、事業者とお話をしています。そういったことから品川区では開設によるつながり、区としても保育定員の拡大が図れるものですので、平成３０年度に向けて大きな受け皿の確保ができるよう、引き続き取り組んでまいります。","voiceIndex":120,"id":"exchange-055"},{"speaker":"塚本委員","kind":"質問","question":"ぜひよろしくお願いしたいと思います。款別審査でも保育士確保についてはさまざまな質疑がございましたが、保育士処遇に対する２３区の独自政策の現状について、品川区としてどのように考えているのかお伺いします。保育士の採用につきましては、ソフト的な面を強調した、例えば品川区の魅力を発信するなど、そういった政策も有効ではないかと思いますが、ご見解をお伺いします。","respondent":"齋藤子ども未来部長","answer":"保育士の確保についての上乗せの施策です。２３区で１１区が一定の上乗せの施策を実施する予定だということを確認しております。","voiceIndex":122,"id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"日本共産党を代表して総括質問を行います。私は待機児童ゼロを求めて質問いたします。父母の願いの１位は、認可保育園、保育園を増やしてほしい。２位、保育園の質の向上。この願いをかなえ、安心して子育ても仕事も両立の支援をしてくださいとの内容が届いていますが、どのように受けとめたのでしょうか、伺います。保護者の子育てに関する要望をどのように受けとめているのかお伺いします。","respondent":"齋藤子ども未来部長","answer":"平成３０年以降も新規園では定員差を３人以上、設けましたので、平成３０年からは２００人の定員差が設けられる見込みです。したがいまして、認証保育所を卒園された場合、３歳児の入園はほぼ全員が可能ではないかと考えております。","voiceIndex":127,"id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"直接話を聞く機会を得たのですから、ぜひ今後に活かしていただきたいと思いますが、認証保育所の子どもたちの３歳の壁が、今現在、乗り越えられないというのは非常に大問題であると思うので、早急に改善していただきたいと思います。入れなかった子どもたちはどうなっているのでしょうか。４月に一人の子どもも路頭に迷わせない丁寧な対応を、具体的にお伺いいたします。","respondent":"齋藤子ども未来部長","answer":"不承諾者に対する対応といたしましては、認証保育所のご利用が約４００人見込まれますので、認証保育所保育料の助成制度をご案内するほか、平成２９年度からはご議決を頂戴できれば、認可外保育施設を利用した場合でも保育料を助成する制度があります。","voiceIndex":129,"id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"部長のご説明だと、不承諾通知が届いた１,１６４人、路頭に迷わせることがないという受けとめでよろしいのでしょうか。改めてそこをお伺いします。申請者は３,５７５人、事前に数字を伺っておりました。入園の内定数は青色で２,４１１人。働く女性が増えてきた。深刻な事態を改善できない原因はどこにあるとお考えでしょうか、伺います。実態の把握と将来予測をどのように立てているのかお伺いいたします。","respondent":"齋藤子ども未来部長","answer":"あわせて、人口の動向、大規模マンション等の建設の動向を踏まえて、来年度以降、都の補助金、補助制度、スキームに加えて、区独自の仕組みを複数用意しておりますので、待機児解消に向けて認可保育園の開設を誘導していきたいと考えております。","voiceIndex":131,"id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問","question":"部長は今、民間の認可保育園でしょうか、誘導していくということでしたけれども、今までの従来の考えで待機児ゼロになるのかどうか、そう思っていらっしゃるのかどうか伺います。実態を正しくつかんでいるのでしょうか。本気の対策がとれているのでしょうか。４月１日の待機児は何人になるでしょうか。潜在的需要にも拡大して考えていくべきではないかと思いますが、いかがでしょうか。","respondent":"齋藤子ども未来部長","answer":"保育園のニーズが大変増えている。これは本会議でもご説明申し上げました。あわせて、品川区の人口も増えている。こういったことは、品川区だけではなく、国も都も予測しがたいところでございました。その要因は、女性の就労に対する意欲が増えている。","voiceIndex":133,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、ぜひ待機児の考え方。ですから、可能な限り、待機児と考えられる方を拡大して準備する。将来予測は難しい。でも、今後、平成５２年まで保育需要は伸びると予測していますから、保育需要に応えるべきであると思っています。保護者からは、小学校に待機児がいないように、保育園の待機児をなくしてほしい。いかがでしょうか。入園内定者が増えなかったのはなぜなのか、この理由もお伺いします。","respondent":"齋藤子ども未来部長","answer":"品川区は、平成２２年の待機児という言葉が本格化して以来、約３倍近い財源を投入させていただいて、認可保育園の開設、定員拡大に努めてまいりました。","voiceIndex":135,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほどの品川方式、４月１０日までに申請しないと待機児にカウントされない。児童福祉法第２４条１項の保育の実施責任がある自治体として、また区長は待機児ゼロを公約に掲げましたが、このまま来年の区長選を迎えていいのでしょうか。待機児ゼロ実現のため、品川区がみずから公設・公営保育園を増設することを求めますが、いかがでしょうか。民営化はやめるべきですが、いかがでしょうか。","respondent":"齋藤子ども未来部長","answer":"あわせて、私立保育園の方は不動産会社の方などと上手に連携しながら、今までであれば駐車場だったところ、あるいはワンルームマンションであったところ、さまざまな働きかけをして認可保育園の整備を進めていらっしゃいます。","voiceIndex":137,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私立の保育園のよさは大いに活かしていただきたいと思っています。でも、なぜ区立の保育園をこの段に及んでつくらないのか、納得がいきません。品川区は基金が９０３億円、そして土地も、探せば、国有地、都有地、区有地とあります。ぜひ総合対策に公立保育園建設を入れていただきたい。保育園をつくることが大きな経済的効果を生み出すと考えていますが、この点はいかがでしょうか。","respondent":"齋藤子ども未来部長","answer":"あるとき開設できても、翌年同じように開設できるとは限りません。やはり継続的に財源を確保し、待機児対策に対して大変効率的な進め方をするには、現在の手法が正しいものと考えております。","voiceIndex":139,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今のご答弁だと、なぜ公設公営の保育園をつくらないのかという私の疑問に答えていただけていないと思うので、もう一回お願いいたします。２０１６年の東京都における保育士の平均月額賃金の比較です。上が私立保育園、平均は２４万円です。全国福祉保育労働組合からは陳情が出ておりまして、ぜひ今の窮状を救うために、区独自の月１万円賃金加算の支援を求めていますが、どうでしょうか。","respondent":"齋藤子ども未来部長","answer":"あわせて、スピードアップという点です。用地を買い、区が基本設計、実施設計、住民対応をする、そして保育園をつくるより、民間の保育園の能力・ノウハウを活かしたほうが、スピーディーに待機児対策ができるです。処遇改善です。","voiceIndex":141,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問・要望","question":"このことが大もとにあるので、ぜひこれを変えるような動きをしてほしい。ぜひ、区の支援もしていただきたい。この間、私立と区立と遜色がないといった表現を、ずっと賃金のことでされていたのですけれども、今日私が示しましたこの差をどう受けとめていらっしゃるのか、もう一回お伺いしたいと思います。ぜひ区民参加、住民参加で、福祉を取り戻す区政の転換を求めますけれども、いかがでしょうか。","respondent":"齋藤子ども未来部長","answer":"私立保育園の区の支援ですが、先ほど、ほかの委員にご説明申し上げましたが、品川区は公定価格に５０％上乗せして負担金として交付しております。公定価格が約３０億円、区の上乗せが１５億円。１園にならしますと、４,０００万円から５,０００万円になります。","voiceIndex":143,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"提案","question":"現場の保育士一人一人は、大変な状況でお仕事をされています。最後に、今予算特別委員会、民生費質疑の中で、齋藤子ども未来部長の発言について、この場で改めて取消しを求めたいと思います。認識を改めていただきたいと答弁しました。区民の福祉増進のために区政をチェックし提案を行う予算審議を、選挙の票集めと批判するものであり、事実無根、議会を冒涜するもので取消しを求めますが、お答えください。","respondent":"齋藤子ども未来部長","answer":"私がその発言を取り消してしまうと、私立保育園の事業者、働く皆さんの思いを伝えることができません。したがいまして、私は取り消す考えはございません。","voiceIndex":145,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問","question":"区民の皆さんが、きっとこの発言を聞いて判断されると思います。私は断固抗議をして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-067"},{"speaker":"南委員","kind":"質問・要望","question":"飯沼雅子委員に続き、羽田新ルート計画の撤回を求め、質問します。３月２１日現在、回収は２,１７８通。羽田新ルート計画に賛成はわずか５％、反対は８１.７％です。一番多いのが騒音、９０.８％。この騒音についてのご意見を１つ紹介します。２番目に多かったのは墜落、６５.２％。低空飛行の羽田新ルート計画を区民はどう考えているのかなど、つかむべきではないでしょうか、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"国に対して地域への丁寧な説明会と情報提供を行いまして、これまで地域の声をしっかり聞くよう求めておりまして、フェーズ１あるいはフェーズ２における説明会、今年に入りまして２月１１日に開催した説明会にもつながっているところです。","voiceIndex":149,"id":"exchange-068"},{"speaker":"南委員","kind":"質問","question":"この結果をどう見るかと聞いたのですが、そのことには全く触れていません。改めて伺いますから答弁してください。国は昨年８月９日に環境方策を示しましたが、墜落や落下物などの事故はゼロを目指してもゼロにできないことがわかりました。これではゼロにはできません。改めて伺いますが、墜落や落下物をゼロにできると思っていますか、伺います。","respondent":"藤田都市環境部長","answer":"結果をどう見るかですけれども、先ほども申しましたとおり、国としても２８０余りの意見といったものを認識してございまして、この中には、期待も、不安の声もあります。そういった声と同様な意見なのかと考えています。","voiceIndex":151,"id":"exchange-069"},{"speaker":"南委員","kind":"質問・要望","question":"国が２８０出した意見にさまざまあるでは、答弁になっていないではないですか。そこをしっかり答えてください。区民の不安に応えることなのですから、答弁してください。墜落や落下物の危険を心配して中止を求める区民は、それぞれ６割を超えています。区はゼロにできるのか、改めて伺います。区民はゼロにできなければだめだと言っているのですから、国に「飛ばすな」と言うべきです。いかがでしょうか。","respondent":"藤田都市環境部長","answer":"落下物等についても、今ご答弁申し上げたとおりと同じようなことで、国としてしっかり対応してもらうことが大切であると考えています。","voiceIndex":153,"id":"exchange-070"},{"speaker":"南委員","kind":"確認","question":"不安の払拭に努めるというのではだめなのです。これをゼロにしてほしいと、区民はみんな、８割の方々がおっしゃるわけです。確認したいと思います。次に、３月１日の行財政改革特別委員会の議事録について質問します。今までの区の姿勢と違う答弁なので確認したいと思っての質問です。読みます。区は姿勢を変えたのでしょうか。品川区の上空を低空で飛行することを、区は認めたのかどうか伺います。","respondent":"藤田都市環境部長","answer":"今進めております羽田空港の機能強化に対する私どもの考え方ですけれども、羽田空港の機能強化を国が今、進めているところにつきましては、一定の理解はする。","voiceIndex":155,"id":"exchange-071"},{"speaker":"南委員","kind":"確認","question":"機能強化の部分だということですね。ということは、品川区の上空を低空で飛行することは、今までと同じという立場で捉えているということなのですか。確認したいと思います。","respondent":"藤田都市環境部長","answer":"区として、これまでの姿勢は変わるものではございません。","voiceIndex":157,"id":"exchange-072"},{"speaker":"南委員","kind":"質問・要望","question":"変わるものではないということ、答弁を繰り返しましたけれども、品川区上空を低空飛行で飛ぶことは了解していないという態度でいいということですか。もう一度答弁していただきたいと思います。それで、品川区の上空を低空で飛行することについての区の態度を改めて答えていただきたいと思います。今までと同じ立場なら、はっきりと訂正していただきたいと思います。","respondent":"藤田都市環境部長","answer":"そのことについて国としてしっかりと具体的な策を示してほしいということを申し上げているものです。これについては、これまでと同じ姿勢で現在も臨んでいるところです。","voiceIndex":159,"id":"exchange-073"},{"speaker":"南委員","kind":"質問・要望","question":"次に意見書の問題です。品川区議会は、昨年１２月７日に、国に羽田空港飛行経路についての意見書を提出しました。危惧を否定したのです。したがって、改めて伺いますが、国の進め方、羽田空港の機能強化に必要な施設整備に係る工事費・環境対策費を国が予算措置することについて、区議会の「危惧」と同じなのか、改めて伺います。議会と同じ立場に立つよう、改めて求めますけれども、いかがですか。","respondent":"藤田都市環境部長","answer":"意見書の中では、騒音、落下物や、その他事故の可能性、区民への影響の他、その対策、環境影響に配慮した方策について具体的に区民に説明すること、多様な手法について工夫をすることというような形で書かれてあります。","voiceIndex":161,"id":"exchange-074"},{"speaker":"南委員","kind":"質問・要望","question":"８月９日の配慮が出された。これについては具体的でないので、不安払拭を引き続き求めるというご答弁でした。とすると、改めて確認したいのですけれども、区議会と同じように、この国の状況あるいは環境方策、８月９日に出されたものについては、区としても議会と同じように危惧している。心配だ。こういう状況だということでいいですね。","respondent":"藤田都市環境部長","answer":"私どもが捉えておりますのは、意見書の中にあります記書き以降の部分、これらについてしっかり議会のほうと連携しながら進めていくべきと考えています。","voiceIndex":163,"id":"exchange-075"},{"speaker":"南委員","kind":"質問・要望","question":"改めて、区民の思いをしっかり受けとめて、品川区議会と同じように、同じ目線、ここに立つように強く求めておきたいと思います。次の問題にいきます。羽田空港の機能強化に関する都および関係区市連絡会について伺います。なぜ連絡会は一度も開かれなかったのでしょうか、伺います。要請しなかったのであれば、しなかった理由は何かも伺います。","respondent":"藤田都市環境部長","answer":"連絡会のほうの幹事会、部長級の会議ですけれども、これまで１３回、開かれてあります。課長級のワーキンググループにつきましては６回開催されておりまして、その連絡会そのものは、情報共有や意見交換を行うための会であり、意思決定をするようなものではございません。","voiceIndex":165,"id":"exchange-076"},{"speaker":"南委員","kind":"質問","question":"この連絡会は公開しています。ご存じだと思いますけれど。しかも、要綱をつくって設置した会議です。したがって、公開もされているし、議事録も当然とっています。だから要綱も設置しているのだと私は理解しています。改めてこの点について、なぜ開かれなかったのか。開きなさいと要請したのかどうかの答弁はありませんでした。部長が言ったということだけですけれども、その点について、もう一度伺います。","respondent":"藤田都市環境部長","answer":"しかしながら、飛行経路については、関係自治体の中でもそれぞれさまざまな感じ方を持っているところですので、品川区独自の要望等については、やはり直接、国に伝えるのがいいのかと考えているところです。","voiceIndex":167,"id":"exchange-077"},{"speaker":"南委員","kind":"質問","question":"直接伝えるということではなくて、正式のルートできちんと必要な発言をすることが大事なのではないですか。水面下でやっていて、東京都議会でも今、さまざまな問題が出ているではないですか。それと同じことになるわけではないのですか。後で禍根を残すようなやり方はやるべきではありません。万が一にでも墜落したらどうなるのですか。その辺についての連絡会の認識を改めて伺いたいと思います。","respondent":"藤田都市環境部長","answer":"それらをもとに国にも伝わっておりますし、区独自の話としては、またその場の中では、やはり状況がさまざま異なることから共通認識になかなかなりにくい部分もありますので、国に直接伝えていく。","voiceIndex":169,"id":"exchange-078"},{"speaker":"南委員","kind":"質問・要望","question":"正式なルートで言わないから、幾ら言っても回数を重ねても実現できない、その具体的な例なのではないでしょうか。言うべきことは言う。それが大事だと思うのです。連絡会を開くように求めたいと思います。いかがでしょうか。そして、そこで区として、８割の区民が反対している状況をつかんだ上ですから、反対するよう求めたいと思いますが、いかがですか。","respondent":"藤田都市環境部長","answer":"区としては、機能強化については一定の理解はするものの、騒音などの環境対策、あるいは安全対策については、いまだ十分とは言えないと考えていますので、環境に配慮した具体的な方策をまずは明らかにするよう国に求めていくのが、今、重要なことであると考えています。","voiceIndex":171,"id":"exchange-079"},{"speaker":"南委員","kind":"意見","question":"私は、改めて、区が勇気を持って、国に区民意思を伝えるべきだと思います。強調したいと思います。それが住民の命と暮らしを守る自治体の責任だからです。このことを強く主張して、以上で終わります。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":173,"id":"exchange-080"},{"speaker":"いながわ委員","kind":"質問・要望","question":"アスリートへのさらなる支援を考えるのであれば、個人への助成額の増額、もしくは新たに助成枠を創設すること、団体になれば経費もかさみますので、団体への助成額の増額をお考えいただきたいのですが、本区のご所見をお伺いしたいと思います。あわせて、幅広くアスリートの発掘・育成支援を行う観点で、助成対象の個人・団体の拡大をお考えいただきたいのですが、本区のご所見をお伺いしたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"私からは、アスリートの支援に対するご質問にお答えいたします。東京２０２０大会が決定いたしまして、私どももアスリートの支援をしていこうということで考えてあります。","voiceIndex":175,"id":"exchange-081"},{"speaker":"いながわ委員","kind":"質問・要望","question":"こういった助成金をつくるということが、やはり発掘、そして育成にもつながっていくと思いますので、また今後、一年一年、時を過ぎるごとに１回、見直しをしていただいて、助成額の増額もお考えいただきたいと思います。明治３８年から大正３年までの毎夏、多数の市内や周辺の小・中学生たちの水泳の鍛錬が行われたと。今後の事業展開をどのようにお考えなのか、本区のご所見をお伺いしたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"そのような方々を品川区に招請しまして、区民の皆さんに講演をいただいたり、また体験授業をする中で、区民の皆さんのスポーツの向上を図り、また感動と勇気を与えられればと考えています。","voiceIndex":177,"id":"exchange-082"},{"speaker":"いながわ委員","kind":"提案","question":"これは提案です。こうした部分、小・中高生を対象にしたスポーツ体験教室を日本体育大学としっかり連携して行うことも必要ではないかと思いますので、ご所見をいただきたいと思います。来年度というか、再来年度になるかもしれませんが、しっかり連携をとっていただきたいと思いますが、いかがでしょうか。","respondent":"安藤文化スポーツ振興部長","answer":"実際に子どもたちにメダリストなどの練習風景を見てもらって、また交流もさせていただきました。そのような形で、実際の実技にかかわるスポーツ教室もはじめ、そのような体験授業も含めまして、今後とも事業展開をしていきたいと考えています。","voiceIndex":179,"id":"exchange-083"},{"speaker":"いながわ委員","kind":"質問","question":"今年度の施政方針では、外国人旅行者の宿泊への対応として、民泊についても品川区版の制度整備を行うとありましたが、１年がたつ現在、民泊を取り巻く環境が日々変化している中で、事例や国の動きなどに鑑みて、何らかの手法は研究されたのでしょうか。国家戦略特区における民泊の指定は、結果として、大阪府とお隣の大田区のみであったことに対して、品川区としてはどのようにお考えかお伺いします。","respondent":"中山企画部長","answer":"それで、いわゆる国家戦略特区が広がらなかったことに関する区の認識ということですが、その後、北九州も指定されておりますけれども、この国家戦略特区については、宿泊日数の制約、それから面積要件、それから周辺住民に対する説明等、かなり現実に制約があって。","voiceIndex":181,"id":"exchange-084"},{"speaker":"いながわ委員","kind":"質問","question":"今、部長がおっしゃったように、３月１０日に住宅宿泊事業法案が閣議決定され、特区とは異なり、日本全国でそれが解禁されると報道がありました。近隣住民のトラブル回避や、許認可のもと宿泊業を営まれている事業者もいらっしゃるので、これに関しては早急に条例制定をする必要があると考えますが、本区のご見解というか、今後の予定をどう思われているのか、ご答弁をお願いします。","respondent":"中山企画部長","answer":"当然ながら、区としても非常に注視して、条例制定に向けての必要性というものを認識しておりますが、実は法案ですと、これは東京都の事務について保健所設置市が行う場合には、協議を行うというのが前提になります。","voiceIndex":183,"id":"exchange-085"},{"speaker":"いながわ委員","kind":"質問","question":"来年の１月から施行されるという話でありまして、この民泊法が、不足する宿泊施設の根本的解決になるかどうかわかりませんけれど、１つの手法として条例制定を早急にお願いしたいと思います。あえて数字はお伺いしませんが、本区の宿泊施設の現状、これで今後の国内外の来訪者を受け入れる体制ができているのか。これは単刀直入にイエスかノーかになってしまうかもしれませんが、わかる範囲でお伺いします。","respondent":"中山企画部長","answer":"これからオリンピック・パラリンピックと迎えることを考えますと、現状のままでは、さらに逼迫する、いわゆる宿泊施設の不足というものが懸念されるという認識を持っております。","voiceIndex":185,"id":"exchange-086"},{"speaker":"いながわ委員","kind":"質問・要望","question":"品川区内のあるホテルも、宴会場を潰して全部客室にしてしまったという事例もあります。民泊を含む、旅館業法上の簡易宿所、シェアハウス、以前、本多委員長からも質問がありましたホテル誘致など、あらゆる宿泊手法を駆使していただき、課題解決に取り組んでいただきたいと思いますが、ここで一言、何かあればお願いします。","respondent":"中山企画部長","answer":"宿泊施設の不足というのは、品川区を訪れる方への制約にもなるということで、これについては、さまざまな手法、民間の力を誘致するような働きを含めて、区としてもしっかり、できることをやっていきたいと考えております。","voiceIndex":187,"id":"exchange-087"},{"speaker":"いながわ委員","kind":"質問","question":"これは、東京２０２０大会を含む、多少、都市型観光的なあれに入ってしまうかもしれませんが、お伺いしてまいります。しながわ」や、東海道五十三次の絵というのですか、あと品川区の観光大使に今ご就任されましたシナモロール、通称シナモンとその関連キャラクターをラベルにデザインすることが、また話題性やＰＲ、おもてなしの効果につながると考えますが、本区のご所見をお伺いします。","respondent":"安藤文化スポーツ振興部長","answer":"そういうものも充実していきながら、委員ご提案の水のペットボトルの販売等につきまして、今後、関係機関ならびに企業と相談しながら、可能性について研究を深めてまいりたいと考えています。","voiceIndex":189,"id":"exchange-088"},{"speaker":"いながわ委員","kind":"質問・要望","question":"東京２０２０大会からの都市型観光というか、品川区のＰＲでは必要ではないかと考えています。まさに、都市型観光からの脱却で、品川型都市観光を樹立というか確立していただきたいなどと思っているところです。ですから、それをしっかりとおもてなしをするということが、僕は大切だと考えていますので、今からでもできると思いますので、ぜひ検討していただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-089"},{"speaker":"石田（し）委員","kind":"質問","question":"いながわ貴之委員に引き続き、総括質疑を行います。私からは、ダイバーシティについてと観光施策について、２点をお伺いいたします。今、働き方改革が急ピッチで進んでいる３つの理由というのがあります。１つが人口および労働人口の減少であり、２つ目が長時間労働の慣習を改善する必要性、そして３つ目がダイバーシティマネジメントの推進と生産性向上であります。よろしくお願いします。","respondent":"田村総務部長","answer":"その中身が、まさに子育てや介護の職員を支える環境づくりという内容で、細かくは申し上げませんが、出産支援の休暇や育児参加の休暇、管理監督者への登用や超過勤務の縮減という形を盛り込んだ内容で、目標値を定めて、これに向けて取り組んでいる内容です。","voiceIndex":193,"id":"exchange-090"},{"speaker":"石田（し）委員","kind":"提案","question":"そこで、ダイバーシティマネジメントについて、まず区の考えと、今後の取組みについてお伺いいたします。そういった意味で、このダイバーシティマネージャーの育成と、いわゆる担当職員の配置を提案いたしますが、その点もあわせてお答えください。よろしくお願いします。","respondent":"田村総務部長","answer":"具体的には、例えば研修を通じて職員に対して周知する。あるいは、先ほどの計画の中にも、人事課に、仕事と子育て両立相談窓口ということで担当者を置いておりまして、そこで制度や手続の紹介、看護師・カウンセラーによる健康相談等も実施しているという内容です。","voiceIndex":195,"id":"exchange-091"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"まさに管理職の方がまず先頭に立って、マネージャーとして活躍していただくことを要望します。ダイバーシティの発信と推進について、区民、区内企業を含めて、ぜひそういったことを、まずは区の内部から取り組んでいただいて、それを今度は外部へと発信していただきたいと思いますが、その点をお伺いします。そして、このダイバーシティの中にワークライフバランスもあります。お願いします。","respondent":"田村総務部長","answer":"さらにこのような取組みを進めてまいりたいと考えております。例えば２０時に退庁を促すとか、１８時ごろ帰宅を促す庁内放送を流すとか、あるいは可能なら職場のノー残業デーを週２日に増やす等、工夫して、残業時間の縮減に努めてまいりたいと考えております。","voiceIndex":197,"id":"exchange-092"},{"speaker":"石田（し）委員","kind":"質問","question":"ぜひよろしくお願いいたします。そのような中で、１つの制度や働き方で全てのニーズを満たすのではなくて、さまざまな選択肢を用意して、合ったものを選択して使える制度をぜひとも整えていただければと思います。それで、働き方について幾つか質問をいたします。これまでの取組みと今後についてのお考えをお知らせください。そしてＩＣＴの活用と機械化についてであります。よろしくお願いします。","respondent":"田村総務部長","answer":"それと、夜間延長窓口や夜の会議などというのも、やはり柔軟に検討していくことは可能かと思ってあります。","voiceIndex":199,"id":"exchange-093"},{"speaker":"石田（し）委員","kind":"提案","question":"この予算規模を見ても、本当に品川区が観光に力を入れていくのだと思います。これは要望で終わります。次に、以前もご提案いたしましたが、予算特別委員会の中でも、シナモロールのサポーターズクラブみたいなものができるというような話もありましたが、これはぜひ品川区全体でのサポーターズクラブの設立を、改めてお願いします。お願いします。","respondent":"中山企画部長","answer":"具体的な話として「いいね」やハッシュタグということでありますけれども、おそらくこれは、１つは素材そのものがインパクトがあることと、やはり「いいね」などをもらうための打ち出し方というのですか、仕掛けも必要かと考えていますので、そういう点でも。","voiceIndex":203,"id":"exchange-094"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ＪＴＢも非常に、観光、また旅行業にとってはさまざまなノウハウを持っていますので、もちろん品川区の観光振興協議会のメンバーであることは承知しておりますが、ぜひ、区内の企業でありますので、私はこれは、さらにＪＴＢと連携をとって、観光に向けて取組み強化をしていただきたいと思いますが、その点、いかがでしょうか。なので、このオープンデータの活用促進についても区のご見解をお聞かせください。","respondent":"安藤文化スポーツ振興部長、中山企画部長","answer":"その方はまた観光協会の理事でもあります。そのような中で、非常に助言、アドバイスをいただきながら進めているところですので、今後ともスクラムを組んで進めていきたいと考えています。オープンデータに関するご提案でありますけれども、現在、１０種類ほどのデータは既に加工できる形で出しておりまして、もともとは例えば避難所であるとか、区の公共施設のロケーション、こういうものから出していたのですけれども。","voiceIndex":205,"id":"exchange-095"},{"speaker":"石田（し）委員","kind":"意見","question":"今年の２０１７年は、実はアニメの１００周年だそうであります。日本のアニメーションが初めて公開されてから今年で１００周年を迎える中で、各自治体や多くの企業でさまざまなイベントを行うようであります。アニメ業界が、アニメを１００年後も残していこうということで、「アニメＮＥＸＴ１００」というようなプロジェクトも始動されました。","respondent":"安藤文化スポーツ振興部長、中山企画部長","answer":"私からは、アニメの１００周年の取組みについて回答します。オープンデータですけれども、区民の声を聞きながら、まずデータの数を増やし、また利用しやすさを考えていきたいと思っています。","voiceIndex":208,"id":"exchange-096"},{"speaker":"須貝委員","kind":"質問","question":"維新・無所属品川を代表して、須貝行宏が総括質疑を行います。教員の長時間労働についてお伺いします。日本では多くの企業において、長時間労働や、それに伴う過労死等が問題となっております。厚生労働省の長時間労働削減推進本部は、これらの是正について強力に取り組む方針を示したと言われていますが、品川区の職員の長時間労働の実態と、区の人事課の対応について教えてください。","respondent":"田村総務部長","answer":"一般の職員の超過勤務の状況ですが、平成２７年度、８００時間超えが３０人で、うち１,０００時間を超える超勤の職員が１０人ということでございまして、主に職種とすると事務職というのが実態です。","voiceIndex":214,"id":"exchange-097"},{"speaker":"須貝委員","kind":"質問","question":"今、品川区役所の人事課のお話をお伺いしました。文部科学省の調査によると、２０１５年にうつ病などの精神疾患で休職した公立学校の教員数は５,００９人もいます。連合総研の調査では、公立の小・中学校教員の１日平均労働時間は約１３時間もあり、そのうち１５％が朝７時前に出勤し、２２％が夜９時以降に退勤するということです。教員の長時間労働を把握していますか、教えてください。","respondent":"本城教育次長","answer":"ただ、教員については、そういう意味で、個々の教員の働き方自体は、学校におきまして、校長等を中心にして、個々にその実態を把握しているような形です。そういう意味で、超過勤務のあり方自体が一般の職員と違う関係で、数値的なデータを持ち合わせているものはございません。","voiceIndex":218,"id":"exchange-098"},{"speaker":"須貝委員","kind":"質問","question":"今お話を伺いましたが、さらに部活の顧問をすると、さらに忙しくなり、本来の教員の仕事に手が回らず、残業や持ち帰り仕事の時間量が多くなった現状、そして生徒としっかり向き合えない現状を改善してほしいと、公立中学校の教員の皆さんが署名を呼びかけたところ、２万３,０００人以上の署名が集まり、文部科学省に届けられております。品川区は、独自の教育制度を、１０年ごとにさまざま改定しています。","respondent":"本城教育次長","answer":"その中でも、例えば教員の健康管理の面では、例えばストレスへの対応ということもありますので、今年度、平成２８年度からも、教員のストレスの状況について、今までとまた違う形で、新たなやり方で見直したり、さまざまな形で、教員の種々の健康管理について努力しています。","voiceIndex":220,"id":"exchange-099"},{"speaker":"須貝委員","kind":"質問","question":"それならば、先ほど、区の人事課、総務部長がおっしゃった、何時間、長時間労働しているとか、そういうデータは出ないのですか。出ないとおかしいですよね。仮に月給が４０万円の教員は、残業代は最大で１万６,０００円だけしか出ていないのです。そして、品川区も教員の勤務実態をしっかり改善する方向に私は持っていくべきだと思うのですが、この辺についてどのようにお考えでしょうか、お答えください。","respondent":"本城教育次長","answer":"ただ、それは、先ほどの繰り返しになりますが、そういった数量的な把握をしていないことは、勤務の特殊性の関係ですが、当然、一人一人のきめ細かな健康管理はしないといけないということはありますので、学校長を中心とした管理体制。","voiceIndex":222,"id":"exchange-100"},{"speaker":"須貝委員","kind":"質問","question":"なぜ、もっと早く改善できないのでしょうか。ですけれど、実際、この方たちはおおむね、朝７時半に出てきて、夜７時半に帰る。１２時間労働です。そして、さらに先ほど調査もありましたが、さらに１時間、持ち帰りの労働をしています。このように、大変ではないですか。だったら、同じ労働者である教員にも同様に、私は残業手当を出すべきだと思いますが、お答えください。それもお答えください。","respondent":"本城教育次長、田村総務部長","answer":"学校の教員の健康管理等の関係ですが、まず１つは、教員の職務の特殊性ということで、先ほどもお話ししましたが、教員の職務は基本的に、自発性、創造性に期待するという面が多い関係で、時間の管理の手法だけでは。ですから、その分の調整額ということで、給料が行政職より高くなっているということですから、私たち行政の職員ですと、事前に、今日は残りますと言って、事前命令を受けて超過勤務をやるのですが、教員の場合には。","voiceIndex":224,"id":"exchange-101"},{"speaker":"須貝委員","kind":"質問","question":"これはどう考えてもおかしいでしょう。品川区が先鞭で、やはり変えていかなければいけないのではないですか。こういう実態は、かわいそうではないですか。一般企業ではどうですか。では、次の質問にいきます。しかし、せっかく教えても、早ければ３年を経過しますと、品川区外の地域へ転出が可能になります。予算の裏づけがある教育特区はつくれないものでしょうか。教育委員会のご見解をお聞かせください。","respondent":"本城教育次長","answer":"それと、ただ品川区の教育を進めてもらう軸となる教員を育成していくという面では、１つは、教職員の人事についての権限を市町村、区のほうに移管するということについては、かねてより、国あるいは都に要望し続けているところです。","voiceIndex":227,"id":"exchange-102"},{"speaker":"須貝委員","kind":"質問","question":"例えば私立学校なら、その中で、教員はほとんど異動はありません。ですが、これは公立校の欠点だと思いますが、あと市もそうです。だから、品川区もそういうふうにしないと、やはりできないのではないですか。品川区が人事権を持たない限り、このままいったら、小・中学校の２つの教員免許を持った教員は集められなくなってしまうのではないですか。その辺についてご見解をお聞かせください。","respondent":"本城教育次長","answer":"義務教育学校につきましては、今現在、制度の移行期ですので、今の免許の取得については、その移行期の中でしっかり対応できている状況ですが、将来を見据えて、今も義務教育学校には優先的に、両方の免許を持っている人を配置したりしながら。","voiceIndex":229,"id":"exchange-103"},{"speaker":"須貝委員","kind":"質問・要望","question":"このような大きな財源が残るなら、予算を使い切れないなら、その一部を区民にお返しするべきではありませんか、教えてください。予算は立てるだけではなく、実際に行われた事業やコストが発生していく過程で、計画された金額から大きく外れることがないようにコントロールすることで、初めて予算を立てた意味が出てくるのだと思うのですが、その辺について財政にお聞きしたいと思います。","respondent":"秋山財政課長","answer":"進行管理、進捗を行っておりますし、それぞれの所管において、部長、課長のレベルでも、進行管理、進捗を行っているというところで、しっかりとコントロールをしていると考えているものです。","voiceIndex":231,"id":"exchange-104"},{"speaker":"須貝委員","kind":"質問","question":"それはもうわかります。ただ、やっていて、やはり１００億円単位のお金を、そうやって使い残してしまう。これは、さまざまありますよね。そして、毎月毎月、ちゃんと財政課題を見ているわけですから、これだけ残りそうだ。大事なら、もっと、やはり真剣に、「こうやって、こうやって、ふるさと納税で持っていかれないように考えます」という姿勢も私は大事だと思うのですが、お考えをお聞かせください。","respondent":"秋山財政課長","answer":"１００億円単位で残しているですけれども、リーマンショックの後、区の財政としては１００億円単位で減っているわけです。そういうところを見据えて基金というものが制度上、存在しているです。","voiceIndex":233,"id":"exchange-105"},{"speaker":"須貝委員","kind":"質問","question":"皆さんの基金。私は、基金をため込んでいるなど、一度も言っていません。今言った、次に使う。そういうことをやはり考えて、財政というのは持っていかないと、区民との会話が何もないではないですか。それで、本当にお金が大事なら、やはり減収８億円ということに対して、国の政策が間違っていようと何をしようと、ではそれに抵抗して、品川区としては、こうやって減収をとどめるのだ。","respondent":"秋山財政課長","answer":"そこには、困っている方に対しての事業も当然入ってありますので、それについては必要なときに必要な事業を行っていっている。そういうことを今後も続けていきたいと考えているものです。","voiceIndex":235,"id":"exchange-106"},{"speaker":"須貝委員","kind":"意見","question":"それならば、実際、年度末になって、では決算が出ました。そうしたら、一旦、基金に入れないで、これだけのお金が残りました。それで、翌年度、しっかり基金に繰り入れました。それだったら、そういうふうに、区民にわかりやすいようにやればいいです。以上で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":237,"id":"exchange-107"},{"speaker":"田中委員","kind":"質問・要望","question":"品川区の保育政策、羽田飛行ルート変更、情報公開の運営、義務教育学校について伺います。最初に、品川区の保育施策について伺います。待機児童解消のために、今年は１４園もの認証・認可保育園がつくられることは歓迎します。処遇改善は、正規職員だけに限らず非常勤保育士へも求められます。品川区では、区立・私立の非常勤職員に対し、それぞれどのような処遇改善を行っているのでしょうか、伺います。","respondent":"齋藤子ども未来部長","answer":"あわせて、随時、一般指導検査を行うとともに、合同の研修会の実施や、心理士といった方を各私立保育園・私立幼稚園に派遣いたしまして、特別な支援を要する児童に対する指導の方法等を教授いたしまして、各私立保育園の保育士のレベルアップ、質の向上を図っております。","voiceIndex":239,"id":"exchange-108"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど区立・私立の非常勤職員に対しての処遇改善について伺いました。品川区が今以上に私立保育園にかかわり、私立園の特徴を活かしつつ、「のびのび育つしながわっこ」を活用して、品川区としての保育を私立園へ進めてほしいと要望いたします。続けます。事業者とはどのような協議がされ、具体的に成果としてどのような整備がされたのでしょうか、伺います。","respondent":"齋藤子ども未来部長","answer":"東品川四丁目地区では、これはまだ計画段階ではありますが、ここでも開設が予定されており、平成３２年、大井一丁目南地区、平成３３年、大崎三丁目地区、それぞれ開設あるいは開設に向け、協議を精力的に進めているところです。","voiceIndex":241,"id":"exchange-109"},{"speaker":"田中委員","kind":"質問・要望","question":"「のびのび育つしながわっこ」が、渡すだけではなく、十分に活用されるように要望します。人口増ばかり先行し、公共施設がパンクしてしまうようなことはあってはならないことだと思いますので、しっかりと具体的な協議と整備の実現を要望いたします。教室型の説明会を区として求めていると伺っていますが、なかなか実現しないことについて、どういう理由があると考えていらっしゃるのでしょうか。","respondent":"藤田都市環境部長","answer":"国がしっかりと説明するのがまず一番重要であると考えているところです。","voiceIndex":243,"id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"区民が求めているのは教室型の説明会です。請求者側には手続の提出期限が９０日という定めがあるのですが、処分庁の対応には定めがないのでしょうか。そして今回、なぜこのように１年以上の時間がかかったのでしょうか。情報という性質上、できるだけ早いことが求められると考えますが、見解を伺います。今回の事例については教育委員会への審査請求であったので、教育委員会からも見解を伺いたいと思います。","respondent":"中山企画部長、本城教育次長","answer":"審議会のほうについては、開催のスケジュール等もあるのですけれども、おおむね、この１０年の４件の諮問については２カ月程度で答申を行っているという状況です。そういう事情がありましたので、公開請求があった請求人も、その経緯を、おわびも含めてご説明させていただいたところです。","voiceIndex":245,"id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど、おおよその期間でさまざまですが、最長でも８カ月ということを伺いました。私たちは１年以上かかっていると思うのですけれど、なぜこのように時間がかかったのかというのをもう一度伺いたいと思います。市民が知る権利として有効活用できるよう、丁寧な説明と迅速な対応を強く求めます。最後に、２０１６年４月に始まった義務教育学校について伺います。そこで伺います。","respondent":"本城教育次長、中山企画部長","answer":"義務教育学校のことに関してですが、当初、本会議で答弁したときに、義務教育学校への移行についての説明の中で私がご答弁させていただいた関係です。行政不服審査の手続に関する件数について、１点だけすみません。平成２７年度の不服申立ての件数は３件でございました。","voiceIndex":248,"id":"exchange-112"},{"speaker":"田中委員","kind":"質問","question":"情報公開のほうは了解しました。この通知を読むと、この法律が想定している義務教育学校のイメージがわかります。この通知に基づいて３点質問いたします。１点目は、義務教育学校の標準規模を伺います。２点目は、国が考えていた義務教育学校は、品川区のような、小学校３クラス・中学校５クラスという構成を想定していなかったのではと考えるのですが、区の見解はいかがでしょうか。","respondent":"本城教育次長","answer":"ただ、今ご説明しましたように、地域の実態に即した形で、それぞれ形をつくれるですので、全国ベースで言えば、例えば１つの地域に１つの小学校と中学校を義務教育学校にするとか、さまざまな例がある中で、品川区としては、既に学区域を持った。","voiceIndex":251,"id":"exchange-113"},{"speaker":"田中委員","kind":"質問","question":"同学校教育法等の改正の通知には、「小中一貫型小学校・中学校（仮称）の扱い」という項目があります。品川区は１０年以上前から、全ての小・中学校が一貫教育を実践しています。品川・生活者ネットワークも小中の一貫教育については賛成です。７年生から２クラス７０人もの子どもたちが、入学ではなく転入するという品川区の義務教育学校と、義務教育学校の本旨の整合性をどのようにつけるのか伺います。","respondent":"本城教育次長","answer":"そういう意味でも、標準的なものも当然しんしゃくしながら、あり方は検討していくというところは、当然ですけれども、品川区の都市型という特色を活かしたものも、義務教育学校として当然、国の想定の中でもしっかりと位置づけているものであると考えているものです。","voiceIndex":253,"id":"exchange-114"},{"speaker":"田中委員","kind":"質問","question":"品川区は都市型の義務教育学校ということなのですけれども、品川区の教育に国が追随してきたというお話が今までありました。それで、本旨の整合性はどのようにつけるのか、もう一度お答えください。そして、この質問です。なので、情報公開に１年かかるのは、やはり時間がかかり過ぎだというのを感じるので、ぜひそこを改善していってほしいと思います。","respondent":"本城教育次長","answer":"情報公開のこともあわせて、今お話がありましたが、それは先ほどご説明させていただきましたが、そもそも手続を始める時点で事務のおくれがあって、それも含めて全体として遅れてしまったことは、経緯等については請求された方にもご説明をさせていただいたところです。","voiceIndex":255,"id":"exchange-115"},{"speaker":"田中委員","kind":"質問・要望","question":"事務方の手続がいろいろあっておくれてしまったということなのですけれども、先ほども言ったのですけれども、事務方の手続というのは、どうしてそんなに手続が混乱してしまったのかとも思いますし、その辺はきちんと今回のことを踏まえて改善していってほしいと思います。市民が知る権利として有効活用できるように、丁寧な説明と、そして迅速な対応を、本当に早くしていただけるよう強く求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":257,"id":"exchange-116"},{"speaker":"鈴木（真）委員","kind":"提案","question":"区を取り巻く社会経済環境の変化は早く、複雑化しております。区民生活の向上を目指し、本委員会で我が会派委員が指摘・提案した、シティプロモーションの充実、介護人材確保と処遇改善、幼児保育拡充、感染症対策、防災対策、いじめ防止カウンセラーの配置、ＪＲ広町社宅跡地有効活用、そしてさらなる待機児童対策などの提案・要望を真摯に捉え、今後の施策に活かされることを要望し、意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":260,"id":"exchange-117"},{"speaker":"たけうち委員","kind":"提案","question":"最後に、本予算特別委員会で会派委員から提案・要望した、子どもの健康や避難所の拡充に資する学校トイレと公衆トイレの洋式化や、ワンストップの包括支援を行うための地域共生社会の構築、また今後の人口動向を踏まえた区有施設の有効活用、多子世帯への子育て支援の拡充、区道の無電柱化の促進、保育士や介護士へのきめ細かな処遇改善、障害児の放課後支援の充実。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":262,"id":"exchange-118"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"公共施設有効活用プランを継承して、統廃合、民間委託、区有地の売却まで行う姿勢を改め、区民要望に応える方針とすべきです。小山台住宅跡地や旧第一日野小学校跡、荏原第四中学校跡の活用、ニコン工場跡の購入も視野に入れ、特別養護老人ホーム、認可保育園、障害者施設、区営住宅、公園など、切実な区民要望に充てるよう求めます。中止を求めます。５月ではなく直ちに撤退するよう国に求めるべきです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":264,"id":"exchange-119"},{"speaker":"大倉委員","kind":"提案","question":"６年前の東日本大震災から得た教訓や、昨年の熊本地震から得た課題や教訓を今後の防災対策に反映し、より具体的で実効性に即したものとすることで、区民のさらなる安心・安全なまちづくりに取り組むことを求めます。最後に、今回の予算特別委員会において、我が会派の所属委員が質問の中で指摘・提案した各項目を真摯に受けとめ、予算執行することを強く要望し、民進党・無所属クラブの意見表明とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":266,"id":"exchange-120"},{"speaker":"須貝委員","kind":"提案","question":"さて、区内に年収３００万円以下の勤労者層が約８割にもなりますので、１００億円も予算が残るようなら、その一部でも低所得者層に充てる支援対策や、さらに大災害後に備えた復旧対策、待機児童対策、医療・介護などの高齢者対策等に重点を置くとともに、さまざまな生活支援を拡充していただきたい。最後に、我が会派の委員から提案された意見を活かしていただくことを要望します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":268,"id":"exchange-121"},{"speaker":"吉田委員","kind":"提案","question":"予算執行にあたり、各款別審査で生活者ネットワークが指摘・提案させていただいた意見を活かしていただくことを要望し、さらに、以下何点か意見を申し上げます。整合性を明確につけた予算立てが、わかりやすく示されることを要望します。総括質疑でも取り上げましたスピード感も含めて、情報公開をさらに進めることを求め、品川・生活者ネットワークとしての意見表明を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":270,"id":"exchange-122"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1068#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":120799,"voices":275}},{"id":"h29-20170327-10","meetingId":"h29-cm03","date":"2017年3月27日","dateIso":"2017-03-27","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"途中ですが、ただいまのご案内のとおり、予定表３その他の(3)東京都後期高齢者医療広域連合議会の報告","agenda":"途中ですが、ただいまのご案内のとおり、予定表３その他の(3)東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"飯沼副委員長","kind":"質問","question":"前回のときも、区市町村に向けてのアンケートが出されて、それに基づいて採決されたのだと思うのですけれども、広域連合の議会のところで、議員として意見を述べるような場があったのかどうか。前回欠席をされていると、今伺いましたけれども、議員として発言するような場は保障されていたのか、その１点だけ。","respondent":"本多議員","answer":"本会議ですと一般質問とかがあるのですが、臨時議会は一般質問はありませんので、質問はできないのですが、ただ、意見表明はできますので、この臨時会に向けて意見表明をされたという方が議事録を読んでわかりました。いらっしゃいましたので。","voiceIndex":13,"id":"exchange-001"},{"speaker":"中塚委員","kind":"意見","question":"問題のある法律の施行だと考えています。その上で、教育長という教育行政のトップを決める人事ですので、この間の実績を重く見ました。他区には見られない義務教育学校や、学校選択制や、小中一貫教育などを進める品川の教育改革は、抜本的な見直しが必要だと思いますので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-002"}]},{"id":"topic-02","title":"議事日程（５）および追加議事日程","agenda":"議事日程（５）および追加議事日程","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"文教委員会で第３１号議案と第３３号議案につきまして、前も申し上げましたが、大半の品川区民の勤労者の収入が上がっていない中、また区内の中小企業の経営が厳しい中、給与が上がるという今回の条例改正には反対いたします。ほかのものに関しては、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5216#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":10411,"voices":42}},{"id":"h29-20170414-10","meetingId":"h29-cm04","date":"2017年4月14日","dateIso":"2017-04-14","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特別委員会の調査事項等","agenda":"特別委員会の調査事項等","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"我々、品川区議会自民党・子ども未来は、次期の特別委員会について、２つの特別委員会を設置することをお願いしたいと考えています。それから、もう一点は、請願等も今は出てきておりまして、羽田空港の機能強化についても、行財政改革の中で取り扱っていくべきだろうということで、１点目は行財政改革特別委員会を設置するべきだろうと考えています。以上、２つの特別委員会をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"意見","question":"私どもの会派からは、３つの案を出させていただきました。前もってお話をしますと、３つありきではなくて、喫緊の課題、また、区議会として、今、近々に取り組むべき課題ということで考えたときに、この３つが出てきたということであります。この点については、後ほど、また委員長に整理していただければと思います。１番と３番については、先ほど自民党・子ども未来からもお話があったとおりの考え方です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-002"},{"speaker":"中塚委員","kind":"提案","question":"土木、建築、そして福祉分野等、横断的にまたがるテーマであり、特別委員会にふさわしいと思いますし、これも区民の要望が強いテーマだと思いますので、提案させていただきたいと思います。ご承知のとおり、深刻な背景を含め、学校や福祉分野など、こちらも横断的な課題や問題、そして緊急性も高いので、特別委員会としてふさわしいのではないかと思い、３つの提案をしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-003"},{"speaker":"あべ委員","kind":"提案","question":"私どもの会派からは、２つの特別委員会。名称としては、従来と同様です。再配置という言葉も入れしていますけれども、今ある施設をどのように活用するか、あるいは、新たに有する公有地をどう活用するかだけではなくて、区内全体のバランスを見ながら、その適正配置。せっかくですので、ある程度、一定の考え方を提案できるようなところまで進めていってもいいのではないかという提案です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"ならば、いっそ常任委員会の審議時間を増やし、集中的に議論をするべきだと思います。区にはこのような喫緊の重要課題があるにもかかわらず、これらを差し置いて別の課題を審議したり、区民要望がない課題に対して審議する事に疑問を感じますので、維新・無所属品川は特別委員会を設置することは反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"意見","question":"庁舎の修繕計画というのは、区有施設の１つでもあるので、１つの調査項目に庁舎の修繕計画も入れてもらう。それから、羽田は、これに関することということで、１つは入れておくべきだろうと思っておりまして、そういう仕分けをすれば、皆さんから出てきたものに対するところを我々はよしとできるのではないのかと考えていますので、そういう分け方をしていただければありがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"提案","question":"先ほど申し上げたとおり、私どもも、３つ立てなければいけないということではないです。委員会としては２つでもいいということで、地域共生社会という項目を立てましたけれども、今のご提案だと、行財政改革の中の基礎自治体のあり方についてというところ。今、立て分けしていただいた中に、区有施設のあり方というところで、それは公有地活用と組み合わせるというご提案をいただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"共産党としての希望は先ほどご説明したとおりで、今のご議論の中で一言だけ述べすると、羽田のルート問題ですけれども、調査事項の次にある備考、このテーマの中に区民への影響はぜひ入れていただいて、ご議論を深めていただくように位置づけていただきたいと思います。その１点です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"あべ委員","kind":"提案","question":"そうすると、幾つかの項目については、一、二回、さらっと資料説明で終わってしまうというものがまた出てきてしまう。その中でご質問をさせていただきたいのですけれども、自民党・子ども未来の基礎自治体のあり方について、これもすごくテーマとしては広いものだと思うのですが、例えば児童相談所の移管など以外のことは、どういう問題意識を持ってご提案をされているのか。いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"基礎自治体のあり方に関することとさせていただいた理由は、今後、最終的に児童相談所が動くと、５５対４５にいかに手を入れられるのかということが出てくる。予算特別委員会の総括で質問して、きちんと動き出せと言ったのはいいのだけれども、これは本当は入れようと思ったのだけれども、今年ではないかなと思ったから入れなかったというのが、我々、自民党・子ども未来の考え方です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"今、民進党・無所属クラブからご質問があった地域共生社会を入れ込む意味なのですけれども、国では、厚生労働省を中心にして、もう打ち出しがありました。人口動向と福祉を結び付けるというところを厚生委員会でやるのですかといったら、おそらくやらないと思いますし、総務委員会でやるのですかといったら、やらないと思います。あらゆるものが関係してくるので、１つの所管ではやりにくいところがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-011"},{"speaker":"あべ委員","kind":"提案","question":"どちらも非常に大きくて大切な問題ですので、特別委員会で扱うことは、やぶさかではないといいますか、全く反対するものではないです。これはまた別の議論、別の場での提案になっていくと思います。あるいは、議会全体で、まずは知識を共有する場ということを考えていってもいいのかなと。お２人から丁寧なご説明をいただいたので、そのように確認させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5218#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":14523,"voices":46}},{"id":"h29-20170421-6","meetingId":"h29-cm04","date":"2017年4月21日","dateIso":"2017-04-21","committee":"区民委員会","time":"午後 １時００分～午後 ４時３４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の順番では、初めに、(1)「荏原第四地域センター改修工事」","agenda":"の順番では、初めに、(1)「荏原第四地域センター改修工事」","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"それと、先ほどから戸籍住民課の業務委託、サービスの向上の説明や、組織改正も事務の効率化や待ち時間の短縮、混雑緩和等、説明がありましたけれども、業務委託の場合に、契約書と仕様書がその前提になるという形になりますけれども、契約書、仕様書の内容について、前提ではなくて実態として厳格に守られているという判断なのかどうか、この点を２つ目に伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"区民の皆様からの苦情ですが、証明類についての苦情は大きいものは聞いてございませんけれども、図書の取り次ぎサービスで２件ほど、少し時間がかかり過ぎるのではないかというような厳しいご指摘をいただきまして、最初の数日については、事業者のお客様のニーズといいますか。","voiceIndex":17,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"ということは、現状もまだ本部からの支援がなければスムーズに進まないという状況なのかどうか、さっき正確に数えればよかったのですけれども、そこまでじろじろのぞくのもどうかなと思ったので、正確な人数はわからないのですけれども、４人の倍ぐらいはいたのかなと思うのですけれども、その辺、現状をどう、どこがスムーズなのか、その点を伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"トラブルの報告と対応ということで、これも先ほど申し上げたとおり、図書の取り次ぎがうまくいっていないということで、区民の声のほうでも上がってきているのですけれども、同じ内容について、事業者のほうから、口頭および書面で報告が出ている形でおります。","voiceIndex":19,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"公務員には当然求められるスキルだと私は思いますけれども、短時間パートで、募集を見ると、時給１,０００円という待遇に対して、この仕事のスキルというのは、これに見合う待遇だと思うのか、仕様書どおりの規定が可能な待遇だと思うのか、この点を伺いたいと思います。民間委託の職員体制に対して、今は本部から応援が入っているということですけれども、業務体制表を伺いたいのです。","respondent":"提坂戸籍住民課長","answer":"待ち時間ですとか混雑状況のことですけれども、今は正直申し上げまして、２０日しかたっていないというところで、まだ少し、先ほど申し上げた図書の取り次ぎなどで時間をかけてしまうということがありますけれども、日々、待ち時間は短縮していると考えています。","voiceIndex":21,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"導入の目的に、待ち時間の短縮や混雑の緩和とおっしゃっているわけですから、先ほど伺ったのは、比較できる調査結果があるのかと質問させていただいたので、あるのかないのかご説明いただきたいと思います。","respondent":"提坂戸籍住民課長","answer":"先ほど、業務の体制ということで、私、説明不足だったのですけれども、業務体制表は間違いなく受託者のほうから提出いただいております。変更した体制表というのは、聞いていないので、それは出ていないかと思います。","voiceIndex":23,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"待ち時間の短縮の努力とおっしゃいますけれども、比較できる資料がないのに、どうそれを評価できるのか、今の説明ではとても納得できるものではないと思いますけれども、その点について伺いたいと思います。予算委員会でも伺いましたけれども、損害賠償とは、具体的に誰の何を賠償するのか、この点も改めて明確にご説明いただきたいと思います。","respondent":"提坂戸籍住民課長","answer":"費用は一切生じないとご説明したのは、資料項番１行政サービスコーナーの証明交付等業務委託のことではなくて、項番２の窓口案内の充実における本庁舎の窓口案内呼出機のことです。なので、ほかの備品等については、仕様書に書いたとおりです。","voiceIndex":27,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"特記事項に、いわゆる契約を解除することができるという規定があるのですけれども、つまり、各項目の１つでも違反があれば契約解除ができるという判断なのか、ひろまち保育園の例もあるだけに、特記事項にある各条項に違反した場合は契約解除することができるという規定ですけれども、１つの項目でも違反があれば契約解除ができると、そういう区の認識なのかどうか伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"１つの項目でも違反があれば契約解除できるかというお尋ねですけれども、内容も個々に様々なケースが考えられてありますけれども、総合的に判断して、たった１つの項目でも、その内容がかなり重い責任を負うようなものであれば、当然契約解除することもあり得ますし。","voiceIndex":29,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこを確認させていただきたいと思います。つまり、前回の説明でも、従事する人に対して必要な研修を行うとか、個人情報についての取り扱いを行うとか、先ほども言ったように、関係法令や区の条例についても精通している、これが人材派遣会社にお願いすることで、なぜ担保できるのか、私はとても疑問なので、それについても伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"プライバシーを扱うということで、それは正規の職員であっても、委託の従事者であっても、守秘義務等については何ら変わるものがあるものではございませんので、きっちりと誓約書も出してもらっておりますので、その辺は問題ないと考えています。","voiceIndex":31,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"人材派遣についてですけれども、先ほど聞いたのは、要するに、人材派遣は問題ないということでよいのか、それを確認させていただきたいのと、そうなった場合に、従事者に求められているスキルや個人情報等、様々守りますという誓約書を書く問題とか、そういうものを人材派遣会社に雇われているいわゆる派遣社員と言われる人に、どうやって担保させるのか、そこをご説明いただきたいと思います。","respondent":"提坂戸籍住民課長","answer":"今のところ、受託者が人材派遣会社から人を確保するということは想定していませんけれども、人材派遣の場合は、直接、指示命令等ができることなので、直接受託者が雇用した契約社員とかパートと同じ扱いであると考えます。","voiceIndex":33,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"事故が起きた際には報告がきちんと上がってくるように徹底がされているのか。雇用契約のことなのですけれども、前回、事業者とのやりとり、事業者との契約についてはお話があったのですけれども、事業者ではなくて、個々の事務従事者との雇用契約について、情報漏洩をしてしまった場合、事業者ではなくて、その個人がしてしまった場合はどうなるのかということを伺いたいのですけれども。","respondent":"提坂戸籍住民課長","answer":"雇用されている個人が情報漏洩をしたということで、それは当然、一義的には受託者のほうにも責任があるということで考えておりますが、最終的には区が行っている事業なので、区のほうにも責任があると思います。","voiceIndex":35,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"社会福祉法人での虐待事件がありました。そのときに区の対応がおくれて、虐待した本人が依願退職という形で退職してしまった、そんなことがありました。そういうことが起こるのはちょっと困ります。今後、情報漏洩は絶対に起きないとは言い切れないので、きちんと徹底してほしいのですけれども、その辺について伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"そういうことで、厳重に個人情報の保護には努めてまいりたいと考えております。","voiceIndex":37,"id":"exchange-010"},{"speaker":"こんの委員","kind":"確認","question":"参考までに確認というか、今までがこうで、今回、改善されてこうなりますというところをお聞きしたいのが、新しく設置をする庁舎内の呼出機の主な機能です。","respondent":"提坂戸籍住民課長","answer":"従来は、掲示板に番号が出るだけで、例えば高齢者ですとか障害者の方がそれに対してお気づきにならない等、その辺もありますので、その辺は職員が注意して直接お声かけをするとか、そういう対応をしてまいりました。","voiceIndex":39,"id":"exchange-011"},{"speaker":"こんの委員","kind":"確認","question":"そうすると、今お聞きしようと思っていた範囲内をお答えいただいたので、ということは、例えば戸籍住民課で申請をして、ほかの課も行かなければいけないというときに、持ち歩いていいという、そういうものなのか確認です。","respondent":"提坂戸籍住民課長","answer":"モバイルをお渡しするときに、例えば、聴覚障害者の方については、こちらについて光が出ますとか、振動しますということをきちんとご理解いただいた上でお渡しする形を考えております。","voiceIndex":43,"id":"exchange-012"},{"speaker":"こんの委員","kind":"質問","question":"わかりました。この端末みたいなものをお渡しするのは、台数が限りがあるので、今のところは高齢者、視覚障害者、そうした方々にということですが、それのほうがいい、スマートフォン等でＱＲコードを読まないで、こちらがいいというときには、細かいことですが、そういうものも対応を今後考えていかれるのですか。細かいことで恐縮ですが、そういうことも今後はあるのでしょうか。","respondent":"提坂戸籍住民課長","answer":"特に年齢で区別するというのは失礼かもしれませんけれども、若年層の方とか、スマートフォン等を持っているような方については、ＱＲコードを読み取って処理状況を確認できますということを説明して、そちらを活用していただきたいと考えています。","voiceIndex":45,"id":"exchange-013"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうしますと、この方は使えそう、この方は使えなさそう等、非常に判断は難しいかもしれません。確かにＱＲコードは便利なのですけれども、モバイル端末をもらうと便利だと思うので、今後、そうしたものが充実されるといいかと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-014"},{"speaker":"藤原委員","kind":"確認","question":"もしあるならば、役所としてどういう対応をしたのかということが１点目。３点目は、オリジナル婚姻届なのですけれども、区に愛着と親しみを感じるようなものをイメージしてこれからつくっていくと思うのですけれども、これ、課長がつくるのですか。誰がつくるのですか。あのマークはいろいろ簡単につけてはいけないというのはあるとは思うのですけれども、その辺についてはなかったのかについてお伺いします。","respondent":"提坂戸籍住民課長","answer":"ただ、印刷の技術は日々進化していますので、この書式をずっと永久に使うということではなくて、定期的に何年かおきに見直しをしなければいけないと考えていますので、その中でオリンピック・パラリンピックですとか、様々な要素が出てくると思いますので。","voiceIndex":48,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"改ざん防止で伺いたいのですけれども、よくこれをコピーすると、「複製です」等表示が出る、それはコピーしたから出るわけですよね。当たり前ですけれども、複製ですから。改ざん防止用紙というのはそれぐらいですか。それとも、何かいろいろ印刷している中で、名前、生年月日、住所等、何かをいじっても改ざん防止用紙は何か出てくるのですか。","respondent":"提坂戸籍住民課長","answer":"その辺を複数組み合わせて改ざん防止を施しております。","voiceIndex":50,"id":"exchange-016"}]},{"id":"topic-02","title":"戻りまして、(1)荏原第四地域センター改修工事","agenda":"戻りまして、(1)荏原第四地域センター改修工事","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"改修工事ということで、確認なのですけれども、荏原第四地域センターの耐震は何年か前、４年前にやっていますか。それを確認させてください。","respondent":"伊崎地域活動課長","answer":"こちらの荏原第四地域センターは昭和５７年６月の新耐震で建てております。なお、備蓄倉庫を兼ね備えております関係で、躯体部分はかなり頑丈につくったというふうに聞いております。","voiceIndex":56,"id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問・要望","question":"すみません、その確認です。計算したらぎりぎりかなと思ったので、１年後ですね。電気自動車給電ステーション整備と書いてあるのですけれども、これは要するに、今、１台止まっていますけれども、その車を電気自動車にしたときのための充電設備を設置しますということでしょうか。ステーションと書いてしまうと、ほかの人も使っていいですよというイメージになってしまうので、その確認をさせてください。","respondent":"伊崎地域活動課長","answer":"こちらの電気自動車の給電ステーション整備の意図としましては、今、防災計画の中で、地域センターを災害時の拠点としていこうとしておりますので、その一環として備えつけるものでございまして、昨年度４カ所、今年度も４カ所やっていく予定ですので、順次。","voiceIndex":58,"id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そういうものも一体的に考えた施設のあり方といいますか、先ほど課長がおっしゃったように、災害時の拠点となるところが、少しほかの地域センターに比べると狭いのではないかという感もあるので、公園も含めて、公園は都市計画法とか公園法とかあるので、様々あるのかもしれないのですけれども、それはやはり品川区がいろいろな手法を考えて、うまくそういうものができたらいいのではないかと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"荏原第四地域センター大規模改修工事ということですけれども、まだ利用されている方や地域の方への説明やご理解を得る努力について、前回伺いましたが、その後の状況について伺いたいのと、工事内容について、自家発電設備の設置ということで、先ほどの議論ですと、災害用ということですけれども、これは太陽光なのか、それとも燃料なのか、別の聞き方をすると、何時間分なのか。","respondent":"伊崎地域活動課長","answer":"利用者、地域の方々への説明ですけれども、主に区民集会所のご利用者ということになってまいりますが、前回の委員会でもご説明をしましたとおり、まず地域センターにはもう既に張り紙をして周知するともに、ご予約にいらしたときに１団体ずつ丁寧にご説明を差し上げています。","voiceIndex":61,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"４点目は、磁気ループについてなのですけれども、持ち運び式も大事ですけれども、大規模改修のときを捉えて、固定式でいつでもマイクを利用する際には磁気ループも使えるというふうに、耳の聞こえの悪い方への支援に向けて、ぜひ固定式の磁気ループを設置していただきたいと、前回、要望させていただきましたけれども、それぞれ４点について、どういう状況なのか伺いたいと思います。","respondent":"伊崎地域活動課長","answer":"ただ、今まで２階のだれでもトイレの扉が非常に開けづらかったということがありますので、だれでもトイレの扉は自動扉に変えるなど、バリアフリーについて対応していくということは考えております。","voiceIndex":63,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん持ち運びのコンパクトなものもありますけれども、やはり両方スクリーンをつけたほうが、現状もそうですし、これからを見通しても、当然必要になってくるのかと思うので、それを伺いたいのと、マイクについては、第１集会室も第２集会室もそれぞれ独立して使えるということなのでしょうか。例えば、今日の委員会ぐらいの規模の会議であっても、耳の聞こえの悪い方はなかなか聞こえないのです。","respondent":"伊崎地域活動課長","answer":"磁気ループにつきましては、おっしゃるとおり、障害者の方への合理的配慮というところで、様々な配慮が必要であることを担当としても認識をしておりますので、当区の全体の方針は、私のほうで今申し上げることは差し控えしますけれども、合理的配慮という中で。","voiceIndex":65,"id":"exchange-022"}]},{"id":"topic-03","title":"平成２９年度地域振興基金を活用した区民活動助成制度の審査結果","agenda":"平成２９年度地域振興基金を活用した区民活動助成制度の審査結果","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"何点かお伺いします。そもそもこれは、ここの目的のところに区内で公益活動に取り組んでいる区民活動団体を対象にということを書かれているのですが、これは所管においては、公益活動に取り組んでいる民間の活動団体を把握されて、こういう文章を書かれているのか、それとも、私たちは公益的な活動をしているであろうと言って手を挙げてこれに申し込んでくる方なのか、その辺を教えていただきたいです。","respondent":"遠藤協働・国際担当課長","answer":"回数ですが、平成２１年度から事業を開始しておりますので、今回が８年度目という形になります。次に、団体の把握ですが、多くの団体につきましては、すまいるネットというところに登録いただいたりしていまして、そちらのホームページで見ていただくような形になるかと思います。","voiceIndex":71,"id":"exchange-023"},{"speaker":"いながわ委員","kind":"質問・要望","question":"それをお答えいただきたいことと、やはり区民の方がこういう活動をしているのであれば、様々な助成金で何とか身銭を切らず、やっていこうという団体は多いと思うので、それを考えたら、もっと広く周知をしていただいて、みんながこういうものに共感してできる、もっと地域においてコミュニティを確立できるような支援をしていっていただきたいという思いが私にはあるのですけれども、いかがでしょうか。","respondent":"遠藤協働・国際担当課長、堀越地域振興部長","answer":"こちらの制度につきましては、企画して、最初の同じ事業につきましては３年を限度として助成させていただいておりまして、３年間で自分で自主的に活動ができるようにということでお願いしたいというところで、３年という形にしています。昨年度、申請の段階から、都のボランティアの関係の団体のホームページ等にも募集の要件を載せるような形で新たな取り組みも始めておりまして、予算額は４００万円ですが、これも３００万円からＰＲを強化して。","voiceIndex":73,"id":"exchange-024"},{"speaker":"いながわ委員","kind":"質問・要望","question":"増えていかないというのは、今もう３年を超えたら、ここには載ってこないということになっていると思うので、とにかく広く区民が交流できるような仕組みをつくっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-025"},{"speaker":"本多委員","kind":"質問","question":"簡単に伺います。今はいいですけれども、今後もし、こういうものがあったら、その団体がそれぞれどういう思いなのかをぜひ入れていただけると、我々も、区民もイメージしやすいなと思うので、それだけ教えてください。","respondent":"遠藤協働・国際担当課長","answer":"それぞれの団体の課題かと思うのですけれども、一般に育児に不安があるとか、それから、お１人の高齢者に対して、それぞれの団体が何かできないかというようなところが多かったように感じております。","voiceIndex":77,"id":"exchange-026"},{"speaker":"本多委員","kind":"質問","question":"今、答弁いただいた事業名を見ると大体わかるのですけれども、さらにその団体がどういうふうな思いなのかというのをぜひ、そういう思いをさらに細かく出していただけるとイメージしやすいので、ぜひお願いします。すごく細かいことを聞いてしまうのですが、９番に「しながわ箸の日イベント」とあるのですが、何月何日なのか、それだけ教えてください。","respondent":"遠藤協働・国際担当課長","answer":"８月４日です。","voiceIndex":79,"id":"exchange-027"},{"speaker":"伊藤副委員長","kind":"質問","question":"１点だけなのですけれども、これ、予算が４００万円です。地域振興基金の平成２７年の年度末の基金額は６億４,０００万円あるのです。だから、４００万円の上限でいいのかということです。だから、もう少し内容を拡大して、平成２７年度末の基金残高が６億４,０００万円、全部使えるわけではないのですけれども、やはりもっと様々な団体が参加しやすい制度をつくったらどうなのですか。","respondent":"遠藤協働・国際担当課長","answer":"こちらを原資として使っているようなことです。地域振興基金につきましては、区民の公益活動という形で条例でうたっているかと思いますので、こちらに沿った形で今後考えていければと考えています。","voiceIndex":82,"id":"exchange-028"},{"speaker":"伊藤副委員長","kind":"提案","question":"それは理解するのです。だけど、これだけ実際に使えるお金があるわけです、６億４,０００万円というお金が。だから、それは品川区の事業として正しいのかということを考えていくと、もう少し助成額をアップするなり、それぞれの事業を拡大するなり、検討してはどうですかという提案をしていますので、改めて答弁をお願い申し上げます。","respondent":"遠藤協働・国際担当課長","answer":"今までの実績として３００万円に満たない部分が多かったのですが、今回、３００万円を超える応募がありまして、４００万円にした効果もあったのかと思います。今後も推移を見ながら拡大していこうと考えています。","voiceIndex":84,"id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"以前から審査方法について伺っているというか、もっとオープンにしてほしいという要望をしているのですけれども、もっと区民の方たち等に開かれた審査方法だと、他の団体の方たちももっと参加しやすかったり、あと、審査を受けた団体の方たちも、審査状況を見た区民の方たちから意見を聞いて、もっと団体の行っている事業が磨かれたり等すると思うのです。その辺に関してご答弁いただきたいと思います。","respondent":"遠藤協働・国際担当課長","answer":"審査方法のオープン化というようなご質問かと思いますが、現在、公募の委員ということで２名は入れているところです。審査結果につきましては、ホームページ等で周知をさせていただいているところですが、さらに拡大ですので、それを含めて検討させていただければと思います。","voiceIndex":87,"id":"exchange-030"},{"speaker":"田中委員","kind":"意見","question":"すごく細かいことなのですけれども、審査基準の表記が、去年は表面というか、予算の上に来ていたのですけれども、なぜ今回に限って、選定事業の下に記載されているのか少し、わかりづらいかなと思いますけれども、見た方、こういう事業が気になっている方が気になるところは、やはり審査基準だと思うので、この位置というか、そこも検討していただけると良いと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"目的のところで伺うのですけれども、「地域の課題や社会的課題の解決に向けた事業」という意味では、これはそもそも行政がやる仕事だと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"遠藤協働・国際担当課長","answer":"行政として区民のニーズにこたえていくというのは確かに重要かと考えています。やらなくてはならない部分かと思うのですけれども、ただ、なかなか行政単独で細かい全てのものに対応していくのはやはり限界がある部分もあるのかなというふうに感じております。","voiceIndex":90,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"ですから、そういう意味において、細かいところというのはわかるのですけれども、私としては、協働という意味もあるかもしれないですけれども、それでもやる政策というか、やることはあるのかという疑問があるので、その辺についてもお伺いします。","respondent":"遠藤協働・国際担当課長、鈴木文化観光課長","answer":"各部署への報告、この行っている中身についての報告といいますか、きちんとした説明をというようなお話だったと思うのですが、こちらにつきましては、それぞれの担当の部署に、今、こういう団体がこういうような活動をしております。ただ、大きくすみ分けといいますか、どちらの制度を使っていただくという判断基準としましては、この地域での活動がご自分たちの地域の何か課題なり向上なりに資するという目的で活動されているのか。","voiceIndex":92,"id":"exchange-033"}]},{"id":"topic-04","title":"春季プレミアム付区内共通商品券発行事業への助成","agenda":"春季プレミアム付区内共通商品券発行事業への助成","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"このアンケートを今後とっていく際に、１,０００名にアンケートを送付したということなのですが、これは今回みたいな抽選ではない、今回２回目になると思うのですけれども、今度からアンケートをとるときは、当選しましたというはがきのところにアンケートをつけていただいて、引き換えにくるときにアンケートを引き渡したほうが、それを答えるのは自由なのですけれども、ある意味、回収率は上がって。","respondent":"山崎商業・ものづくり課長","answer":"当選者の引き換えにアンケートをというようなご提案につきましては、１つの取り組みの案として研究させていただけたらというふうに思っております。","voiceIndex":99,"id":"exchange-034"},{"speaker":"こんの委員","kind":"確認","question":"３点あります。仕組みをまず確認をしたいのですけれども、秋から事前申し込みという形でしましたけれども、抽選は、これはどういった形で行うのでしょうか。購入冊数を事前に書くわけですから、ある程度読めますよね。一次審査で抽選を獲得できた人と、だめだった人と結果が出る。その委任された人が引き換えに行くときに、本人確認をするかしないかという確認です。この３点をお願いします。","respondent":"山崎商業・ものづくり課長","answer":"秋は、やはり最初でしたので、私もその現場に行かせていただいて、説明を聞きながら区としても確認をさせていただきながらやらせていただきました。","voiceIndex":101,"id":"exchange-035"},{"speaker":"こんの委員","kind":"質問・要望","question":"今、次の秋の状況で、結局残りの部分というところを次にお聞きしようかなと思ったのですがご答弁いただけたので、そうすると、直接販売のときは、完売するまでやるという形ですけれども、残ってしまうというのは、やはりこれをどうにかしていかなければいけないのではないかと思うのですけれども、予算として確保して、区民の皆さんからは、アンケートを見ても。","respondent":"山崎商業・ものづくり課長","answer":"並んでいただいたときには、ちょうど完売してということなのですけれども、この方式ですと、どうすれば予算でぴったりといくのかというのは、なかなか研究するところがあって、少し許される、検討の中ですけれども。","voiceIndex":103,"id":"exchange-036"}]},{"id":"topic-05","title":"中小企業センター空調設備改修工事に伴う貸室利用停止","agenda":"中小企業センター空調設備改修工事に伴う貸室利用停止","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"確認なのですけれども、今、中小企業センター全館の冷媒というか、配管を全部変えるわけですね。全館は、５階、６階でしたか、介護福祉専門学校も入っての全館という表現なのか、そうなると、階数的には介護福祉専門学校、要は、全部共通の冷媒というか、お湯を通したり、水を通したりしているわけですから、当時のつくりからいくと、別にそこが分かれているわけではないわけですね。","respondent":"山崎商業・ものづくり課長","answer":"今日の報告は、中小企業センター諸室の貸し出しという観点ですので、そこは省かせていただいておりますが、学校のほうも５階と６階の機能を一定程度、春休み、冬休みなどの期間において、事務室を移したりしながら、５階と６階で互い違いに施工していくようなことで。","voiceIndex":109,"id":"exchange-037"},{"speaker":"中塚委員","kind":"意見","question":"ご説明いただいたのですが、意味がよくわからない部分があったので。９月１日から１１月３０日の３カ月間利用停止をする理由が、暑からず寒からずと言ったのは、クーラー、暖房が使えないことになると、部屋そのものが使えないということが今回の説明ですよね。それが暑いの寒いのとどう関係があるのかよくわからなかったのですけれども。","respondent":"山崎商業・ものづくり課長","answer":"ということですので、先ほど年度の後半の夏場から１２月までの間で工事ができますから、そのときに一番季節的に暑くなく寒くない時期ということになりますと、大体９月から１１月ぐらいの間だろう、中間期と俗に呼ばれておりますけれども。","voiceIndex":112,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"わかりました。今回、空調設備改修工事ということですけれども、簡単に言うと、中小企業センターはクーラーのききが弱かったり、かと思ってつけたらきき過ぎてしまったり、暖房もなかなかきかなかったり、かと思ったら暑過ぎたり、どうもうまくないなというのは使っていて感じるところだったのですけれども、今回の工事で何がどういうふうに改善されるのか、そこもご説明いただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"今まで空調改修をしていきながら、利用者の方々の快適なご利用空間を確保してまいりました。","voiceIndex":114,"id":"exchange-039"},{"speaker":"伊藤副委員長","kind":"確認","question":"何が言いたいかというと、こういう利用者の方々に対するほかの施設への誘導といったらいいのですか、つまり、自分たちの都合ではなくて使えないわけですから、だから、そういう方々に対しては品川区の連携の中で、品川区役所の会議室を紹介するとか、きゅりあんを紹介する等は行うのですかという確認です。","respondent":"山崎商業・ものづくり課長","answer":"もちろん産業関係の施設、例えば大崎の産業支援交流施設なども持っておりますので、そうした施設などの代替を考えたり、区のきゅりあん、スクエア荏原等。","voiceIndex":116,"id":"exchange-040"},{"speaker":"伊藤副委員長","kind":"意見","question":"優先はなかなかつけにくいですけれども、自分たちの都合ではなくて、品川区の都合で事業等できなくなるわけです。だから、そのことについては、様々、まさに地域振興事業と連携をとっていただいて、ある程度、優先的に品川区の他の施設を紹介してあげるなりしていったほうが区民サービス向上だと思いますので、検討してください。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":118,"id":"exchange-041"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"もう説明はあったかもしれないのですけれども、もう１度ゆっくりと答弁をいただきたいと思うのですけれども、本来だったら、情報漏洩が起きたときには、どのような手順が踏まれるはずだったのか。そこまでお願いします。","respondent":"提坂戸籍住民課長","answer":"本来、情報漏洩が発覚した時点で、申し出をして、即時、住民票の回収ですとか、個人番号が記載されている場合、その個人番号を変更する措置をとらせていただくということで、そのときの措置としては間違ったものではなかったのですが、事務上の引き継ぎ等が十分にされていなくて。","voiceIndex":123,"id":"exchange-042"},{"speaker":"田中委員","kind":"質問","question":"その事務上の引き継ぎがうまくいかなかった原因は何なのですか。","respondent":"提坂戸籍住民課長","answer":"事案が発生したことの処理経過ですとか、その辺の文書の保存が適切でなかった部分があったことが大きいところです。","voiceIndex":125,"id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"それが今回、情報が共有できていなかったというのは、すごく根本的な問題だと思うのですけれども、そこに対してなぜそのようなことが起きてしまったかということと、防ぐことができなかった危機管理に対して、今後どうしていくのかというところを伺います。","respondent":"提坂戸籍住民課長","answer":"システム上の措置としましては、先ほど申し上げたのですけれども、正式なＤＶ支援措置の申し出が出ている分については、既にシステム上のロックをかけておりましたけれども、正式なものでない今回のようなケースについても、システム上、ロックをかけて。","voiceIndex":127,"id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"正式でロックがかかるものと、そうでないものの違いを教えていただきたいことと、今回、民間委託になる前に、民間委託でない区での業務でこのことが起こっているのですけれども、そして、前回、課でこういうことが起きていたという情報が共有ができていなかったこと、どうして情報が共有されなかったのかという部分も含めてお伺いしたいと思います。","respondent":"提坂戸籍住民課長","answer":"ただ、そうとは言っても、ご本人の安全を確保するという面から、「処理注意」というアラーム表示をして注意を喚起していたものなのですが、その辺が欠けて発行してしまったです。情報共有化されていなかったというのは、結局、ごく限られた一部の職員で処理を進めていたです。","voiceIndex":129,"id":"exchange-045"},{"speaker":"田中委員","kind":"質問","question":"ごく一部の職員で処理がされてしまったということですが、それは単純に考えてやってはいけないのですよね。どうしてそのことが起こってしまったのかということと、今後、きちんと情報が共有されるように何か考えていらっしゃると思うのですけれども、その辺をお伺いしたいです。","respondent":"提坂戸籍住民課長","answer":"先ほど、課内研修を行ったということでご説明をさせていただきましたけれども、ＤＶ支援ですとか、個人情報が非常に重要であるということを、再度、戸籍住民課の職員だけではなくて、全庁的なこともありますので、地域センターの職員ですとか。","voiceIndex":131,"id":"exchange-046"},{"speaker":"田中委員","kind":"質問","question":"今回の方は、きちんと区からの謝罪があったので、もう大丈夫ですということをおっしゃられていたのですけれども、共有がされていなかったということは、それは正式な謝罪の文書ではなかったということになるのでしょうか。その辺を伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"その謝罪の文書というのが適切に保管されていなくて確認できなかったというのが事実です。","voiceIndex":133,"id":"exchange-047"},{"speaker":"田中委員","kind":"確認","question":"その文書については、相手の方から、こういう文書をいただいたので大丈夫ですということを情報提供として私たちは伺っていて、確認がとられているはずなのですけれども、そこも今は情報共有されていないということでしょうか。","respondent":"提坂戸籍住民課長","answer":"そういうことではございませんで、当時、謝罪文を出したときに、その辺の、はっきり申し上げて、決裁ですとか、そういうものがとられていなくて、それが保管されておらず２月の区民委員会のときにそれを探したのですが、見つからなかったということです。","voiceIndex":135,"id":"exchange-048"},{"speaker":"田中委員","kind":"質問","question":"ご答弁のとおりで、つまりは、うまく言えないのですけれども、隠されていたということで良いのでしょうか。","respondent":"堀越地域振興部長","answer":"要するに、担当職員では発行できないような、完全に機械処理上の「ロック」がかかるという形に加えて、ご相談中のものについても、「アラーム」表示で、担当職員で確認を慎重に行えば解除できるという形になっていて、「アラーム表示」。","voiceIndex":137,"id":"exchange-049"},{"speaker":"田中委員","kind":"質問","question":"アラーム表示だったものがこれからはきちんとロックがかかるようになったということはよかったと思います。それが今回、こういう形で情報共有もされていなかったことや、様々なことが明らかになり、その当事者の方がそれを知ってどう思うのかということについて私もとても納得がいかないというか、その方はとても苦しいなと思うのですけれども、その辺についてお伺いしたいと思います。","respondent":"提坂戸籍住民課長","answer":"以前、私がご説明を申し上げた際は、どなたの案件かということを把握していなくて、一般的に正式にＤＶ支援がされていた方については、システム上、ロックをかけたということでご説明して、今のようなケースということは把握しておりませんでした。","voiceIndex":139,"id":"exchange-050"},{"speaker":"田中委員","kind":"質問","question":"今回のことで、当事者の方への謝罪をどう考えるのかということと、民間委託される前にこういうことが起きていて、事故も隠されてしまっていたという事実がある中で、これから大井町サービスコーナーの窓口だったり、これから民間委託をしていくという中で、この評価はどのように行っていくのかということと、もう今、大井町サービスコーナーも始まってしまったので、これから目黒の新規事業、民間委託など。","respondent":"提坂戸籍住民課長","answer":"事業者の場合は、画面表示を見て、こういう表示が出ていたら、ロックがかかっている以前に、疑義が生じたということで、これは、即刻、事業者は携わらないで、区の職員に引き継いでいただいて、その上でサービスコーナーの場合でしたら、ロックを解除することはできませんので。","voiceIndex":141,"id":"exchange-051"},{"speaker":"田中委員","kind":"質問","question":"そういう徹底をきちんとしてほしいことと、重ねてになりますけれども、今回、区でこの情報が隠されてしまっていた場合、今度、民間になった場合、もっと何かが起きたときに情報が上に上がってこないのではないかということを懸念しています。そんなことはないと思いたいのですけれども、その辺の対策について伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"民間委託は始まってありますけれども、あくまでも受付ということなので、そこには必ず区の職員が常駐しておりますので、そこで情報が上がってこないということは考えてございません。そこで必ず事故を未然に防ぐ形で万全を期したいと考えています。","voiceIndex":143,"id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"なので、その辺をしっかりとやってほしいと思います。事業者との雇用の契約でも、もしも情報が漏洩したときの従事者との雇用契約について等、その辺をしっかりともう一度ご答弁いただきたいのですけれども、お伺いします。","respondent":"提坂戸籍住民課長","answer":"万一従事者が、情報漏洩とか、そういう不祥事を起こした場合は、まず一義的には区から受託者に対してその辺の事実確認をしてもらって、それで不祥事ということが確認されれば、雇用契約の打ち切りということも当然ありますし、その上で区は受託者に対して処分を行う。","voiceIndex":145,"id":"exchange-053"},{"speaker":"田中委員","kind":"意見","question":"こういうことがあったので、民間委託というか、危機管理が徹底される、情報が共有されること等、そういうことがしっかりしてからまた次の段階として民間委託という感じで、今はまずここの構築をしっかりされることが先決だと思うので、そこのところを頑張っていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":147,"id":"exchange-054"},{"speaker":"中塚委員","kind":"質問","question":"ロックがかかっていれば係長が対応、これはわかります。アラーム表示があるのに、なぜ発行をしてしまったのか、その原因が今のご説明ではわからなかったので、もう一度そこを伺いたいと思います。２点目は、マイナンバーは変えたと、ご本人の対応も含めてやりとりは伺いましたけれども、ただ、被害に遭われた方にしてみれば、出てしまった個人情報を取り戻すことができたのか、この点も伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"それと、個人番号についても、先ほど申し上げましたけれども、即時変更したということで、被害は起きていなかったと把握しております。","voiceIndex":148,"id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"アラーム表示が出ているけれども、住所と名前は確認ができるのでしょうけれども、アラーム表示あるのに、なぜ交付してしまったのか、ここをご説明いただきたいと思います。２つ目は、実質的被害はないということですけれども、出てしまった情報を取り戻すことができなかったということなのか、この点も伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"情報は、住民登録している住所とは実際には別のところに居所としていたということなので、取り戻すというか、被害は受けなかったということで、こちらのミスは申し訳ないですけれども。","voiceIndex":150,"id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"すみません。平成２７年１２月ということで、対策としては、結果としてアラームではなくて正式なものでなくてもロックをするというご説明がありましたけれども、起きたのが平成２７年１２月で、その対策を実施したのはいつか、これだけ最後にご説明いただきたいと思います。","respondent":"提坂戸籍住民課長","answer":"大変申し訳ございません。今回の事件を把握をしたのが区民委員会の後なので、その後の対策として、アラーム表示をしている相談中の案件が１００件ほどありましたので、そちらを３月中に全件ロックをかけさせていただきました。","voiceIndex":154,"id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"わかりました。平成２７年１２月に起きた事態が、対策が実施されたのが、田中委員に指摘されるまで、なぜ対策が検討されなかったのか、ここが２つ目の問題だと思うのです。もちろん担当者がかわっているとか、そういう問題ではなくて、平成２７年１２月に起きた事態の対策が、なぜ今になってしまったのか、指摘がされるまでなぜ対策を打つことができなかったのか、そこは率直に答弁をいただきたいと思います。","respondent":"提坂戸籍住民課長","answer":"それは大変申し訳ございません。実際、ごく一部の職員で処理されていて、情報の共有化がされていなかったので、その辺の対策がなされていなかったです。","voiceIndex":156,"id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2778#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":51962,"voices":159}},{"id":"h29-20170421-7","meetingId":"h29-cm04","date":"2017年4月21日","dateIso":"2017-04-21","committee":"厚生委員会","time":"午後 １時００分～午後 ４時２４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)障害児施策","agenda":"はじめに、(1)障害児施策","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"「にじのひろば」の利用料が高いというのは様々ご意見を伺っていましたので、こういう形でこの児童福祉法の支援事業に準じたという形になって良かったと考えています。もっと利用したいという方が増えた場合のキャパシティーというか、受け入れのキャパはどれくらいあるのかについてもお聞かせいただきたいと思います。","respondent":"中山障害者福祉課長","answer":"戸越に移転することで少しキャパが広がったということでは利用人数の調整が多少可能ということと、新しくつくります障害児者総合支援施設の中にも日中一時支援につきましては、今のところ定員２０名ということで予定をしているものです。","voiceIndex":24,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"続いてお聞かせいただきたいのが、２ページ目に利用料が軽減される例として1)、2)、3)とありますけれども、登録は７１名で６８名が現在利用されているということなのですが、1)、2)、3)それぞれでおおよそ何％ぐらいの利用となっているのかということと、2)の一般１で、これは所得割区民税が２８万円未満ということなのですけれども、これは世帯収入換算でどれぐらいかの年収にあたるのか。","respondent":"中山障害者福祉課長","answer":"予算要求の段階ではおおむね１,０１６万７,０００円程度を予定しております。なお、こちら区だけの単費なのかどうかという負担の割合になりますが、この事業は地域生活支援事業の位置づけにしております。","voiceIndex":26,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"支援力の強化ということで、職員体制が専門職を配置をするということで、多分職員増ということにもなるのだと思うのですけれども、現在の職員体制と、今回専門職を配置したということでどう変わるのかということを教えていただきたいのですけれども、現在の八潮・荏原における職員体制が何人体制で、どういう体制を敷いており、資格などはどうなっているのかということと、今回。","respondent":"中山障害者福祉課長","answer":"以前は八潮の常勤が２名ということでしたので、そこで１名増えていることと、それから係長職で事務系の職員がついていたのですが、福祉系の職員がコーディネーターとして１名配置することで、より支援に力を入れていきたいと考えています。","voiceIndex":28,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"職員体制が専門職を配置するということで、具体的には資格がはっきりしない。どんな資格の人が何人かというのを含めて、よくわからなかったのですけれども、はっきり教えていただきたい。","respondent":"中山障害者福祉課長","answer":"今回は子どもがいらっしゃる前の午前１０時ぐらいからの出勤ということで勤務形態を変えておりますので、子どもがまだ来る前の段階で、そうした研修ですとか、今日のプログラムをどういうふうにやるかという話し合いなどを行う時間がとれましたので。","voiceIndex":30,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ということは、社会福祉主事が１名増えるということと、臨床心理士の方が研修を充実させられる、そしてまた研修ができるような時間帯まで勤務していただけるように変わるということで、職員は、具体的には子どもが来る時間からだけではなくて研修ができる時間帯からの勤務ということで、研修などに割ける時間も増えるということと、具体的にもう１人職員が増えるということなのでしょうか。","respondent":"中山障害者福祉課長","answer":"わかりにくい説明で申し訳ございません。八潮のほうは常勤が１人増えております。コーディネーターは一応専門職ということで、事務系の職員から１名切りかわったということで、実際に支援の現場にも入るということになっております。","voiceIndex":32,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"おおよそわかりました。ただただ預かる時間だけでなく、そういう研修時間も保証されるというのはすごく大きなことだと思いますし、それがやりがいにもつながっていくということにもなるかと思いますので、ぜひ充実していただけるようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-006"},{"speaker":"浅野委員","kind":"質問・要望","question":"２点ほどお伺いしたいのですけれども、今回、荏原から戸越に移転をするということで、子どもたちにとってはある意味大きな変化かなとも思われるのですけれども、子どもたちはこういう変化というのは慣れているのか、それとも少し気をつけて対応しなければならない子どもがおられるのかどうかということについて１点教えていただきたいのと。","respondent":"中山障害者福祉課長","answer":"まだその許可がおりていない状況ですので、ちょうど角にあたる、戸越の閉店してしまったイトーヨーカドーがあるのですが、あそこの横のラインにとめさせていただいて、そこからはほんとうにすぐそばですので、職員が付き添って「にじのひろば戸越」までご案内をする予定です。","voiceIndex":36,"id":"exchange-007"},{"speaker":"たけうち委員","kind":"確認","question":"２つありまして、まず、確認が１つです。それから登録料が５,０００円ということなのですけれども、この登録料というのは考え方としてどういう位置づけになるのかということで、これは１回登録すればいいのか、それとも１年に１回なのかということ、また、ないと思いますけれども、登録をやめたときにこれは返金されるのかなど、登録料の考え方を教えてもらえますか。","respondent":"中山障害者福祉課長","answer":"１点目の八潮の利用料金体系ですが、同じように負担軽減措置はします。それから登録料の考え方なのですけれども、これは年間でいただいているものです。","voiceIndex":39,"id":"exchange-008"},{"speaker":"安藤副委員長","kind":"質問","question":"それと、このガイドブックのほうですけれども、これは単純なわからないことなのですけれども、例えば都立港特別支援学校や都立矢口特別支援学校の記載がないですけれども、やはり子どもをみるに当たって将来のこともやはり考えると思うので、ここに一体的にあるほうが自然なのかなと思うのですが、記載がないのがなぜなのかということと、それと放課後等デイサービスですけれども。","respondent":"中山障害者福祉課長","answer":"１点目の負担の差についての考え方です。確かに「にじのひろば」は完全に無料化しているわけではございませんので、ご利用に合わせた負担ということでかかってはきてしまいます。","voiceIndex":42,"id":"exchange-009"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"すまいるの場合はやはり月３,０００円ぐらいで区が一定かかわって、そういった子どもの放課後育成支援ということでやっているのですが、まだまだそういった意味では、障害をお持ちのお子さんがいらっしゃるご家庭ですと、かなりの負担が強いられてしまうという課題はあると思いますので、ぜひこれからさらに負担軽減を図っていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-010"}]},{"id":"topic-02","title":"後期高齢者医療保険料軽減判定におけるシステムの誤り","agenda":"後期高齢者医療保険料軽減判定におけるシステムの誤り","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この厚生労働省のプレスリリースの中でも、２ページの(3)の一番最後に、「個々の事情を伺いながら丁寧に説明した上で本来の保険料を納付していただきます」と記載されているのですけれども、５４名と７名、合わせて６１名の方に対する区としての対応は、どういう対応をされるのかということと、それから額によってはちょっと大変な方というのもいらっしゃると思うのですけれども。","respondent":"三ツ橋国保医療年金課長","answer":"６１名の方に対してはどのように区は対応していくのかという部分ですけれども、４月１７日に発送した通知の中で、実際にはこのような状況の内容と、あとは状況に応じまして分割納付を、その方その方の状況によりますけれども、分納のご相談も応じますということは伝えております。","voiceIndex":49,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"保険者側のミスというところで追加徴収という形になるわけですので、電話など、電話で内容についてわかるのかどうかわからないのですけれども、そういう手段も含めて、やはり、保険者側のミスであるにもかかわらず一遍の通知だけでいいのかという思いがしているのですけれども、その辺は丁寧にやる必要があるのではないかと思いますが、その点どうでしょうか。","respondent":"三ツ橋国保医療年金課長","answer":"５４通プラス７通の発送をしておりますけれども、今のところその５件につきましては、どういう内容なのですかということを聞かれていまして、そのときに丁寧に説明した結果、納得していただいている状況です。","voiceIndex":51,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、平成２０年からずっと間違えたまま来ていて、そこまでは遡らないで平成２７年度、平成２８年度だけをこういうふうに対応するという考えで、平成２０年度から平成２６年度までの分というのは、もうそのまま遡らないですよと、そのままにしてしまいますとなりますと、追加徴収の方は別にしても、還付される方というのも、平成２０年度から多く払い過ぎた分は。","respondent":"三ツ橋国保医療年金課長","answer":"増額更正を行うなど徴収の部分というのは、様々な法律上決まっていることがございまして、その関係で平成２７年度、平成２８年度となっております。","voiceIndex":53,"id":"exchange-013"},{"speaker":"横山委員","kind":"確認","question":"１点だけ確認させてください。保険料の正しい計算方法に関する問い合わせをきっかけに今回認識をされたということで、問い合わせのあった広域連合に対して個別に回答するということで、平成２３年以降対応してきたということなのですけれども、そちらの再発防止について、複数の担当者による確認を徹底するということなのですが、この辺少し詳しく教えていただけますか。","respondent":"三ツ橋国保医療年金課長","answer":"このシステムは税法上の部分を用いていたようで、ちょっと説明するとかなり細かいことになってしまいますので詳しくは申し上げませんけれども、実際に繰越年分を税法上の部分を勘案していたということになっております。","voiceIndex":56,"id":"exchange-014"}]},{"id":"topic-03","title":"の３、所管事務調査","agenda":"の３、所管事務調査","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"今検討中の部分があるということで、そちらのところはまた結果が出ましたらその段階で確認させていただきたいと思うのですけれども、まず１点目が、こちらの事務運用の検討というところで、平成２９年度中の検討課題に入っているのですけれども、東京都と品川区で事務の連携ですとか会議体ですとか、その辺はどのように考えていらっしゃるのでしょうか。","respondent":"三ツ橋国保医療年金課長","answer":"こちらに3)としてお示ししておりますのが課内の部分でございまして、東京都との関係ですが、主管課長会がありまして、そちらの中で様々な東京都から報告事項などを受けております。","voiceIndex":62,"id":"exchange-015"},{"speaker":"横山委員","kind":"質問","question":"主管課長会でご報告をいただくということでお聞きしました。それは一方的にというか、一方向的に、都のほうから区のほうに情報がおりてくるという形でよろしいのでしょうか。区のほうからＰＴや広域化対策委員会で挙がったことに関して、都と双方向的に話し合うような場は、今年度中に想定されているのでしょうか。","respondent":"三ツ橋国保医療年金課長","answer":"一方、品川区からの要望ですけれども、実際に主管課長会の中でもお話ししていくこともできますし、２３区全体のことですので、例えば主管課長会の中で、「うちの区はこういうふうに考えているのだけれども」という討議の部分がありますので、意見交換の中では示していく予定です。","voiceIndex":64,"id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"ありがとうございました。主管課長会で双方向的な意見交換などをしていただいて、２３区全体のお話ではあるかと思うのですけれども、やはりそれぞれの区で、今までのスタンスですとか、実際の運用方法ですとか、異なる部分というのはやはり出てくるかと思います。できる限り、品川区のやり方・要望を都に伝えていただくとともに、２３区全体でもうまくいくような形で要望をお願いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"国民健康保険の制度改正ということで伺いました。","respondent":"三ツ橋国保医療年金課長","answer":"実際、その内容が、第２期の加算・減算の実施方法の中で、上位保険者の１、２％だということで、そこまでなかなか品川区は受診率の向上がされておりませんので、該当はしていないのですけれども、引き続き受診率の向上に向けて対応してまいります。","voiceIndex":68,"id":"exchange-018"},{"speaker":"浅野委員","kind":"確認","question":"健診の受診率はぜひとも今後とも向上しいっていただければと思いますので、その点は引き続きよろしくお願いしたいと思います。このような中で、例えば２３区とか都下の市町村も含めまして、それぞれの代表が集まって全体で論議をするとか、それぞれが平等だと確認できるような、そのような考え方で会議をするということも必要かという気がしますが、これについてはどのような動きがあるのか教えてください。","respondent":"三ツ橋国保医療年金課長","answer":"これから標準保険料の算定をするに当たって、おそらく各区独自にそういうものが出てくる可能性があると思いますので、２３区の先ほどの主管課長会でありますとか、また特別区長会の中でも検討はしていると思いますので、そのあたりで平等性についても意識はしていってまいります。","voiceIndex":70,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう既に１万５,０００円もの保険料の値上げになるという、高過ぎる保険料が問題になっているときに、さらに保険料を高く押し上げたのが、この法定外繰入の高額療養費等を保険料に置きかえるという仕組みでしたから、それに加えて法定外の繰入金をさらに保険料にかえていくということが、これから都道府県化によって圧力になって。","respondent":"三ツ橋国保医療年金課長","answer":"国民健康保険の主管課長会であるとか、また東京都などの状況を踏まえて、いち早く情報をキャッチしながら対応してまいりたいと考えています。","voiceIndex":73,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はできればそれに加えて、今まで削減した高額療養費等まで繰入金で賄うというところまでしていただければ一番良いのですけれども、そういうところもぜひしていただきたいというのは要望になりますが、少なくとも今入れている法定外の繰入金はそのまま残すというところを、ぜひ意見として言っていっていただきたいというふうに思いますので、その辺のところもこれからだというふうになると思いますが。","respondent":"三ツ橋国保医療年金課長","answer":"運営方針につきましても区の意見等は、実際にどういうふうに上げるのか、２３区の要望として上げるのか、そのあたりもはっきりと今ここで明確にお答えできませんけれども、必要に応じて申し入れてまいります。","voiceIndex":75,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど私が一番初めにお聞きした、法定外の繰入金がどんな項目があってそれぞれ幾ら出されているのかというのは、今手持ちがないということなのですけれども、次回でも結構ですし、資料としてぜひ厚生委員会に示していただきたい。法定内の繰入金も合わせて示していただきたいというふうに思いますけれども、その点も含めてお願いします。","respondent":"三ツ橋国保医療年金課長","answer":"手持ち資料がないのですけれども、ざっくり申し上げますと、法定内、法律の範囲内ですけれども、例えばそれは７割、５割、２割の軽減料になっている、それの交付金の補填されるという部分が法定内と認識しておりまして、法定外と言いますのは、保険料の算定について。","voiceIndex":77,"id":"exchange-022"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"実際に何回開かれたのか。もう１つは、説明資料の図のところでリスクを回避できるというのがあるのですけれども、そのリスクとは、医療給付費の支払いが収入状況によりできなくなる可能性があるのだと書いていますけれども、こういった、実際に払えないということが過去にあったのでしょうかというのをお伺いしたいのと、常にリスクを抱えているということであれば、なぜ今までは回避できたのでしょうか。","respondent":"三ツ橋国保医療年金課長","answer":"はプロジェクトチームの活動に関しましては、実際に動いている状況です。月に２回程度、国保医療年金課のメンバーが集まりまして、各係から選出した精鋭が集まって検討しております。","voiceIndex":80,"id":"exchange-023"},{"speaker":"安藤副委員長","kind":"質問","question":"リスクを回避できるというのがメリットだとなっているので、それは今までやはり、例えば繰入金をしてきたとか、区としてそうした努力をしてきたからリスクを回避してきたということなのですかということをお伺いしたいので、よろしくお願いします。","respondent":"三ツ橋国保医療年金課長","answer":"リスク回避の点ですけれども、委員ご指摘のとおり、一般繰入金の部分で回避できていると考えています。","voiceIndex":82,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この資料の1)の紺色の枠の中の一番下のところなのですけれども、都は国保の運営方針を定め、市区町村の事務の効率化と書かれているのですけれども、区にとってどういったことが事務の効率化になるのかなという思いがするのですけれども、なるとしたらどんなところで効率化が具体的に図られるのか。","respondent":"三ツ橋国保医療年金課長","answer":"事務の効率化というものが、様々な場面で今検討中ですけれども、実際に東京都の中で違う区に移った場合に、資格はそのままで適用はその区になるですので、資格そのものが変わらないという部分で事務の効率化が図られることが１つだと考えています。","voiceIndex":85,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3474#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":26301,"voices":92}},{"id":"h29-20170421-8","meetingId":"h29-cm04","date":"2017年4月21日","dateIso":"2017-04-21","committee":"建設委員会","time":"午後 １時００分～午後 ２時４９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２９年５月都営住宅入居者募集","agenda":"平成２９年５月都営住宅入居者募集","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"すみません、ちょっと細かいことで、気になったことをお伺いしたいのですけれども。４の募集住宅２,４００戸で、1)で世帯向となっているのですけれども、これは単身者向と世帯向という言い方で区別はあるのですか。募集の要綱などを見ると、家族向と単身者向とかと普通なっているのですけれども、単身者向としていることに何か今までとの違いみたいなものがもしあるのであれば教えてください。","respondent":"長尾住宅課長","answer":"こちらは、今までの制度と変わるものではございませんので、世帯向と書いておりますが、ご家族向のファミリータイプということになります。こちらは世帯向となっておりますので、単身者向に関しては原則入っていないです。","voiceIndex":27,"id":"exchange-001"}]},{"id":"topic-02","title":"大崎三丁目地区（大崎駅西口Ｆ南地区）等の再開発計画","agenda":"大崎三丁目地区（大崎駅西口Ｆ南地区）等の再開発計画","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今ご説明いただいた大崎駅西口Ｆ南地区、先ほど先般説明会も住民にされたということで、１５９名参加されたということですけれども、ここでの住民の皆さんの反応とかはどうなのだったのかなというのをまず一つ聞きたいのと。ちょっとこの事業について、事業費とか補助金の予定の入れる額はどれぐらいかとかはもうわかっているのか、いれば教えていただきたいと思います。","respondent":"稲田都市開発課長","answer":"説明会で参加された方の反応です。私は出席していないのですが、私どもの係長と担当主査が前回出席いたしまして、その報告を受けました。","voiceIndex":34,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"私も説明会に参加された方からお話を伺ったのですが、建物の、別紙２の３ページを見たときに、こんなに高くなるのだと、大変驚かれていましたし、ここで初めて知る方が多かったということでした。それで先ほど、その間のところで、また住民の皆さんへの説明会を行いますみたいなお話があったかと思うのですけれども、そこがどこなのかもう一回ちょっと伺いたいと思います。","respondent":"稲田都市開発課長","answer":"先般実施した説明会以外に、一番最後の１１ページをご覧いただきますと、本日と書いてありますその次に矢印的な四角で都市計画原案の検討というところがありますが、その次、都市計画原案の縦覧というのがあります。","voiceIndex":36,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、この１１ページの予定が書かれていますけれども、これは本日というのが、説明会ということなので、要は４月１３日とか１４日とか１６日だということですよね。何年何月がこの都市計画原案の縦覧で、何年の何月が公告・縦覧で、というふうに月日がわかるようにならないですか。","respondent":"稲田都市開発課長","answer":"最終的に一番目指しているところは、都市計画決定・告示というところが、この事業化との間にありますけれども、１１月頃決定できればいいかなというところで、組合のほうもそのような認識を持っているところです。","voiceIndex":38,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"とても早いペースでだんだんだんと進んでいってしまうのかなというところなのですけれども、この準備組合、今加入率はどれぐらいになっているのか。それからあと、この開発事業の保留床と権利床の割合というのはどんな感じになっているか伺いたいのですが。","respondent":"稲田都市開発課長","answer":"準備組合への加入状況です。全権利者、先ほど２７名のうち２４名が加入しておりまして、加入率が８８.９％です。保留床等そういうところにつきましては、細かいところはまだ決まっていないです。","voiceIndex":40,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"この保留床とか権利床の割合のところは大体、この間開発をずっと進めてきているわけですけれども、どれぐらいにわかってくるのか伺いたいのと、あと保留床というのはどなたがどれくらいを、どなたが取得されるのかというのを伺いたいです。","respondent":"稲田都市開発課長","answer":"保留床を誰が持つかというところにおきましては、様々な保留床を持つ方もおられると思いますが、組合が持つ保留床というのもあって、あと参加組合員が持つ保留床もあるです。","voiceIndex":42,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこら辺はちょっと今後も保留床等が権利変換の段階で決まってくるということですので、そこら辺をお聞きしていきたいと思いますけれども、やはり住民への丁寧な説明、まあ説明されても、本当にこれだけ町の形が様変わりしている地域というのは、この品川区内でも大崎になってくるわけですので、９月頃の都市計画案の公告・縦覧の前に住民説明会をやられるということですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-007"},{"speaker":"筒井委員","kind":"意見","question":"Ｆ南地区ですと、日影が左隣の芳水小学校に一部かかっているのですけれども、このＦ南地区の開発によって芳水小学校の児童とかそうした関係者の方々がどういった影響を受けるのか、また現時点でどのようなお声が出ているのか、それもわかる範囲でお教えください。","respondent":"稲田都市開発課長","answer":"最終的な事業の完了、工事の完了というのでしょうか、におきましては、これから都市計画決定や組合の設立、そういったことが関わってきますので、なかなか何年度というのは今のところ難しいところですが、一般的に言えば、このような進捗でいきますと。","voiceIndex":45,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"たしかこの西口は開発するときに途中から入ってきたような気がしたのですけれども、その経過、それから考え方は、時期的に、経過によっていろいろ変わっていくというのはわからないではないのですが、何か今までやってきたことを一部変更をするということになると、当初の計画と大幅に変更になる部分もあって、それをどういうふうな関係でこういうふうな開発が進んでいるのかというのを教えてください。","respondent":"稲田都市開発課長","answer":"その西口におきましては、今回やる部分を後から追加したという考えではございませんで、西口地区も平成６年あたりには大崎駅西口地区まちづくりの方針的なものをやって、全部で６地区割り当てをつくっているのです。","voiceIndex":49,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"そこで、なおかつこれにかぶせるということになると、どういう関係があるのかなということがちょっと不思議になっているということと、それから西口Ｅ西地区、これは明電舎とということなのですが、この明電舎との連携という意味ではどういう連携を考えられるものか、どういうことでここが入ってきているのかというのを教えて下さい。","respondent":"稲田都市開発課長","answer":"ここが東京都のマンション再生に関する調査の対象地域になったということで選ばれてきたのですけれども、再開発におけるマンションの再生はどうしたらいいかということで、ちょうど再開発を検討する地区になりましたので、東京都のほうからそういう調査を依頼されて。","voiceIndex":51,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"１つ目のほうなのですが、マンションの検討ということなのですが、その進め方は今回の西口Ｆ南地区のほうはここで進められていて、隣のほうは、駅側に近いところというのはそういう再開発準備組合等をつくっていくわけではなくて、何か違う方向で進めていくのでしょうか。それと、明電舎もどういう関係で、明電舎は明電舎の土地であるならば勝手にできるはずではないですか。","respondent":"稲田都市開発課長","answer":"一緒に建物を建てるというところではございませんけれども、歩行者ネットワーク、そういうこと等においても連携をしていけたらというところで、現在検討しています。","voiceIndex":53,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"なぜこれをしつこく聞くかと言うと、説明会資料の４ページの右側の図のところに将来接続検討となっているのです、大崎地区と。この大崎周辺というのが、要は大崎駅との接続部分というのが連携的に考えられていて、この図を見るとＦ南地区との将来接続検討というふうになっているのです。なので、どういう関係性を持ってやっていくのですかと、それが気になったのです。そこをお願いしたいと思います。","respondent":"稲田都市開発課長","answer":"ご指摘のとおり、まちづくりとしましては駅前からこの西側の地区につながる西口駅前地区におきましてもそういうところは重要ですので、今の準備組合段階でも区のほうも指導というか調整等を行って、西口一体的なまちづくりができるように調整をしています。","voiceIndex":55,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"大崎地区、本当にこれからどんどんまだまだ開発が進んでいくのだろうと思って期待はしているのですけれども、ただ広くなれば関係性も広がっていくわけであって、いろいろな考え方が出てくると思うのです。それから、人間関係がきちんととれてないとうまくいくものもいかなくなりますので、何が言いたいかわかるかと思うのですけれども、そこをしっかり進めていただきたいという意見で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問","question":"再開発ということで、荏原町の駅前も整備が終了して、あそこも旗岡八幡神社、神社仏閣があるという中で、今回の再開発もまさにこの居木神社とお寺が隣接しているということで、別紙２の資料の４ページを見ますと、準備組合が計画、こういった事業概要だと思うのですけれども、風格ある参道空間の形成ということで。","respondent":"稲田都市開発課長","answer":"これはあくまでもイメージです。","voiceIndex":58,"id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そういうことを含めて、これは区としての観光資源というか関連した話になりますけれども、観光にも属するのではないかと思いますが、その辺の区のお考えをお聞かせいただきたいと思います。","respondent":"稲田都市開発課長","answer":"今回参道を整備し、また緑道でつながるというようなところも考えておりまして、また今後その辺の発展が期待されればいいなと考えています。","voiceIndex":60,"id":"exchange-015"},{"speaker":"塚本委員","kind":"意見","question":"説明会資料の２ページで、施設計画のところでの生活支援施設で保育所等、また店舗となっていますけれども、この辺の導入について、保育所はどのぐらいの規模のものになるとかという話が今の段階でどんな感じなのかというところと、あと店舗というのは地元ニーズ等というのはどのくらい活かされてきているのかというところをお聞かせください。","respondent":"稲田都市開発課長","answer":"子育て支援施設ですが、これは今組合と話をしておりまして、子育て支援施設の導入をするということになっています。ただ、細かなところというのですか、床の大きさとかそういうところはまだこれから詰めていくものです。","voiceIndex":62,"id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"保育所等の規模については、今再開発とかをしていくと、ほぼ間違いなくと言っていいほど保育所が設置されますが、基本的には３９階によって大きく人口が増えるということは予想されるわけで、その増加分というところを見込んで設置の規模というのを見ていくのか、あるいはもっと地域の保育需要みたいなものを広く見て。","respondent":"稲田都市開発課長","answer":"保育をどうしていこうかですが、関係各課に説明する中で、保育関係部署のほうからもここに保育の施設が欲しいという意見はいただいております。今後、そのマンションだけなのか、地域も含められる大きさにできるのか、その辺等は今後の調整でやっていきたいと考えております。","voiceIndex":64,"id":"exchange-017"},{"speaker":"塚本委員","kind":"意見","question":"いずれにしても、これからというところではあるかと思いますけれども、今課長のご答弁があったとおり、地域の連携とか庁内での連携とかということを強めながら、皆さんが本当に良かったなと思えるような形で進めていっていただけるようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"住居ではなくて事務所が増えることによって、大崎駅、今すごいですよね。さらにまたこれで事務所が増えてきたときに、ＪＲとの関係というのは、その辺の話し合いは計画の中でついているのかどうか気になっているのと、ちょっと忘れてしまったのですけれども、地下に入る短絡線、あのようなものもどうなっているのか、ちょっと含めて教えていただければと思います。","respondent":"稲田都市開発課長、中村都市計画課長","answer":"ＪＲも何もやっていないわけではございませんで、ホームドアの設置もやっております。それから混雑時には警備員等を立てているところです。ＪＲの混雑につきましては、今都市開発課長が申し上げた対応をやっておりますので、引き続きＪＲのほうにもそういった混雑解消に向けた取組みを行っていただくように、区のほうからもお願いをし続けているところです。","voiceIndex":69,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問","question":"道路側を通っても、ホームの混み具合がわかるのですけれども、何かそれこそホームドアがないと、一番道路側のほう、これでは危ないなと普段から思っているので、その辺の折衝というか計画、これからの線路の状況によってはまたホームドアをつくることによって変わってくるのかとも思うのですけれども、何かその辺のホームドア的なものの情報は入っていないでしょうか。","respondent":"中村都市計画課長","answer":"ただ、区といたしましても、万一のことを考えて、やはり万一の安全に対しても対応していただきたい旨はＪＲのほうには申し伝えてあります。引き続きこれも同じく申し入れを行っていきたいと思います。","voiceIndex":72,"id":"exchange-020"}]},{"id":"topic-03","title":"住宅耐震化緊急促進アクションプログラムに基づく耐震化促進","agenda":"住宅耐震化緊急促進アクションプログラムに基づく耐震化促進","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"国のほうから補助金が、助成金が、拡充していくためには戸別訪問をしてこのアクションプログラムに基づいてやっていくということだったと思うのですけれども、対象になる戸別訪問をする住宅というのはどれぐらいあるのか。そしてそれを４か年でということですけれども、どれくらい、１００％を目指しているのか、年間目標みたいなものはあるのか伺いたいと思います。","respondent":"鈴木建築課長","answer":"それを３か年に分けるわけですが、当然目標としましては、この４,０００棟を３か年かけて全て回るという予定です。","voiceIndex":78,"id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それは引き続きこれを続けていくのか、その方の要望に合った形がとれるのかとか、そういったことは今後になってくると思うのですけれども、そういったことはどのように考えているのかなということと、あとこの戸別訪問をされる方、訪問する人は、区の職員なのか、委託したりとかしてしてもらうのか、何人ぐらいで取り組もうとしているのか教えてください。","respondent":"鈴木建築課長","answer":"戸別訪問の回る体制ですが、これは委託を使って、今現在プロポーザルで委託業者を決定する予定です。","voiceIndex":80,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"そもそも国がこうした助成金を出すというところから始まった事業、もともと品川区が木密のところでも１０年プラン、そういうのとかの中にあったわけではなく、国からこういうのがあるよと来たから、では品川区でやろうというふうになったということなのですか。","respondent":"鈴木建築課長","answer":"これは昨年度末の、本当に予算ぎりぎりのところで話が出たところですので、２３区で手を挙げていないところもあります。ただ、区としてはそういった拡充策を受けて、早急に内部で検討して、積極的に活用して耐震化を図っていきたいということで取り組んでいくものです。","voiceIndex":82,"id":"exchange-023"},{"speaker":"西本委員","kind":"提案","question":"やはり信頼ある形で、アンケートを取るにしても話をするにしても、やはり区のほうの証明のある方、ただ何かそういうものをつくると簡単に真似されてしまうことがあるので、何か工夫しないと、確実に区の関係者が来ているのだということが何かわかりやすいようにしなければいけないのではないかなと思うのですが、そこはとても気になりますが、いかがでしょうか。","respondent":"鈴木建築課長","answer":"３点目の委託業者の守秘義務といいますか、これは当然選定に当たってはそういった個人情報を含めた情報の管理の徹底というのは当然図っていきますし、実施に当たっては戸別訪問の実施計画、実施マニュアルというものも区の管理のもと作成して行います。","voiceIndex":84,"id":"exchange-024"},{"speaker":"西本委員","kind":"提案","question":"それで、なかなか、ではどうするのといった場合に、具体的な提案をしづらい部分だと思うのです。近隣の何とか不動産に聞いたらどうでしょうということは言えないではないですか。では、そこの建築というところまでどうやったら持っていけるのかというのは、区の態度としてはちょっとチャレンジャブルな部分に入っていってしまう可能性もあるのですが、ここをちょっと研究していただきたいなと。","respondent":"鈴木建築課長","answer":"それからあと、セキュリティーあるいはその後のいろいろなそういったご自身の意向をどこまで開示して示して、それがあるいは犯罪ですとか違う方向に使われる恐れがないかどうか。これは以前も品川区を語って無料診断を今実施中ですというときもありました。","voiceIndex":86,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、そういう気持ちがない、アンケートだからいろいろ出てくると思うのですが、ここの重要なことは、そう考えていない人たちに対してどうでしょうか、前向きに考えていきましょうと誘導していかなければいけないというのが大きな柱になってくると思うのです。なので、いろいろと職員の方も一緒に何回か経験をしながら実行していただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-026"}]},{"id":"topic-04","title":"平成２９年度サマールックキャンペーンの実施","agenda":"平成２９年度サマールックキャンペーンの実施","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"それを強化期間とするということで、軽装というのは要は上着を脱いでネクタイを外すということを区としては軽装と言っているのですか。ポロシャツになるとかそういう、スーパーがつくと何なのだろうとちょっと思ってしまっただけなのですけれども、そこら辺を伺いたいと思います。","respondent":"小林環境課長","answer":"抗議とかということではございませんで、昨年度環境課で週に１回、より軽装を意識した取組みとしまして、課で統一したポロシャツの着用を行ってまいりました。職員から、区の取組みとしてより強力に啓発活動を図ろうといった意見がございました。","voiceIndex":93,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"その調整というのを環境課がある程度調査して、そこは一応２８℃となっているけれども、環境によってはもうちょっと温度的には下げてもいいのではないかとかという判断というのはどこが、環境課が私はやるべきだと思っているのですけれども、全体把握がどうなっているのかなというのが一つ。それと、このチラシのエコラ、これは誰が考えたのですかねと。","respondent":"小林環境課長","answer":"エコラにつきましては、これは私が知っている範囲で申し訳ないのですが、区の職員が考えたものと聞いております。","voiceIndex":95,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"何かその情報を投げかけ、やってくださいはいいのですけれども、ではそれがどうだったのか。この庁舎もそうですよ、この庁舎は職員の方々が働きやすい部分は必要だと思うのですけれども、でも区民の方々が出入りする場所でもあるので、その快適さというのもきちんと情報をとったほうが今後の対策にいいのではないかなと思うのですが、いかがでしょうか。","respondent":"小林環境課長","answer":"委員ご指摘のとおり、温度がどうかという把握まで我々のほうは実は今しておりませんが、今後、関係所管いろいろとありますので、調整をしながら進めていきたいと考えております。","voiceIndex":97,"id":"exchange-029"}]},{"id":"topic-05","title":"しながわＥＣＯフェスティバル２０１７の開催","agenda":"しながわＥＣＯフェスティバル２０１７の開催","exchanges":[{"speaker":"塚本委員","kind":"意見","question":"イベントの特色で、2)来場者への“もったいない”の意識付けというのを今回初めての取組みとしてやっていただくということで、これは会派としても訴えてきたところでありますので、この意識付けの啓発がどんどん進むということは非常に歓迎したいと思います。","respondent":"小林環境課長","answer":"小盛り等の量の調整ですが、容器の大きさは変わる予定ではなくて、各ブースのそばにこのお店では量の調節ができますよということをお示しした上で、その容器の中で小盛りになるとか、そういったところの量の調整だけをするところでまずは始めたいと考えているところです。","voiceIndex":103,"id":"exchange-030"},{"speaker":"塚本委員","kind":"質問・要望","question":"量がすごく多いものを提供していて余る人が多いというようなことであれば、多いけれども大丈夫ですかみたいな声を積極的にかけるというのは効果的かなと思うのですけれども。その辺で運営するサイドの人に、出展する側の人にも意識を啓発していただきたいと思うのですけれども、そういうことは今回出展を募るに当たってぜひやっていただきたいと思いますが、いかがでしょうか。","respondent":"小林環境課長","answer":"はお声がけすることも一つの手段ですし、やはり見える化するということも一つの手段かと考えておりまして、それをまずはやって、今年度の反省をまた来年度活かしていくというようなところで取組みを進めていきたいと考えております。","voiceIndex":105,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"サービス精神だと安くてたくさん食べていただきたいという思いがあるのではないかと、提供する側としてはあると思うのですよね。そうすると、かなりフードロスがなくなっているという検証も今出てきていて、なので、一声かけることによって、やっぱり食べようね、物を大切にしようねという意識付けになると思うので、そちらもあわせて考えていただきたいなと思うのですが、いかがでしょうか。","respondent":"小林環境課長","answer":"今年度はまず初年度ですので、実際にどういった対応をされたかというのはちょっと検証しながら、次年度以降何かうまく活かせないかというふうに考えていきたいと考えています。","voiceIndex":107,"id":"exchange-032"}]},{"id":"topic-06","title":"平成２９年度品川区・区内三消防署合同水防訓練の実施","agenda":"平成２９年度品川区・区内三消防署合同水防訓練の実施","exchanges":[{"speaker":"西本委員","kind":"確認","question":"すみません、１点確認ですが、７の（２）、七消防署と一緒にやるのが隔年であるということです。それで、今回はその年ではないので三消防署とやるということでよろしいですか。","respondent":"川部防災安全担当課長","answer":"委員ご指摘のとおりでございまして、当区と大田区、輪番で第二消防方面本部との連携訓練をやっておりまして、昨年度当区がやりましたので、今年は大田区が第二消防方面本部との連携をされるです。","voiceIndex":113,"id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"今までと場所が変わるということで、２枚目、別紙に図を載せていただきましたけれども、大体この西大井広場公園でやっていたときと同じなのか。ちょっと工夫して新しい場所だから変わったところがあったりするのか、伺いたいと思います。","respondent":"川部防災安全担当課長","answer":"今回は、概算ですが、消防団・消防署員が約８０名減になっておりまして、今回この会場でその規模で訓練を実施させていただきまして、その次の方面本部との連携に耐え得るような訓練となるのかどうか、その辺のほうも推奨事項、検討事項等を鑑みまして。","voiceIndex":115,"id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"今回ここのしながわ中央公園の多目的広場を使ってということですけれども、そうするとずっとここになっていくということなのでしょうか。","respondent":"川部防災安全担当課長","answer":"これも、先ほどご回答申し上げたことに関連してくるのですが、訓練の規模等を鑑みまして、もし今回やってみて、例えば面積が足りない、導入する消防車両がちょっと物足りないということであれば。","voiceIndex":117,"id":"exchange-035"},{"speaker":"塚本委員","kind":"意見","question":"今のにちょっと関連するのですけれども、西大井広場公園から比べると狭くなるわけですよね、規模も縮小でやると。それはそういうふうにせざるを得ない部分もあるというところなのですが、そういう中でこのしながわ中央公園多目的広場で今回やろうということにした、こちらでやろうとする積極的な理由というのはあるのか、それをお聞かせください。その辺をもう少しお聞かせください。","respondent":"川部防災安全担当課長","answer":"それと、新しい防災拠点ができたということをこの周囲の皆様にご認識いただくためにも、ぜひこちらのほうでやってみたいということで企画をさせていただいたです。","voiceIndex":119,"id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"確認","question":"念のためなのですが、これはチラシなど町会長に配るものに、場所が変わりましたと当然書いてあると思うのです。そのまま向こうに行かれては心配なので、そこら辺、町会長会議を使ってでもやっぱりもう一回言っておいてもらいたいなと思うので、確認です。","respondent":"川部防災安全担当課長","answer":"委員ご指摘のとおり、今回まず一つの重点といたしましては、皆様に配付させていただきましたご案内通知に、昨年と会場が変更となりますのでご注意くださいというようなただし書きを加えさせていただきました。","voiceIndex":121,"id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ぜひお願いします。それを町会長が見ることによって、場所を見ていない方が、この近くの方は見ていらっしゃるけれども、せっかくつくった広場を、この公園を各町会の会長にも見てもらいたいと思うので、ぜひその辺もよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問・要望","question":"関連してなのですが、私もちょっと心配です。多分私もこれを今日聞かなかったら西大井広場に行っていたのではないかと思うのですけれども。そういう方々のお知らせ、入口が何カ所かあると思うのですけれども、そこに張れませんかね。やはり防水訓練といったらもう西大井広場というふうに頭が固まってしまっているものですから、なのでそこら辺も工夫していただきたいなと。これは意見で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4198#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":33360,"voices":133}}]);
